import Action     from "./Action.js";
import Command    from "../Command.js";
import Constants  from "../../std/Constants.js"; 
import Util       from "../../std/Util.js";
import SolarSystem from "../../animations/SolarSystem.js";
import FrameFixer from "../../traj/FrameFixer.js";

// This is the superclass of commands which compute a set of basic
// trajectory commands and insert them into the sequence.  
//
// It handles issues of whether we need to ravel and unravel orbits as
// we change frames.  Implementing classes need to have the computeAction
// and addCommands methods.  The first computes the interval over which
// the trajectory changes are implemented and the basic information for them.
// The second actually inserts them into the sequence.  The separation is required
// since we may need to ravel and unravel the orbit immediately before and after
// the computed commands.

class CalcAction extends Action {
    constructor(ptr, anim, traj) {
        super(ptr, anim, traj);
    }
    
    // Transfer from the current orbit to the requested orbit.
    // In terms of actions this simply add generated commands to the queue.
    execute(forced) {
        if (this.anim.delta > 0) {
            this.initiate();
        }
    }
    
    initiate() {
        const keys = this.args.keyvals;
        if (!keys.dest) {
            this.anim.setQuickHTML("No destination set for trajectory: "+this.constructor.name+" command ignored");
            return;
        }
        
        let here = this;  
        
        function startTransfer(params) {
            // Handle this with an instance level function in the
            // basic command class.
            here.runTransfer(params);
        }
        this.getOrbit(this.time, [keys.dest], {}, startTransfer);
    }
    
    // This unravels the orbit before we do the trajectory calculation.    
    doRavel(orb, off, time, ravelling) {
        let seq = this.traj.sequence;
        let args = "";
        let sign = "";
        if (!ravelling) {
            sign = "-";
        }
        let prefix = sign + off+" ";
        let infix = "";
         while (off > 0) {
            args = orb.primaryName + infix + args
            off -= 1;
            infix = " ";
            orb = orb.prime;                
        }
        args = prefix + args;
            
        let orbcmd = new Command(time, "orbit", args);
        orbcmd.setGenerated(this);
        seq.add(orbcmd);

    }
    
    checkRotation(destOrb, time) {
        // Check for a landing...
        if (destOrb.isRotation || (destOrb.primaryName && destOrb.sec.isRotation)) {
            
            let rot = destOrb;
            if (!destOrb.isRotation) {
                rot = destOrb.sec;
            }
            // Get the latitude and longitude of the rotation object to use
            //  in the REST command.
            let lon = Util.toDegrees(rot.l0);
            let lat = Util.toDegrees(rot.b0);
            let primary = destOrb.primaryName;
            let cmd = new Command(time, "rest", "primary="+rot.body+" site="+lon+","+lat);
            return cmd;
        }
        return null;
    }
    
    runTransfer(params) {
        let currOrb = this.traj.rocket.traj.traj; 
        let destOrb = params.orbit;
        
        // We may want to do the calculation in a specific frame.
        let ff = new FrameFixer();
        let frame = ff.findFrame(currOrb, destOrb);

                // Are we going to need to unravel or ravel?
        let startOff  = ff.findOffset(currOrb, frame);
        let endOff    = ff.findOffset(destOrb, frame);
        
        let gm = ff.findMass(frame);
        currOrb = ff.convertToFrame(currOrb, frame);
        destOrb = ff.convertToFrame(destOrb, frame);
        
        // Compute the requested action using the original orbits.
        let compAction = this.computeAction(currOrb, destOrb, gm);
        
        Util.log("Command '"+this.constructor.name+"' computed in frame:"+frame);
        
        if (startOff>0) {
            this.doRavel(currOrb, startOff, compAction.t0, false);                
        }
        this.addCommands(compAction);
        
        // The rest command will handle the ravelling if needed.
        let cmd = this.checkRotation(destOrb, compAction.t1);
        if (!cmd) {
            if (endOff > 0) {
                this.doRavel(destOrb, endOff, compAction.t1, true);                
            }
        }
        
        if (cmd) {
            cmd.setGenerated(this);
            this.traj.sequence.add(cmd);            
        }
    }
    
    // This is where the calculation for the action is actually done.
    // This should return the a structure:
    //   {t0:beginning of the action,
    //    t1:end of the action,
    //    data: data needed for the action
    //    }
    computeAction() {
        throw new Error("computeAction not overriden in "+this.constructor.name);
        
    }
    addCommands() {
        throw new Error("addCommands not overriden in "+this.constructor.name);
    }
}

export default CalcAction;
