import Action from "./Action.js";
import Util   from "../../std/Util.js";

class loop extends Action {

    constructor(ptr, anim, traj) {
        super(ptr, anim, traj);
    }
    
    execute(reverse) {
        let traj     = this.anim.frame.traj;
        let offset = 30*86400;
        if (this.ptr.elem.forward) {
            try {
                offset = Util.parseDuration(this.ptr.elem.forward);
            } catch (exc) {
                Util.log("Invalid interval ignored in loop: "+this.ptr.elem.forward);
            };   // Just use default
        }
        if (offset < 1) {
            offset = 1;  // Go to at least 1 second before the start of the script.
        }
        let wantTime = traj.sequence.start() - offset;
        let newStage = "before";
        Util.log("Looping animation.");
        if (traj.rocket) {
            traj.delRocket(true);
        }
        if (traj.invoker) {
            traj.invoker.setState({stage:newStage});
        }
        if (traj.rocketController) {
            traj.rocketController.setState({stage:newStage});
        }
        traj.lastStage = "before";
        traj.returnTime = wantTime;
        this.anim.time = wantTime;
        
        // Clear the direction flags for the commands.
        let curr = this.ptr;
        while (curr.elem.command != "START" ) {
            curr.elem.direction = 0;
            curr = curr.prev;
        }
        
        this.anim.setQuickHTML(null);
    }
}

export default loop;
    
