import PlanetarySystem from "./PlanetarySystem.js";
import SolarSystem     from "./SolarSystem.js";
import Void            from "./Void.js";
import LocalGalaxy     from "./LocalGalaxy.js";
import Galaxy          from "./Galaxy.js";
import Galaxies        from "./Galaxies.js";
import Clusters        from "./Clusters.js";

import ssData          from "../data/PlanetaryData.js";

// Singleton class to manage the animation instances.
class AnimationFactory {
  
    constructor(){
        this.cache = {};
        this.available = {};
        let pls = ssData.Sol.planets;
        for (let planet in pls) {
            this.available[planet.toLowerCase()]      = 1;
            // We have animations of moons for which we have rendering textures.
            for (let moon in pls[planet].moonInfo) {
                let m = pls[planet].moonInfo[moon];
                if (m.render && m.render.texture) {
                    // We have an image so we allow an animation of this moon.
                    this.available[moon.toLowerCase()] = 1;
                }
            }
        }        
        this.available["solar system"]                = 1;
        this.available["abell clusters"]              = 1;
        this.available["galaxy"]                      = 1;
        this.available["the milky way"]               = 1;
        this.available["interstellar void"]           = 1;        
        this.available["nearby galaxies"]             = 1;
        this.available["local galactic neighborhood"] = 1;
        this.available["the earth and environs"]      = 1;
    };
    
    getAnimation(name, args) {
        
        name = name.toLowerCase();
        
        if (name == "the earth and environs" ) {
            name = "earth";
        } else if (name == "the milky way") {
            name = "galaxy";
        }
        
        if (!this.cache[name]) {
            switch (name) {
              case "mercury":
              case "venus":
              case "earth":
              case "mars":
              case "jupiter":
              case "saturn":
              case "uranus":
              case "neptune":
              case "pluto":
                let capName = name.substring(0,1).toUpperCase()+name.substring(1);
                this.cache[name] = new PlanetarySystem(capName, args);
                break;
                
                                               
              case "solar system":                    
                this.cache[name] = new SolarSystem(args);
                break;
                
              case "interstellar void":
                this.cache[name] = new Void(args);
                break;
                
              case "local galactic neighborhood":
                this.cache[name] = new LocalGalaxy(args);
                break;
                
              case "galaxy":
                this.cache[name] = new Galaxy(args);
                break;
                
              case "nearby galaxies":
                 this.cache[name] = new Galaxies(args);
                 break;
             
              case "abell clusters":
                 this.cache[name] = new Clusters(args);
                 break;
                 
            }
            
        }
        return this.cache[name];
    }
    
    // Is this a valid animation name?
    isAnimation(name) {
        return this.available[name.toLowerCase()];
    }
    
    // Has this animation been loaded?
    isLoaded(name) {
        return this.cache[name.toLowerCase()] != null;
    }
}
const singleton = new AnimationFactory();

// Export the instance not the class.
export default singleton;