/** This function solves Kepler's equation to find
 *  the eccentric anomaly as a function of the mean anomaly.
// For orbits with eccentricity near 1 we need
// to be careful when MA is near 0 or Pi.  There is a vast art on this
// problem but for the nonce we are using a simple abd likely inefficient
// approach.  All types of orbits are nominally supported, but parabolic orbits
// are treated as extremely eccentric elliptic orbits.
 * 
 */
 
import Constants from "../std/Constants.js";
import Util      from "../std/Util.js";

let ONEP = 1+3*Number.EPSILON;

let errCnt = 0;

//These are used when profiling usage, or debugging...
let usageCnt = 0;   // Number of time Kepler has been called.
let limitCnt = 0;   // Total number of loop iterations in all calls.
let iterCnt  = 0;   // Number of iterations where boundary test yielded better answer
                    // than extrapolation.
let exit1     = 0;  // Eccentricty=0
let exit2     = 0;  // Exact, or 0 range
let exit3     = 0;  // Ran into min/max constraint
let exit4     = 0;  // Exact hit on bisection
let exit5     = 0;  // Extrapolation doesn't change value
let maxIter   = 0;  // Maximum number of iterations.

let totalError = 0; // The sums of the absolute differences between input ma and ma returned
                    // for computed value of ea.

// Usage:
//   eccentricAnomaly = Kepler(meanAnomaly, eccentricty);
// This should work for any non-negative eccentricity and
// any value for the mean anomaly.  A simple iterative process
// combining Newton's method and bisection is used.  Each iteration
// calls Kepler's equation twice and its derivative once or twice.
 
// In testing on 2026/01/19 we found the maximum number of
// iterations required was 54 and the average number of iterations required
// was about 3.63 for first 100 million invocations for solar system orbits.
// The maximum value likely reflects the pessimal case of bisection being
// used at every step so that each iteration builds one bit of precision.
// For elliptical orbits the eccentric anomaly is returned in the range 0 - 2PI,
// while for hyperbolic orbits the return value may be any real value.

// The average error (defined here as the difference between the desired mean anomaly
// and the mean anomaly returned by Kepler's equation for the returned value of
// the eccentric anomaly) is measured as 2.9e-17.   Likely this is due to the digitization
// of the real numbers, so that we often get 0 measured error.
const Kepler = function(ma, ecc) {
    usageCnt += 1;
//    if (usageCnt % 10000000 == 0) {
//        console.log("Invocations: "+usageCnt+" maxIter:"+maxIter+
//                "  limitCnt: "+limitCnt+"   AvgIter: "+(iterCnt/usageCnt));
//        console.log("   Exits:", exit1, exit2, exit3, exit4, exit5, 
//              (exit1+exit2+exit3+exit4+exit5-usageCnt));
//        console.log("Average Error:", totalError/usageCnt);
//    }
    
    if (ecc == 1) {
        ecc = 1 - 1.e-10;  // Treat parabolic orbits as very large ellipses.
    }
    // Want to check if there is a non-neglibible difference
    // between min and max.  Note that min<max (e.g., so if min>0, max>0)
    // While we can have min or max = 0, we cannot have them be
    // different signs, since we limit the range to one side
    // of the origin immediately.
    function hasRange(min, max) {
        if (min > 0) { 
            return min*ONEP < max;
        } else if (max < 0)  {
            return max*ONEP > min;
        } else {  // Either min=0 or max=0
            // 2.2250738585072014e-308 is smallest normalized float.
            // In principle we could deal with unnormalized numbers,
            // but likely will have issues with roundoff.
            return min < -3*2.2250738585072014e-308 || max > 3*2.2250738585072014e-308 ;
        }
    }
    
    
    // Check arguments.
    if (ecc < 0) {
        throw new Error("Illegal eccentricty for Kepler:"+ecc+" at MA="+ma);
    }
    if (isNaN(ma) || isNaN(ecc)) {
        throw new Error("NaN argument to Kepler (ma,ecc):"+ma+" "+ecc);
    }
    
    // Set the functions to be used and initial bounds of the iteration.
    
    // Define the functions that transform the eccentric anomaly to the mean anomaly.
    // The form is a little differenct for elliptical and hyperbolic orbits.
    let fma;
    let fdma;
    
    if (ecc > 1) {  // Hyperbolic orbit
        fma = function(ea, ecc) {
            return ecc*Math.sinh(ea) - ea;
        };
        fdma = function(ea, ecc) {
            return ecc*Math.cosh(ea) - 1;
        }
    } else {      // Elliptical orbit
        fma = function(ea, ecc) {
            return ea - ecc *Math.sin(ea);
        }
        fdma = function(ea, ecc) {
            return 1- ecc*Math.cos(ea);
        }
        // For periodic orbits set the range to 0 to 2*PI.
        if (ma < 0 || ma > 2*Math.PI) {
            ma = ma%(2*Math.PI);
            if (ma < 0) {
                ma += 2*Math.PI;
            }
        }
    }
    
    if (ecc < Constants.SHAPE_RATIO) {
        // Circular orbit, so ma = ea = ta
        exit1 += 1;
        return ma;
    }
    
    
    let eaTest = ma;

    // Now we just iterate till we converge.  For elliptical orbits we know
    // that if ma is between 0-pi, or pi-2pi, then ea is
    // in same range so we can set initial boundaries: emin,emax.  For hyperbolic orbits we have 0
    // as one bound and then effectively use either plus or minus infinity.
    let emin, emax;
    if (ecc < 1) {
        emin = 0;
        if (ma > Math.PI) {
            emin = Math.PI;
        }
        emax = emin + Math.PI;
        
    } else {
        // The maximum value for the true anomaly is acos(-1/e), but
        // the eccentric anomaly is not constrained,
        // so we set the limits to rather large values.
        
        if (ma <= 0) {
            emin = -1.e10;
            emax = 0;
        }  else {
            emin = 0;
            emax =  1.e10;
        }
        if (Math.abs(ma) > 2*Math.PI) {
            eaTest = Math.asinh(ma/ecc);            
        }
    }

    // Probably not needed, but could be extreme tail of hyperbolic
    // orbit.
    if (eaTest > emax) {
        emax = 2*eaTest;
    }
    if (eaTest < emin) {
        emin = 2*eaTest;
    }
    
    
    
    // What's the outcome using our initial guess?
    let maTest = fma (eaTest, ecc);
    let dmadea = fdma(eaTest, ecc);
    

    // Iterate to find the best value.
    let iter = 0;
    while (true) {
        let eaTestB;
        
        // Are we done?  Yes if either we got the right answer,
        // or we've run out of range to adjust...
        if (maTest == ma || !hasRange(emin, emax)) {
            totalError += Math.abs(maTest-ma);
            if (maTest != ma) {
                // For the nonce lets see if we get any large errors.
                let delta = Math.abs(maTest-ma);
                // Second condition reflects large values of MA for hyperbolic
                // orbits where we lose absolute precision due to magnitude of MA.
                if (delta > 5.e-14  && Math.abs(delta/ma) > 5.e-14) {
                    console.log("Diff:", Math.abs(maTest-ma), ma, ecc);
                }
            }
            exit2 += 1;
            return eaTest;
        }
        
        // Check to see if we're not converging and end if we've gone too
        // many iterations.  This shouldn't happen, so report it the first few
        // times.
        if (iter > 1000) {
            if (errCnt < 10) {
                Util.log("Kepler: No convergence: eccentricity:", ecc,'  Mean anomaly (rad):', ma);
            }
            errCnt += 1;
            return null;
        }

        // We haven't finished.  First let's do a quick test halfway to the
        // appropriate limit.  This keeps us from stalling.        
        let delta = ma - maTest;
        
        // Is the correct answer on the upper side of the current value of eaTest?
        let upper = true;
        if (ma < maTest) {  // The maTest value is smaller than ma, so the correct ea is smaller too.
            upper = false;
        }
        
        // Try a test value halfway between the current test value and the appropriate limit.
        if (upper) {
            eaTestB = 0.5*(eaTest + emax);
        } else {
            eaTestB = 0.5*(eaTest + emin);
        }
        
        // If we are so close to the boundary that we can't move
        // any further then we are done
        if (eaTestB == eaTest) {
            exit3 += 1;
            totalError += Math.abs(delta);
            return eaTest;
        }
        
        // Get the value at this bisection point?
        let maTestB = fma(eaTestB, ecc);
        
        // Just in case...
        if (maTestB == ma) {
            limitCnt += 1;
            exit4 += 1;
            return eaTestB;
        }
        let deltaB  = ma - maTestB;
        

        // Which result was closer?
        let useDelta = delta;
        let useEaTest = eaTest;
        let useMaTest = maTest;
        // If the midpoint works better.  Use that
        // instead of the original guess.
        if (Math.abs(deltaB) < Math.abs(delta)) {            
            limitCnt += 1;
            useEaTest = eaTestB;
            useMaTest = maTestB;
            dmadea = fdma(eaTestB, ecc);
            useDelta  = deltaB;
        }
        
        // Also, we can update the limits.  If the sign is the
        // same, then the midpoint must have been a better guess,
        // b
        if (delta*deltaB > 0) {
            // Same sign...  So the midpoint should be the better one.
            if (delta > 0) {
                emin = eaTestB;
            } else {
                emax = eaTestB;
            }
        } else {
            if (eaTest < eaTestB) {
                emin = eaTest;
                emax = eaTestB;
            } else {
                emin = eaTestB;
                emax = eaTest;
            }
        }
        let newEa = useEaTest + useDelta/dmadea;
        if (newEa == useEaTest) {
            // extrapolates to same point, so we are done...
            exit5 += 1;
            totalError += Math.abs(useDelta);
            return newEa;
        }
        
        
        if (newEa > emax) {
            newEa = emax;
        } else if (newEa < emin) {
            newEa = emin;
        }
        
        maTest = fma(newEa, ecc);
        dmadea = fdma(newEa, ecc);
        eaTest = newEa;
        iter    += 1;
        if (iter > maxIter) {
            maxIter = iter;
        }
        iterCnt += 1;
    }
};

export default Kepler;
