// Calculate the global minimum of a scalar function (nominally of time) between
// the start/stop values, where a step of delta should be
// small enough to separate extrema (i.e., extrema will never
// be less than delta apart).
//     func  -- Scalar function of one variable.
//     start -- Start time for looking for minimum
//     stop  -- Stop time for looking for minimum (stop may be less than start)
//     delta -- A time step sufficiently fine to separate extrema of the function adequately.
//     tol   -- The allowed offset time from the actual minimum in the returned value.
//              Once we've isolated the minimum to a range of less than tol we can return.
//     returns structure {t: time, f: value}
//
// This method is only expected to work with reasonably smooth functions.

import OrbitCompare from "../orbits/OrbitCompare.js";
function xLog(...args) {
    if (OrbitCompare.count == 0) {
        console.log(args);
    }
}
const MinCount = {};
MinCount.evals    = 0;
MinCount.locals   = 0;
MinCount.binaries = 0;
MinCount.calls    = 0;
function GlobalMinimum(func, start, stop, delta, tol, eps) {
    MinCount.calls += 1;
    // We will split the desired interval by delta (or something smaller) and
    // look for minima along the points.  We extend by an interval in each direction
    // to look for minima at the endpoints.
    
    // Find an appropriate delta to exactly divide the interval.
    // We'll use a minimum of 8 bins.
    
    // Choose defaults approriate to orbits in MKS units:  find minimum to within ~20 minutes
    // Don't allow test points closer than 1 second.
    
    if (tol == null) {
        tol = 1000;
    }
    if (eps == null) {
        eps = 1;
    }
    let xStore = [];
    let fStore = [];
    
    let n = Math.abs(stop-start)/delta;
    if ( n < 8 ) {
        n = 8;
    } else {
        n = Math.ceil(n);
    }
    const d = (stop-start)/n;
    const forward = start < stop;  
    
    // Now get values at the start/stop points of each sub-interval. 
    // We extend an extra sub-interval in each direction.
    let t    = start - d;
    let vals = [];  
    
    // We start with n intervals, and n+1 points.  We add 1 more point on each side to get n+3
    for (let i=0; i<n+3; i += 1) {
        vals[i] = func(t);
        MinCount.evals += 1;
        t      += d;
    }
    
    let minVals = [];
    let minLevel = 0;
    
    // First check to see if the start or stop points are guaranteed to be local minima in the range
    // because the function decreasing as we go over the edge of the interval.  This uses the assumption
    // that their cannot be a maximum in the same or adjacent interval as a minimum.
    if (vals[0] < vals[1]  && vals[1] < vals[2]) {
        minVals.push({t: start, f: vals[1]});
    }
    if (vals[n+2] < vals[n+1]  && vals[n+1] < vals[n]) {
        minVals.push({t: stop, f: vals[n+1]});
    }
    
    // Now look for local minima.  Again the assumption that extrama must be spread out across bins.
    for (let i=1; i<n+1; i += 1) {
        
        // Look for a minimum.
        if (vals[i] < vals[i-1]  && vals[i] < vals[i+1]) {
            const t0 = start + (i-2)*d;
            const t1 = t0+d;
            const t2 = t1+d;
            minLevel = 0;
            
            // Calculate the local minimum
            const localMin = getLocalMinimum(t0, t1, t2, vals[i-1], vals[i], vals[i+1]);
            
            // If we found a mininum in the first or last triplet, it could be outside
            // the requested time range.  Must be decreasing as we cross the range limit.
            if ( (localMin.t < start && forward) || (localMin.t > start && !forward)) {
                localMin.t = start;
                localMin.f = vals[1];
            } else if ((localMin.t > stop  && forward) || (localMin.t < stop && !forward)) {
                localMin.t = stop;
                localMin.f = vals[n+1];
            }
            minVals.push(localMin);
        }
    }
    
    // Sort the local minima according to the minimum val, so least is firt.
    if (minVals.length > 1) {
        minVals.sort((a,b)=>{return a.f-b.f});
    }
    // Return the global minimum
    return minVals[0];
    
    
    // Use recursive fitting to parabola to find local minimum.
    function getLocalMinimum(t0, t1, t2, f0, f1, f2) {
        MinCount.locals += 1;
        xStore[minLevel] = [t0, t1, t2];
        fStore[minLevel] = [f0, f1, f2];
        minLevel += 1;
        
        //  We need to have our own forward flag, separate from the global minimum
        // since if we invoke a binary search it may switch the direction.
        const forward = t0 < t2;
        
        let tbot = t0;
        let ttop = t2;
        if (t2 < t0) {
            ttop = t0;
            tbot = t2;
        }
        
        // Fit known three values to f(t)=  at^2 + bt + c and get parameters of parabola.
        const r01 = (f0-f1)/(t0-t1);
        const r02 = (f0-f2)/(t0-t2);
        const a   = (r01-r02)/(t1-t2);
        const b   = r01 - a*(t0+t1);
        const c   = f0  - a*t0*t0 - b*t0;
        if (a < 0) { 
            console.log("No minimum found");
            // Need a to be positive or we get a max rather than a min.
            return null;
        }
        
        // Minimum should occur where derivative is 0.  2a*t + b = 0
        let tMin = -0.5*b/a;
        
        // Don't allow new point too close to existing points.
        // Roundoff in calculations can then break algorithm
        // Note that eps should be << tol so that this doesn't
        // push the new test point outside the desired range.
        
        let xDelt = eps;
        if (!forward) {
            xDelt = -eps;
        }
        if (Math.abs(t0-tMin) < eps) {
            tMin = t0 + eps;            
        }
        if (Math.abs(t1-tMin) < eps) {
            if (tMin < t1)  {
                tMin = t1-eps;
            } else {
                tMin = t1+eps;
            }            
        }
        if (Math.abs(t2-tMin)< eps) {
            tMin = t2-xDelt;
        }
        
        if (tMin < tbot || tMin > ttop) {
            console.log("***Minimum outside range", t0,t1,t2,f0,f1,f2,a,b,c, tMin);
            return null;
        }
        
        const fMin = func(tMin);
        MinCount.evals += 1;
        
        // With our new test point we have 4 distinct values.  
        // Let find the three that surround the minimum.
        // Recall that we may have a negative interval.
        if ( (tMin < t1  && forward) || (tMin > t1 && !forward) ) {
            // Order id t0, tMin, t1, t2.
            if (fMin > f1) { 
                // Next using tMin, t1, t2
                t0 = tMin;
                f0 = fMin;
            } else  {
                // Next t0, tMin, t1
                t2 = t1;
                f2 = f1;
                t1 = tMin;
                f1 = fMin;
            }
        } else {
            // Starting with t0, t1, tMin, t2
            if (fMin > f1) {
                // Next using t0, t1, tMin
                t2 = tMin;
                f2 = fMin;
            } else {                
                // Next using t1, tMin, t2
                t0 = t1;
                f0 = f1;
                t1 = tMin;
                f1 = fMin;
            }
        }
        
        // OK.  Are we sufficiently bound in time that we can return?
        if (minLevel > 30 || Math.abs(t0-t2) < tol) {
            if (minLevel > 30) {
                console.log("LocalMinimum recursion limit");
                throw new Error("GlobalMinimum did not converge");
            }
            return {t: t1, f: f1};
        } else {
            // Check if the two intervals are very unequal.
            const dt01 = Math.abs(t0-t1);
            const dt12 = Math.abs(t1-t2);
            if (dt01 > 10*dt12) {
                const ret = getBinaryMinimum(t0, t1, t2, f0, f1, f2);
                return ret;
                
            } else if (dt12 > 10*dt01) {
                // Make it so that the big interval is first.
                // We haven't required the intervals to be positive.
                const ret = getBinaryMinimum(t2, t1, t0, f2, f1, f0);
                return ret;
            }
            // Or should we recurse using the new bounds for the minimum?
            const ret = getLocalMinimum(t0, t1, t2, f0, f1, f2);
            return ret;
        }
    }
    
    // Call this when the two intervals are too unequal.
    // The difference between t0 and t1 should be much larger
    // than between t1 and t2.
    function getBinaryMinimum(t0, t1, t2, f0, f1, f2) {
        MinCount.binaries += 1;
        if (Math.abs(t0-t2) < tol) {
            return {t: t1, f: f1};
        }
        
        const smallDelta  = 2*(t2-t1);
        let ttest = t1-smallDelta;
        let ftest = func(ttest);
        MinCount.evals += 1;
        if (ftest > f1) {
            const dtt1 = t1 -ttest;
            const dt12 = t2 - t1;
            if (Math.abs(dtt1/dt12) > 10) {
                // Intervals still unequal.
                return getBinaryMinimum(ttest, t1, t2, ftest, f1, f2);
            } else {
                // Bracketing minimum, but with more equal intervals
                return getLocalMinimum(ttest, t1, t2, ftest, f1, f2);
            }
        } else {
            // If we have a new minimum we know the ratio of offsets if 3/1
            // which is reasonably balanced.
            return getLocalMinimum(t0, ttest, t1, f0, ftest, f1);
        }
    }
}

export default GlobalMinimum;