
import Util from "../std/Util.js";
import Constants from "../std/Constants.js";

import QOrb from "../orbits/QOrb.js";

// The equinoctial elements are less subject to singulatities than the stantard
// Keplerian elements.
//   Given the Keplerian elements:
//      a:  the semimajor axis
//      e:  the eccentricity
//      i:  the inclination
//      omega: the longitude of the ascending node
//      nu: the argument of periapsis
//      t0: an epoch of periapsis
// we can calculate the equinoctial elements
//      a:   unchanged
//      h:   e cos(omega+nu)
//      k:   e sin(omega+nu)
//      p:   tan(i/2) cos(omega)
//      q:   tan(i/2) sin(omega)
//      lambda: M+nu+omega
//  where M is the mean anomaly at the epoch of the elements.
//  We can calculate M since we know t0 and the period of the orbit (from a).
//  QOrb actually gives both a and the period of the orbit which means that we
//  have a measure of the central mass.  We propogate that to the elements
//  since ultimately we'll want to convert back to orbits using the standard
//  elements.

class Equinoctial {
    
    // This starts with a standard orbit object and determines
    // the equinoctial elements.  The epoch is t=0 for the calculation of M.
    // The elements are returned as a simple structure.
    static getElems(orb){
        
        const a = orb.a;
        let res = {a: a};
        const nu = orb.rot[5];
        const omega = Math.atan2(orb.rot[2], orb.rot[0]);
        const i     = Math.atan2(orb.rot[4], orb.rot[3]/orb.rot[0]);
        res.sqGM  = 2*Math.PI*a*Math.sqrt(a)/orb.per;
        let M     = 2*Math.PI * (orb.t0%orb.per)/orb.per;
        if (M < 0) {
            M += 2*Math.PI;
        }
        res.h = orb.e * Math.cos(nu + omega);
        res.k = orb.e * Math.sin(nu + omega);
        const ti2 = Math.tan(0.5*i);
        res.p = ti2*Math.cos(omega);
        res.q = ti2*Math.sin(omega);
        res.lambda = M + nu + omega;
        return res;
    }
    
    // This returns an orbit from a set of equinoctial elements where the epoch
    // is assumed to be t=0.  Note that in addition to the standard
    // equinoctial elements the mass of the central body is also provided
    // in the input parameters (or more precisely sqrt(G*M) is.
    static getOrbit(elems) {
        const a = elems.a;
        let orb = {a:a};
        orb.per = 2*Math.PI * a*Math.sqrt(a)/elems.sqGM;
        const nu_plus_omega = Math.atan2(elems.k, elems.h);
        const omega = Math.atan2(elems.q, elems.p);
        let nu = nu_plus_omega - omega;
        const M = elems.lambda - nu_plus_omega;
        const i = 2*Math.atan(elems.p/Math.cos(omega));
        orb.t0 = M/(2*Math.PI)*orb.per;
        orb.e = Math.sqrt(elems.h*elems.h + elems.k*elems.k);
        if (nu < 0) {
            nu += 2*Math.PI;
        }
        orb.rot = Util.anglesToRot({i:i, Omega:omega, nu:nu});
        return new QOrb(orb);        
    }
    
    // Interpolate between two sets of elements with r ranging from 0 to 1.
    // In principle this can take any structure with named real values.
    static interp(from, to, r) {
        let res = {...from};
        for (const name in from) {
            res[name] += r*(to[name]-from[name]);
        }
        return res;        
    }
}

export default Equinoctial;