import SolarPlanets     from "../../solarsystem/SolarPlanets.js";
import AnimationFactory from "../../animations/AnimationFactory.js";
import Util             from "../../std/Util.js";
import Constants        from "../../std/Constants.js";
import QOrb             from "../../orbits/QOrb.js";
import Epicycle         from "../../orbits/Epicycle.js";
import Rotation         from "../../orbits/Rotation.js";
import precession       from "../../orbits/Precession.js";
import Action           from "./Action.js";
import SolarSystem      from "../../animations/SolarSystem.js";

// An orbit definition supports the following parameters:
//   primary:   the body to be orbited (defaults to Earth
//   id:        the id to be used for this orbit launch commands.
//   a:         semimajor axis (either a or altitude required)
//   altitude:  the altitude of the orbit over the surface (either a or altitude required)
//   e:         eccentricity  (req)
//   nu:        argument of perihelion(req)
//   omega:     the longitude of the rising node (req)
//   i:         inclination of orbit (req)
//   t0:        time of periastron passage
// Angle arguments are specified in degrees.  Distances default to meters, but
// and attempt is made to parse their units.
// The mass and radius of the primary are extracted from the information in the animations.
//   

class definition extends Action {
    
    constructor(ptr, anim, traj) {
        super(ptr, anim, traj);
    }
        
    execute() {
        if (this.anim.delta < 0) {
            return;  // Do nothing when going backwards in time.
        }

        let keyvals = this.args.keyvals;
        if (keyvals.primary && keyvals.primary && keyvals.site && keyvals.id) {
            this.landing(keyvals.primary,keyvals.site,keyvals.id);
        } else {
            this.newOrbit();
        }
    }
    
    // The defined trajectory is an orbit around some other body.
    newOrbit() {
        
        // Functions used to parse arguments.
        function check(key, val) {
            if (!val) {
                throw new Error("Required id not found in orbit definition");
            }
            return val;
        }
        
        function parse1(key, val) {
            if (val == null) {
                throw new Error("Required value: "+key+" not found in orbit definition");
            }
            let v = parseFloat(val);
            if (isNaN(v)) {
                throw new Error("Unparseable value for "+key+" in orbit definition: "+val);
            }
            return v;
        }
        
        function parse2(key, val) {
            if (val == null) {
                return null;
            }
            let v = Util.parseWUnits(val);
            if (isNaN(v)) {
                throw new Error("Unparseable value for "+key+" in orbit definition: "+keyvals[name]);
            }
            return v;
        }
        
        function findObj(key, p) {            
            if (!p) {
                p = "Sun";
            }
            
            let data = SolarSystem.getTrackedObject(p);
            if (!data) {
                throw new Error("Attempt to define orbit unknown object: "+p);
            }
            return data; 
        }    
        
        
        
        let proc = {id: check, 
                    primary: findObj, a: parse2, t0: parse2, altitude: parse2,
                    e: parse1, omega:parse1, nu: parse1, i: parse1};
        let res = {};
        
        // Do the processing appropriate for each key.
        for (let key in proc) {
            res[key] = proc[key](key, this.args.keyvals[key]);
        }
        
        // Ignore attempts to redefine a given id.
        if (Action.definedOrbits[res.id]) {
            this.redefinition(res.id);
            return;
        }
        
        // Confirm we have a size for the orbit.
        let a = res.a;
        
        if (a == null) {
            if (res.altitude  && res.primary && res.primary.radius) {
                a = res.altitude + res.primary.radius;  // Add the radius of the primary to the altitude.
                res.a = a;
            }
        }
        if (!a) {
            throw new Error("Orbit size not specified");
        }
        
        if (a*(1-res.e) < res.primary.radius) {
            throw new Error("Orbit intersects surface");
        }
        
        // Angles to radians
        res.i  = Util.toRadians(res.i);
        res.nu = Util.toRadians(res.nu);
        // Note capital since anglesToRot uses it that way.
        res.Omega = Util.toRadians(res.omega);
        delete res.omega;
        
        res.rot = Util.anglesToRot(res);
        
        let M = res.primary.mass;
        res.per = 2*Math.PI * Math.sqrt(a*a*a/(Constants.G*M));
        
        let orbit = new QOrb(res);
        if (res.primary.J2) {
            // We're going to compute the precession rates, but
            // the 0 time should be when we enter this orbit, so
            // we'll need to update the orbit later.  Setting the
            // zero point to null will suppress precession till we
            // know when...
            let [p1, p2] = precession(res.primary.radius, orbit);
            orbit.addPrecession(null, p1, p2);
        }
        if (res.primary.orbit) {
            orbit = new Epicycle(res.primary.orbit, orbit, res.primary.name);
        }
        
        // Add to the list of defined orbits.
        Action.definedOrbits[res.id.toLowerCase()] = orbit;
    }
    
    redefinition(id) {
        Util.log("Attempt to redefine orbit: "+id);
    }
    
    // The defined trajectory is at rest on the surface of some body.
    landing(primary, site, id) {
        if ( Action.definedOrbits[id.toLowerCase()]) {
            this.redefinition();
            return;
        }
        id = id.toLowerCase();
        if (Action.definedOrbits[id]) {
            this.redefinition(id);
            return;
        }
        let crds = this.lonlat();
        let data = SolarSystem.getTrackedObject(primary);
        if (crds == null || data == null) {
            throw new Error("Unable to find required data for landed state-- ID: "+id+"  Primary: "+primary+"  site: "+site);
        }
        let rot = new Rotation(primary, crds[0], crds[1]);
        let orb = new Epicycle(data.orbit, rot, primary);
        Action.definedOrbits[id.toLowerCase()] = orb; 
    }
}

export default definition;