import CameraAction     from "./CameraAction.js";
import Command    from "../Command.js";
import TransCalc  from "../../traj/TransCalc.js";
import Util       from "../../std/Util.js"; 
import Constants  from "../../std/Constants.js"; 

import {Vector3}  from "three";

class center extends CameraAction {
    constructor(ptr, anim, traj) {
        super(ptr, anim, traj);
    }
    
    
    execute(force) {
        this.initiate();
    }
    
    initiate() {
        let here = this;
        let forward   = this.anim.delta > 0;
        let generated = this.ptr.elem.generated !== false;
        if ((forward && generated)   || (!forward && !generated)) {
            return;
        }
        let target = this.getMovant();
        
        // Do the recentering after we've successfully parsed
        // the arguments and if necessary found the coordinates of a named object.
        function doCenter(params) {
            let c = params.position;
            let oldCent =  target.clone();
            
            // Do user centers going forward, and genereated centers going
            // backward.
            
            
            if (here.anim.delta > 0) {
                // Add in command to revert to current position when running backwards.
                let posStr = oldCent.x+" "+oldCent.y+" "+oldCent.z;
                if (here.movant == "camera") {
                    posStr += " movant=camera";
                }
                
                let revc = new Command(here.ptr.elem.t, "center", posStr);
                revc.generated = here;
                let revert = {elem: revc};
                
                // Insert into the sequence immediately before the current command.
                here.ptr.prev.next = revert;
                revert.prev        = here.ptr.prev;
                revert.next        = here.ptr;
                here.ptr.prev      = revert;
            }
            let nvec = new Vector3(c[0], c[1], c[2]+here.getZOffset());
            target.copy(nvec);
        }
        
        let args = this.args.posvals;
        if (args.length == 0) {
            doCenter({position:[0,0,0]});
        }
        
        this.handlePosition(this.anim.time, args, {}, doCenter);
                
    }
}

export default center;
