import Animation from "../elems/Animation.js";
import Util      from "../std/Util.js";
import Coords    from "../std/Coords.js";
import Constants from "../std/Constants.js";
import Settings  from "../std/Settings.js";

import {Scene, Vector3, Euler,
        SphereGeometry, MeshBasicMaterial, Mesh} from "three";

class Void extends Animation {
    constructor(params) {
        super(params);
        
        this.calls      = 0;
        this.maxCalls   = 1;
        
        this.delta      = 2.5*86400;   // 2.5 days (about 10 times the step size for the solar system.
        this.paused     = true;
        this.name       = "Interstellar void"; 
        this.primeChild = "Solar System";
        this.baseAnimation = "Local Galactic Neighborhood";
        
        this.longClickTime = 1500;  // A little shorter since
                                    // we do less clicking here.

        this.scene       = new Scene();
        this.textShowing = true;
        this.centerBody  = "Solar System";
        
        this.cameraPos = new Vector3(0,0,10);
        this.cameraRot = new Euler(0,0,0,"XYZ");
        this.sceneCoord = "Ec";
        this.minScale = 14.4;
        this.maxScale = 16.4;
        this.sceneScale = 1000*Constants.AU;
        this.addSS();        
        this.addTimeDisplay();
        
        if (Settings.showVoid == "always") {
            this.maxCalls = 1.e10;
        } else if (Settings.showVoid == "never") {
            this.maxCalls = 0;
        }
        this.finish();              
    }
    
    addSS() {
        const ssGeom = new SphereGeometry(0.1, 30,30);
        const mat    = new MeshBasicMaterial({color: 0xFFFF00, wireframe: false});
        const ss     = new Mesh(ssGeom, mat);
        ss.meta      = {name: "Solar System", type: "Stellar system"};
        this.addElement (
               "Solar System", 
               {name: "Solar System", component: ss}
        );        
    }
    onEnter() {
        this.calls += 1;
        // Skip this animation if we aren't supposed to see it.
        if (this.calls > this.maxCalls) {
            if (this.frame.prevAnimation.name == "Solar System") {
                this.setAnim("Local Galactic Neighborhood");
            } else {
                this.setAnim("Solar System");
            }
            return;
        }
        let text = `
<b>The Interstellar Void</b>
<br>
<pre>
In the range from a few thousand AU to a few hundred thousand AU
there is little that we can confidently depict.  The known Solar System shrinks to 
a tiny spot in the center.  While millions of comets are thought to inhabit the Oort Cloud 
and the Kuiper Belt, few orbits are known.
        
Here, beyond the influence of the Solar wind, the interstellar medium is thought
to be  thin and very hot, a consequence of shock waves blasting through -- presumably 
from recent supernovae.   

The Galactic magnetic field threads through the region, but it has not been mapped with any detail at this scale.

By default, this animation is inserted in the chain of animations the first time 
a user moves up the animation chain from Solar System to Local Galactic Neighborhood or 
down in the opposite direction to allow a user to visualize the scope of the void. The only
object shown in the animation is a ball representing the entire solar system.        

The scale for this animation runs from 2.5 x 10<sup>14</sup> to 2.5 x 10<sup>16</sup> meters, or 
about  1,600 to 160,000 AU. Subsequently, this interval is usually skipped. 
The startup option, <b>showVoid</b> may be specified with the values <b>never</b>, <b>once</b>, 
or <b>always</b> to alter the default (<b>once</b>) behavior.
`
        this.setQuickHTML(text);
    }
    getAnimationFrame() {
        return Coords.getCoords("unit");
    }
    doLongClick(e) {
        const matched = this.frame.raycast(e);
        let found = null;
        
        for (let i=0; i<matched.length; i += 1) {
            let entry = matched[i];
            let name = entry.meta.name;
            if (name == "Solar System") {
                this.setAnim("Solar System");
                return;
            }
        }
        super.doLongClick(e);
    }        
}  

export default Void;

