import Action       from "./Action.js";
import Util from "../../std/Util.js";

class rest extends Action {
    constructor(ptr, anim, traj) {
        super(ptr, anim, traj);
    }
    
    
    // Let the body rest on the surface of some object.
    execute() {
        let delta   = this.anim.delta;
        let flds    = this.args.posvals;
        
        // Doing the landing...
        // The rest state starts at the rest command and continues
        // till the next movement.  
        //
        // So moving forward in time, the rest state begins at the
        // time of the command, and moving backwards it starts at
        // the time of the following impulse.
        
        if ( (delta > 0  && this.time == this.anim.time)  ||
             (delta < 0  && this.time < this.anim.time)  ) {
            let primary = this.args.keyvals.primary;
            if (!primary) {
                primary = this.args.posvals[0];
            }
            let [pLon, pLat] = this.lonlat();
            this.traj.rocket.setToRest(this.anim.time, primary, pLon, pLat);
        }
    }
}

export default rest;
