// Collect all of the legal commands in a single
// export.  Commands are assumed to be in the same directory.

// General actions
import animation from "./animation.js";// Select the overall animation
import comment   from "./comment.js";  // Comment in trajectory itself
import echo      from "./echo.js";     // Display a comment in animation
import loop      from "./loop.js";     // Go back to beginning of trajectory program
import skip      from "./skip.js";     // Skip forward in the animation.
import speed     from "./speed.js";    // Change the timestep of the animation

// Trajectory actions
import impulse   from "./impulse.js";  // Add an impulse to the trajectory
import jump      from "./jump.js";     // Make an instantaneous jump to another location
import orbit     from "./orbit.js";    // Begin orbit (either specified or using current state)
import coast     from "./coast.js";    // Coast without gravitational influence
import thrust    from "./thrust.js";   // Add a thrust to the gravitational pull
import accel     from "./accel.js";    // Accelerate without gravitational influence
import rest      from "./rest.js";    // Rest on the surface of a body

// Calculate transfers to a body
import transfer   from "./transfer.js";   // Transfer to a given orbit using initial and final impulses
import transmid   from "./transmid.js";   // Tranfer to a given orbit using initial, final and midcourse impulses
import transcalc  from "./transcalc.js";  //
import trajectory from "./trajectory.js"; // Trajectory with lots of options.
import accelto    from "./accelto.js";    // Accel/decel trajectory.

import definition from "./definition.js";  // Define an orbit to be launched to.


// Camera actions
import center    from "./center.js";    // Set the center of the animation
import follow    from "./follow.js";    // Follow an object as the center of the animation
import pan       from "./pan.js";       // Pan to a given locaiton over time

// Visibility actions
import hide      from "./hide.js";      // Hide an element in the animation.
import norocket  from "./norocket.js";  // Mark the script as a non-trajectory
import show      from "./show.js";      // Show an element in the animation.


const actCache = {};

// Generic actions
actCache.animation = animation;
actCache.comment  = comment;
actCache.echo     = echo;
actCache.loop     = loop;
actCache.speed    = speed;

// Base motion actions
actCache.impulse  = impulse;
actCache.jump     = jump;
actCache.orbit    = orbit;
actCache.coast    = coast;
actCache.thrust   = thrust;
actCache.accel    = accel;
actCache.rest     = rest;

// Complex trajection actions
actCache.transfer   = transfer;
actCache.transmid   = transmid;
actCache.transcalc  = transcalc;
actCache.trajectory = trajectory;
actCache.accelto    = accelto;

actCache.definition    = definition;

// Camera actions
actCache.center   = center;
actCache.follow   = follow;
actCache.pan      = pan;

// Visibility actions
actCache.hide     = hide;
actCache.norocket = norocket;
actCache.show     = show;

export default actCache;
