import  {Component}  from "react";

import Animation     from    "../elems/Animation.js";
 
import Util          from    "../std/Util.js";
import Dump          from    "../std/Dump.js";
import Constants     from    "../std/Constants.js";

import SolarPlanets   from    "../solarsystem/SolarPlanets.js";
import ssData         from   "../data/PlanetaryData.js";

import loadMPCData   from    "../parsers/ParseMPC.js";

import OrbitPlot     from    "../solarsystem/OrbitPlot.js";
import Planet        from    "../solarsystem/Planet.js";
import Ring          from    "../solarsystem/Ring.js";
import SmallBodies   from    "../solarsystem/SmallBodies.js";
import Sun           from    "../solarsystem/Sun.js";
import Missions      from    "../solarsystem/Missions.js";
import TrojanOrbit   from    "../orbits/TrojanOrbit.js";
import QOrb          from    "../orbits/QOrb.js";
import FixedOrbit    from    "../orbits/FixedOrbit.js";

import Settings      from    "../std/Settings.js";



// In doing trajectories we will need to consider orbits that have different primaries.
class TrackedEntity {
    constructor(name, primary, orbit, mass, radius, rotation) {
        this.name    = name;
        if (primary) {
            let lc = primary.toLowerCase();
            if (!SolarSystem.solarObjects[lc]) {
                Util.log("Adding solar object "+name+" with unsaved primary: "+primary);
            }
        }
        this.primary = primary;
        this.orbit   = orbit;
        this.mass    = mass;
        this.radius  = radius;
        this.rotation = rotation;
    }
}

class SolarSystem extends Animation {
    
    static solarObjects = {};
    static addTrackedObject(name, primary, orbit, mass, radius, rotation) {
        // If no rotation is given, then we assume that the axis is the same
        // as primary, the period is the same as the orbital period and just use 0 phase.
        if (rotation == null) {
            let prot = {...SolarSystem.getTrackedObject(primary).rotation}; 
            prot.rotationPeriod = orbit.per;
            prot.rotationPhase  = 0;
            rotation            = prot;
        }
        SolarSystem.solarObjects[name.toLowerCase()] = new TrackedEntity(name, primary, orbit, mass, radius, rotation);
    }
    
    static getTrackedObject(name) {
        return SolarSystem.solarObjects[name.toLowerCase()];
    }
    
    constructor(inputs) {
        
        super(inputs);
        const fields = {
            centerBody:    "Sun",
            centralMass:   ssData.Sol.mass,
            name:          "Solar System",
            primeChild:     "Earth",
            sceneCoord:    "Ec",
            baseAnimation: "Interstellar void",
            longClickTime: 1500,  // How long a mouse click needs to be to be classified as a long click.
            maxScale: 14.4,       // Maximum scale for simulation (about 300 billion km)
            minScale: 10.5        // Minimum scale for simulation (about 5 million km)
        };
        
        console.log("Just a random addition");
        for (var key in fields) {
            if (!inputs || !inputs[key]) {   // Don't override anything specified by user.
                this[key] = fields[key];
            }
        }
        
        if (!inputs.planets) {
            this.planets = Object.keys(ssData.Sol.planets);
        }
        
        // Set the start time of the animation to the start of the current day.
        // Since the program starts with this animation, this
        // is where we are initializing the start time.  When we switch
        // animations the new animation will inherit the time.
        
        this.time  = Date.now()/1000;
        this.time -= Constants.Epoch0;        // Use 2000 as 0 point
        // Now to aid debugging we will start at the beginning of the current
        // UTC day.  So when we do a sequence of runs on the same day we should 
        // get identical results.
        this.time -= this.time % 86400;
                
        this.addSun();
        this.addPlanets();
        this.sceneScale = Constants.AU;
        this.addSmallBodies();
        
        
        this.addTimeDisplay();
        
        let miss = Missions(ssData.Sol.missions, this.time);
        let oldQuiet = this.quiet;
        if (miss.length > 10) {
            this.quiet = true;
        }
        for (let i=0; i<miss.length; i += 1) {
            this.addElement(miss[i].name+"Miss", miss[i]);
        }
        this.quiet = oldQuiet;
        
        if (miss.length > 0) {
            Util.log("Added "+miss.length+" spacecraft missions");
        }
        this.finish();
    }
        
    doLongClick(e) {
        const matched = this.frame.raycast(e);
        let found = null;
        
        for (let i=0; i<matched.length; i += 1) {
            
            let entry = matched[i];
            let name = entry.meta.name;
            if (name == "Sun") {
                this.setQuickHTML("No subanimation for the Sun.<br>Double click on planets or their orbits<br>for subanimations.")
            }
            let type = entry.meta.type;
            if (type == "planet"  && name != this.name) {
                this.setAnim(name);
                return;
            } else if (type == "orbit"  && ssData.Sol.planets[name]) {
                this.setAnim(name);
                return;
            }
        }
        super.doLongClick(e);
    }
    
    foundBodies(e) {
        var detail = e.detail;
        detail = Object.entries(detail).sort((a, b) => a[1] - b[1]);
        const data = [];
        for (var i in detail) {
            if (detail[i][1] > 0) {
                detail[i][1] = detail[i][1].toFixed(4);                
            }
            data.push({name: detail[i][0], d: detail[i][1]});
        }
        this.setState({nearby: data});
    }
    
    find(name, callback) {
        this.frame.finder.getLocation(name, this.smbData, "smb", callback);
    }

    // Add the fixed sun
    addSun() {
        this.addElement("Sun", Sun());
        SolarSystem.addTrackedObject("Sun", null, new FixedOrbit(), ssData.Sol.mass, ssData.Sol.radius, 
                                     {rotationPeriod:2500000, rotationPhase:0, rotAxis:[0,90]}); 
    }

    // Add the planets
    addPlanets() {

        const names = this.planets;
        
        // The orbits of the planets have a very slow dependence on time,
        // so save this time in case we want to match the orbits generated here.
        this.planetOrbitEpoch = this.time;

        // Add each planet in the list.
        for (var xi = 0; xi < names.length; xi += 1) {
            const pname = names[xi];

            const planetData = SolarPlanets.getElements(pname, this.time);
            const qorb       = SolarPlanets.getOrbit(pname, this.time);
            if (qorb == null) {
                Util.log("Unable to process orbit for "+pname);
                continue;
            }
            
            // Save basic information about this object.
            SolarSystem.addTrackedObject(pname, "Sun", qorb, planetData.mass, planetData.diameter*500,
                {rotationPhase: planetData.rotationPhase, rotationPeriod: planetData.rotationPeriod,
                 rotAxis: planetData.rotAxis});
            // Add the orbit line (which is invariant)
            const orbitLine = new OrbitPlot(pname, qorb, planetData.color).comp();
            let meta = {...ssData.Sol.planets[pname], orbit: qorb};
            meta.name = pname;
            meta.type = "planet";
            orbitLine.component.meta = {...meta, type:"orbit", otype: "planet"};
            this.addElement(orbitLine.name, orbitLine);

            const planetBody = Planet(pname, this.time, qorb, planetData.diameter, planetData.color, false);
            planetBody.component.meta = {...meta, type:"planet"};
            
            this.addElement(planetBody.name, planetBody);

            // Does this planet have a ring?
            if (planetData.ringAngle) {
                const ringElement = Ring(pname, this.time, qorb, planetData.diameter, planetData.ringColor);
                ringElement.component.meta = {...meta, type:"ring"};
                this.addElement(ringElement.name, ringElement);
            }
        }
    }

    // Add the small bodies point array.
    addSmallBodies() {
        loadMPCData(ssData.Sol.smallBodiesURL, this.time, this.smbCallback.bind(this));
    }
    smbCallback(smbData, epoch) {
        this.smbData = smbData;
        this.smbEpoch = epoch;
        if (!Settings.notrojanfix) {
            Util.log("Adjusting Trojan and Hilda orbits to maintain swarms.");
            this.fixTrojans(this.smbData, epoch);
        }
        this.addMetaTime("smb", epoch);       
        this.addElement("SmallBodies", SmallBodies(this.smbData, this.colorLookup, this.time));
        if (this.deferred != null) {
            this.deferred();
        }
    }
    
    
    // Apply a correction to Trojans and Hildas to keep them
    // in appropriate groups.
    fixTrojans(data, epoch) {
        let nTrojan = 0;
        let nHilda  = 0;
        let JOrb = SolarSystem.getTrackedObject("Jupiter").orbit;
        for (let i=0; i<data.length; i += 1) {
            let initPos = data[i].orbit.position(epoch);
            let addTime = Math.random();
            if (data[i].Orbit_type == "Jupiter Trojan") {
                data[i].orbit = new TrojanOrbit(data[i].orbit, epoch, JOrb, (1+addTime)*0.2*Constants.CENTURY, 0, 1);
                nTrojan += 1; 
            } else if (data[i].Orbit_type == "Hilda") {
                data[i].orbit = new TrojanOrbit(data[i].orbit, epoch, JOrb, (1+addTime)*0.15*Constants.CENTURY, 0, 1.5);
                nHilda += 1;
            } 
        }
        Util.log("Updating Trojan and Hilda orbits:");
        Util.log("    "+nTrojan+" Trojans");
        Util.log("    "+nHilda +" Hildas");
        
    }
        
    raycastResult(results) {
        super.raycastResult(results, "au");
    }
    
    
    
    addExternalOrbit(name, orbit) {
    
        this.addElement(name+"Orbit", new OrbitPlot(name, orbit, 0xAAFFAA).comp());
        // If the phase of the orbit has been specified add the body too.
        if (orbit.t0 != null) {
            const userBody = Planet(name+"Body", this.time, orbit, 4000, 0xFFAAFF, true);
            this.addElement(userBody.name, userBody);
        }
    }
    // This function can be removed later.
    finish() {
        console.log("Finishing solar system");
    }

}

export default SolarSystem;