import {Component, createRef} from "react";

import {PerspectiveCamera, Matrix4, WebGLRenderer, Quaternion, Euler, Vector3, Group} from "three";
import {Scene} from "three";
import Rotater from "../three/Rotater.js";

import Rocket from    "../components/Rocket.js";
import CoordSys from "../components/CoordSys.js";
import Util      from "../std/Util.js";
import Constants from "../std/Constants.js";
import PushButton from "../elems/PushButton.js";
import Command from "../trajanim/Command.js";
import TrajOrbit from "../orbits/TrajOrbit.js";
import QOrb     from "../orbits/QOrb.js";
import CounterComponent from "../elems/CounterComponent";

class PushButtonX extends PushButton {
    constructor(props) {
        super(props);
    }
}

class RocketController extends Component {
    
    constructor(args) {
        super(args);
        this.anim         = args.anim;
        this.camRad       = 4;
        this.traj         = args.traj;
        this.wasThrusting = false;
        this.savedArgs    = null;
        this.camera       = null;
        this.state        = {hasImpulse: false, 
                            backward: args.anim.delta < 0, 
                            dv: 0, 
                            paused: this.anim.paused, 
                            impulse:[0,0,0],
                            stage: null,
                            lastMinApp: null
                            };
        if (this.traj.lastStage) {
            this.state.stage = this.traj.lastStage;
        }
        this.rocket       = null;
        this.controls     = null;
        this.vAbs         = [0,1,0];
        this.count        = 0;
        this.impChanged   = false;
        
        this.timeHandler = this.timeReverse.bind(this);
    }
    
    // Defer setting up three.js controls until
    // we have a real component to work with.
    componentDidMount()  {
        
        let elem          = document.getElementById("ControlDisp");
        const scene       = new Scene();
        const camera      = new PerspectiveCamera( 70, 1, 0.1, 10 );
        this.camera       = camera;
        camera.position.z = this.camRad;        
        const renderer    = new WebGLRenderer({antialias: true});
        this.renderer     = renderer;
        renderer.setClearColor("#000000");
        renderer.setSize(100, 100);
        this.lastAngle = -100;
                
        elem.appendChild(renderer.domElement);
        
        this.rocket = new Rocket({height:1.5, name:"Demo"});
        this.rocket.rotation.x = -Math.PI/2;
        let comp = new Group();
        comp.add(this.rocket);
        scene.add( comp );
        const csys = new CoordSys();
        scene.add(csys);
        elem.appendChild(renderer.domElement);
        this.rocket.Mfire.visible = false;
        this.setControls();
        this.anim.frame.renderer.domElement.addEventListener("timereverse", this.timeHandler);        
        this.startRender(renderer, camera, scene, this.rocket, csys);
        
                // Publish this controller.
        this.anim.frame.traj.setRocketController(this);

    }    
    
    // Set the controls for the manual orientation.
    setControls() {
        if (this.controls) {
            // New set of controls.
            this.controls.dispose();
        }
        this.controls = new Rotater(this.rocket, this.renderer.domElement);
    }
    
    // Close out the trajectory completely from the animation.
    closeTraj() {
        this.anim.frame.traj.delRocket(true);
        this.anim.removeElement("TrajSequencer");
        this.anim.frame.traj = null;
        this.anim.frame.userControls.holder.setState({optState: false, content: null});
    }

    // Called after a deferred start is finally ready to show up.
    restart() {
        if (this.savedArgs == null) {
            throw new Error("Attempt to restore RocketController without saved data");
        }
        let sv = this.savedArgs;
        this.startRender(sv.renderer, sv.camera, sv.scene, sv.rocket, sv.csys);
        this.savedArgs = null;
    }
    
    timeReverse() {
        this.setState({backward: this.anim.delta < 0});
    }
    
    // Begin rendering the rocket controller.
    startRender(renderer, camera, scene, rocket, csys) {
        let here = this;
        let count = 0;
        let lastQuat = null;
        let lastPaused = here.anim.paused;
        
        
        // This is invoked periodically in the Three.js animation of the
        // small rocket icon used to control the orientation of the craft.
        var render = function () {
            // If the rocket has been deleted just return.
            if (!here.anim.frame.traj || !here.traj.rocket) {
                return;
            }
            requestAnimationFrame( render );
            if (here.anim.paused != lastPaused) {
                lastPaused = here.anim.paused;
                here.setState({paused:lastPaused});
            }
            
            // In theory this might belong more in the rendering of the RocketController
            // component, but we can't call setState from that render, so we do it here.
            // We only look for an update if we have an orbit comparer, and either
            // we've updated an impulse, or the animation is running.  Normally we
            // shouldn't have both, since impulses are updated when the animation is
            // stopped.
            if (here.traj.orbCompare  && (here.impChanged || !here.anim.paused)) {
                let minArr = here.traj.orbCompare.minDist(here.anim.time);
                let d = minArr.f;
                if (!here.state.lastMinApp || (d != here.state.lastMinApp.f)) {
                    here.setState({lastMinApp: minArr});
                }
            }
            here.controls.update();
            let animCamera = here.anim.frame.camera.position;
            let rockState = here.traj.lastState;
            if (rockState == null) {
                return;
            }
            
            let cp   = here.anim.frame.camera.position;
            let cpos = [cp.x,cp.y,cp.z];
            let rpos = Util.times(1/Constants.AU, rockState[0]);
            let vel  = rockState[1];
            let cmp  = Util.viewedCoordFrame(cpos, rpos, vel);
            let x    = Util.vec3(cmp[0]);
            let y    = Util.vec3(cmp[1]);
            let z    = Util.vec3(cmp[2]);
            
            
            // These unit vectors define a coordinate system relative to
            // the input frame.  Csys is meant to represent the global
            // coordinate frame, so we use the inverse to properly
            // orient it.
            let mat = new Matrix4();
            mat.makeBasis(x,y,z);
            csys.setRotationFromMatrix(mat.transpose());            
            
            rocket.Mfire.visible = here.traj.rocket.thrusting;
                        
            // Render the scene
            renderer.render(scene, camera);
            let cr = rocket.rotation;
            let v = new Vector3(0,0,1);
            v.applyEuler(rocket.rotation);
            v.applyMatrix4(mat.transpose());
            here.vAbs = v;
            count += 1;
            
            // Check if the DV should be updated.
            let olddv = here.state.dv;
            let newdv = here.traj.rocket.totalDV;
            if (olddv != newdv) {                
                here.setState({dv: newdv});
            }
        };
        render();
    }
    
    // Disconnect
    componentWillUnmount() {
        if (this.anim.frame.traj) {
            this.anim.frame.traj.setRocketController(null);
        }
    }
    
    showOrb(evt) {
        this.showOrbit = evt.target.checked;
        if (this.showOrbit) {
            let rockState = this.traj.lastState;
            this.rockOrbit = QOrb.stateOrbit({t:this.anim.time, 
                                              r: rockState[0], 
                                              v: rockState[1]});
            this.rockOrbit.scale = 1/Constants.AU;
            let elem = new TrajOrbit(this).comp();
            if (this.anim.sceneElements["TrajOrb"]) {
                this.anim.removeElement("TrajOrb");
            }
            this.anim.addElement("TrajOrb", elem, true);            
        } else {
            this.anim.removeElement("TrajOrb");
        }
    }
    
    runningButtons() {
        let   up       = this.thrustUp.bind(this);
        let   down     = this.thrustPushed.bind(this);
        let   stage    = this.state.stage;
        let   disabled = stage != "after" || this.anim.delta < 0;
        let topButton = null;
        let button = <PushButton down={down} up={up} disabled={disabled} label="Thrust" />;
        if (this.state.hasImpulse) {
            up    = this.finishImpulse.bind(this);
            down  = this.executeImpulse.bind(this);
            button = <PushButtonX down={down} up={up} label="Execute impulse" />;
        }
        return (
          <div>
            {button}
            <br/>
            <button onClick={this.copyTraj.bind(this)}>Save trajectory</button><br/>
            <button onClick={this.closeTraj.bind(this)}>Close trajectory</button>
          </div>
        );
    }
    
    // Convert from an impulse in the r,rv, vrv system to x,y,z
    impXYZ() {
        let r = this.traj.lastState[0];
        let v = this.traj.lastState[1];
        let u = [];
        let d = [0,0,0];
        // Get the unit vectors.
        u[0] = Util.unit(v);                 //   Velocity
        u[2] = Util.unit(Util.cross(r, v));  //   Perpendicular to orbit plane
        u[1] = Util.cross(u[0], u[2]);       //   Perpendicular to velocity in orbit plane.
        // Now a matrix multiply.
        for (let i=0; i<3; i += 1) {
            for (let j=0; j<3; j += 1) {
                d[i] += u[i][j]*this.state.impulse[j];
            }
        }
        return d;
    }
    
    // We need to do commands immediately without switching states
    // so that we can track the same elements of the i/f.
    doAddedCommand(cmd) {
        const seq = this.traj.sequence;
        let ptr = seq.add(cmd);
        Command.enact(ptr, this.anim, this.traj);
        
        // Mark this command as done in the sequencer by updating its last time.
        this.traj.lastTime = this.anim.time;
    }
    
    insertImpulse() {
        const imp  = this.impXYZ();
        const dlt  = Util.mag(imp);
        if (dlt > .001) {
            let cmd = new Command(this.anim.time, "impulse",imp[0]+" "+imp[1]+" "+imp[2]);
            this.doAddedCommand(cmd);
        }
        // Need to update the lastState of the trajectory.
        this.traj.lastState = this.traj.rocket.traj.stateVector(this.anim.time);
        this.impChanged = true;
        this.setState({impulse:[0,0,0], hasImpulse: false});
    }
    
    executeImpulse() {
        this.lastImpulse = this.state.impulse;
        this.insertImpulse();        
    }
    
    finishImpulse() {
    }
    
    clearStopped() {
        this.setState({impulse:[0,0,0], hasImpulse: false});
    }
    
    stoppedButtons() {
        function isNumber(val) {
            return !Number.isNaN(Number.parseFloat(val));
        }
        
        let here = this;
        let updv0 = function(val) {
            if (isNumber(val)) {
                let num = Number.parseFloat(val);
                let oldImp = here.state.impulse;
                here.setState({impulse:[num, oldImp[1], oldImp[2]]});
            }
            here.impChanged = true;
        };
        let updv1 = function(val) {
            if (isNumber(val)) {
                let num = Number.parseFloat(val);
                let oldImp = here.state.impulse;
                here.setState({impulse:[oldImp[0], num, oldImp[2]]});
            }
            here.impChanged = true;
        };
        let updv2 = function(val) {
            if (isNumber(val)) {
                let num = Number.parseFloat(val);
                let oldImp = here.state.impulse;
                here.setState({impulse:[oldImp[0], oldImp[1], num]});
            }
            here.impChanged = true;
        };
        
        
        return (
            <div>
    <table><tbody><tr>
    <th colSpan="2" align="center">Impulse (m/s)</th></tr><tr>
              <th align="right">V        </th><td><CounterComponent xclass="impAdd" controller={this} index={0} /></td></tr><tr>
              <th align="right">R x V    </th><td><CounterComponent xclass="impAdd" controller={this} index={1} /></td></tr><tr>
              <th align="right">V x R x V</th><td><CounterComponent xclass="impAdd" controller={this} index={2} /></td></tr><tr>
              <td colSpan="2"><button onClick={this.insertImpulse.bind(this)}>Insert</button><button onClick={this.clearStopped.bind(this)} >Clear</button></td>
              </tr></tbody></table>                        
            </div>
        );
    }
    
    // This render is the required React method that defines the
    // HTML for the rocket controller.
    render() {        
        
        let buttons;
        if (this.state.paused) {
            buttons = this.stoppedButtons();
        } else {
            buttons = this.runningButtons();
        }
        
        let minApp = "";
        if (this.state.lastMinApp) {
            let d = this.state.lastMinApp.f;
            let t = (this.state.lastMinApp.t-this.anim.time)/86400;
            let tx = (this.state.lastMinApp.t/86400 - 8000);
            minApp = "MinApp: " + d.toFixed(2)+"au  in "+t.toFixed(1)+"d"+" "+tx.toFixed(1);
        }
        
        return  (      
<div>
  <table><tbody>
    <tr><td>
      <table visible={""+!this.controllerOff}><tbody>
        <tr><td colSpan="3" align="center" onClick={this.rev.bind(this)}>R</td></tr>
        <tr>
          <td onClick={this.right.bind(this)}><h3>+</h3></td>
          <td><span id="ControlDisp" style={{width:"50px",height:"50px"}}></span></td>
          <td onClick={this.left.bind(this)}><strong>-</strong></td></tr>
        <tr><td colSpan="3" align="center" onClick={this.fwd.bind(this)}>F</td></tr>
      </tbody></table>        
    </td>
    <td>
      Show orbit:<input type="checkbox" onChange={this.showOrb.bind(this)} /><br/>
      {buttons}
    </td></tr>
   </tbody></table>
   <span>&Delta;V: {this.state["dv"].toFixed(1)} &nbsp; {minApp}</span>
</div>
        );
    }
    
    // Directional buttons.
    fwd() {
        this.setOrient(-Math.PI/2, 0);
    }
    rev() {
        this.setOrient(-Math.PI/2, Math.PI);
    }
    right() {
        this.setOrient(-Math.PI/2, Math.PI/2);
    }
    left() {
        this.setOrient(-Math.PI/2, -Math.PI/2);
    }
    
    // Called after current trajectory is successfully pasted
    // to clipboard. 
    copySuccess() {
        this.anim.setQuickHTML("Trajectory copied to clipboard. "+this.traj.sequence.size+" elements");
    }
    
    // Error in clipboard copy.
    copyFailure(err) {
        this.anim.setQuickHTML("Trajectory copy failed:"+err);
    }
    
    // Attempt to copy the current trajectory sequence to the clipboard.
    copyTraj() {
        navigator.clipboard.writeText(this.traj.sequence.toString())
          .then(this.copySuccess.bind(this), this.copyFailure.bind(this));
    }
    
    
    // Set the orientation of the camera.
    setOrient(x,y){
        let cr = this.rocket.rotation;
        cr.x = x;
        cr.y = y;
    }
    
    // Called only when a new push is seen.
    // Initiates a THRUST command.
    // We add a slight delay to the thrust so that it gets executed in the
    // next segment.
    thrustPushed() {
        if (!this.wasThrusting  && this.anim.delta > 0) {
            let lastState = this.traj.lastState;
            let mag = Util.mag(lastState[1]);
            if (mag < 10) {
                this.anim.setQuickHTML("Speed too small to define direction of thrust");
                return;
            }
            let r = this.rocket.rotation;
            // We add the PI/2 so that we get an x-angle of 0 for the
            // thursts in the view plane.
            const seq = this.traj.sequence;
            let cmd = new Command(this.anim.time, "thrust", ".001 "+(r.x+Math.PI/2)+" "+r.y);
            this.doAddedCommand(cmd);
            this.wasThrusting = true;
        }
    }
    
    // The thrust button is let go. 
    // Initiates an ORBIT command.
    thrustUp() {
        if (this.wasThrusting) {
            let cmd = new Command(this.anim.time, "orbit", null, null);
            this.doAddedCommand(cmd);
        }
        this.wasThrusting = false;
    }
}

export default RocketController;

