import Action from "./Action.js";
import Util   from "../../std/Util.js";

class impulse extends Action {
    constructor(ptr, anim, traj) {
        super(ptr, anim, traj);
    }
    
    // Impulses are only really computed going forwards.  When
    // going backward we just use the orbit we save before we execute the impulse.
    execute() {
        this.saveAndRestoreOrbits();
    }
    
    // This is called by saveAndRestoreOrbits to do the impulse when moving forward.
    actualCommand() {
        let flds    = this.args.posvals;
        let imp = this.getImpulse(flds);
        this.traj.rocket.addImpulse(imp, this.time);
    }
    
    
    restoreOrbit(xtraj, svData) {
        let flds = this.args.posvals;
        let magImp = Util.mag(this.getImpulse(flds));
        this.traj.rocket.updateDV(-magImp);
        if (xtraj.traj.primaryName) {
            xtraj.updLocal(svData.initOrb, this.time);
        } else {
            xtraj.updTraj(svData.initOrb, this.time);
        }        
    }

    
    getImpulse(flds) {
        let imp;
        if (flds.length == 1) {
            let dv    = parseFloat(flds[0]);
            let state = this.traj.rocket.traj.stateVector(this.time);
            let vn    = Util.unit(state[1]);
            imp = Util.times(dv, vn);
        } else if (flds.length == 3) {
            imp =  [parseFloat(flds[0]), parseFloat(flds[1]), parseFloat(flds[2])];
        } else {
            throw Error("Invalid Impulse request:"+this.elem.command.toString());
        }
        return imp;
    }
}

export default impulse;
  