// Get the position and velocity of a point on a surface of a body.
// We can add this to the orbit of the body to get the motion of
// a point on the surface of the body, or just leave it in the body's reference frame
// we use it as the start/stop state for a launch/landing.
import Util        from "../std/Util.js";
import Coords      from "../std/Coords.js";
import SolarSystem from "../animations/SolarSystem.js";

class Rotation {
    constructor(name, l0=0, b0=0) {
        
        // When we land on a body, we will move the ship to the
        // specified location and velocity for the known rotation which
        // may introduce a small glitch in the position and especially the
        // velocity.  If we go backwards this will grow and make the
        // reverse orbit somewhat different from the forward. 
        // We use the entryState to try to make sure that we replicate
        // the glitch going backward.
        this.entryState = {time: -1.e100};
        // Find the body in the list of known solar system objects.
        let data = SolarSystem.getTrackedObject(name);
        if (!data || !data.radius || !data.rotation.rotationPeriod) {
           throw new Error("Inadequate data to land on:"+name);
        }
        this.isRotation = true;
        this.body       = name;
                
        this.period = data.rotation.rotationPeriod;
        let rotAxis = data.rotation.rotAxis;
        this.tRef   = data.rotation.rotationPhase;
        this.lPole  = Util.toRadians(rotAxis.ra);
        this.bPole  = Util.toRadians(rotAxis.dec);        
        
        this.r      = data.radius;     // Radius of body
        this.l0     = l0;              // Lat/lon on surface of body.
        this.b0     = b0;
        
        this.z      = this.r*Math.sin(b0);  // Constant z relative to center of body
        this.cr     = this.r*Math.cos(b0);  // Constant factor in position calculation.
        //
        // Transform from equatorial coordinates to the coordinates of the
        // rotating body.
        let pEq     = Coords.getCoords([this.lPole, this.bPole, 0]).inverse();
        // Add conversion to ecliptic coordinates to transfrom from planetary coords to eq.
        let eqec    = Coords.getCoords("eqec");
        this.trans  = pEq.add(eqec);  // Transformation from body to ecliptic
        
        // Velocity is constant, only direction changes.
        this.v      = 2*Math.PI*this.r/this.period * Math.cos(b0);  // Rotational speed of point
    }
    setEntry(entryState) {
        this.entryState = entryState;
    }
    
    // Get the position in ecliptic coordinates relative to the center of the body.
    position(t) {
        if (t == this.entryState.time) {
            return this.entryState.state[0];
        }
        let lCurr = this.l0 + 2*Math.PI * (t-this.tRef)/this.period ;
        let x = [Math.cos(lCurr)*this.cr, Math.sin(lCurr)*this.cr, this.z];
        // Convert to ecliptic coordinates        
        return this.trans.vTransform(x);
    }
    
    // Get the rotational velocity in ecliptic coordinates.
    velocity(t) {        
        if (t == this.entryState.time) {
            return this.entryState.state[1];
        }
        // Velocity is perpendicular to position, but entirely in x/y plane
        let lCurr = this.l0 + 2*Math.PI * (t-this.tRef)/this.period;
        let v = [-Math.sin(lCurr)*this.v, Math.cos(lCurr)*this.v, 0];
        return this.trans.vTransform(v);
    }
    
    // Position and velocity
    stateVector(t) {
        if (t == this.entryState.time) {
            return this.entryState.state;
        }
        return [this.position(t), this.velocity(t)];
    }
}

export default Rotation;

