import Updater   from "../components/Updater.js";
import Util      from "../std/Util.js";
import Constants from "../std/Constants.js";
import {Vector3} from "three";

// Have the camera follow an object in an orbit.
class Follower extends Updater {
    constructor(anim, targ, movant, orbit, start, duration, zoffset) {
        super(anim, targ, movant, start, duration);
        this.orbit   = orbit;
        this.zoffset = zoffset;
    }
    
    action(time) {
        let pos = this.orbit.position(time);
        let v3 = new Vector3(pos[0], pos[1], pos[2]+this.zoffset);
        this.vector.copy(v3);
    }
}

export default Follower;