import CameraAction     from "./CameraAction.js";
import Command    from "../Command.js";
import TransCalc  from "../../traj/TransCalc.js";
import Util       from "../../std/Util.js"; 
import Constants  from "../../std/Constants.js"; 
import Panner     from "../../components/Panner.js";

import {Vector3}  from "three";
//
//  Pan the camera from one position to another.
//      T0  pan duration [x y z]/[target]
//  pans from the current position at T0 and reaches the target at T1.
//  The last pan must always have no arguments.
class pan extends CameraAction {
    constructor(ptr, anim, traj) {
        super(ptr, anim, traj);
    }
    
    execute(forced) {
        let here = this;
        let forward = this.anim.delta > 0;
        let args    = this.argInfo.posvals;
        let durat   = args.shift();
        durat = Util.parseDuration(durat);
        
        let gen  = this.ptr.elem.generated;
        if (gen == null) {
            gen = false;
        }
        
        function doPan(params) {
            let x = params.position;
            let movant = here.getMovant();
            let y = movant.clone();
            x[2] += here.getZOffset();
            y = [y.x, y.y, y.z];                
            if (forward  && !gen) {
                here.cleanGenerated();
                // Insert a command that will run when going backwards.
                let cmd = new Command(here.ptr.elem.t+durat, "pan", durat+" "+y[0]+" "+y[1]+" "+y[2]);
                if (here.argInfo.keyvals.movant) {
                    cmd.forward += " movant="+here.argInfo.keyvals.movant;
                }
                let seq = here.traj.sequence;
                seq.add(cmd);
                cmd.setGenerated(here);
            }
            if (forward   && !gen) {
                new Panner(here.anim, here.movant, movant, here.ptr.elem.t,       durat, y, x);
            } else if (!forward && gen) {
                new Panner(here.anim, here.movant, movant, here.ptr.elem.t-durat, durat, x, y);
            } else {
            }
        }
        if (gen != forward) {
            this.handlePosition(this.anim.time+durat, args, {}, doPan);            
        }
    }
}

export default pan;