import {Component} from "react";
import Util             from "../std/Util.js";
import RocketController from "../elems/RocketController.js";
import TrajChooser      from "../elems/TrajChooser.js";
import TrajChooser1      from "../elems/TrajChooser1.js";
import TrajWait         from "../elems/TrajWait.js";
import TrajRun          from "../elems/TrajRun.js";
import TrajAfter        from "../elems/TrajAfter.js";
import TrajSequencer    from "../elems/TrajSequencer.js";
import SolarPlanets     from "../solarsystem/SolarPlanets.js";
import Sequence         from "../trajanim/Sequence.js";
import CommandParser    from "../trajanim/CommandParser.js";
import Command          from "../trajanim/Command.js";

class TrajControl extends Component {
    
    // This class ties together the user intervface elements associated with a specific
    // trajectory.  There are a number of elements that we consider:
    //    The small forms that allow the user to select the start and end points for
    //    the trajectory.
    //    The rocket displayed in the animation.
    //    The rocket controller displayed in manual mode.
    //    The rocket sequence of commands
    
    constructor(props){
        super(props);
        // The animation we are currently running in.
        this.anim    = props.anim;
        this.anim.frame.userControls.trajControl = this;
        this.state   = {stage:    props.stage, 
                        sequence: props.sequence, 
                        origin:   props.origin, 
                        dest:     props.dest,
                        noRocket: props.noRocket
                        };
        this.traj    = null;
        if (this.anim.frame.traj) {
            this.traj = this.anim.frame.traj;
            if (props.origin) {
                this.traj.setOrigin(props.origin);
            }
            this.state.sequence = this.traj.sequence;
            this.state.stage = this.traj.sequence.findStage(this.anim.time);
        }
    }
    
    render() {
        
        // We have a number of possible stages:
        //    init:   No sequence or trajectory established.
        //            Can add existing sequence or define start location.
        //    empty:  A sequence with no orbit established.
        //            Can start trajectory at some location.
        //    before: A sequence before the first orbit request.
        //            Can specify destination.
        //    during: A sequence in the middle of the trajectory
        //            Can delete subsequent trajectory requests.
        //    after:  A sequence after the last trajectory request.
        //            Can do manual control or specify destination.
        let stage = this.state.stage;
        if (this.state.sequence && !this.anim.frame.traj) {
            this.anim.frame.traj = new TrajSequencer({anim: this.anim, sequence: this.state.sequence});
            this.anim.frame.traj.setOrigin(this.state.origin);
            this.anim.frame.traj.lastStage = stage;
        }
        
        // Make sure we're connected to the sequencer.
        if (this.anim.frame.traj) {
            this.anim.frame.traj.setInvoker(this);
        }
        
        let noRocket = this.state.noRocket;
        switch (stage) {
            case "init": 
                if (noRocket) {
                    return <div></div>;                    
                }
                return <TrajChooser trajControl={this} anim={this.anim} />;
            
            case "empty": 
                if (noRocket) {
                    return <div></div>;                    
                }
                return <TrajChooser1 sequence={this.state.sequence} trajControl={this} anim={this.anim} />;
            
            case "before":
                return <TrajWait sequence={this.state.sequence} trajControl={this} anim={this.anim} />;
            
            case "during": case "after":
                return <RocketController traj={this.anim.frame.traj} anim={this.anim} />;
                        
            default:
               return <span> Programming error: Unknown trajectory controller stage: stage </span>;
        }
    }
    
    componentWillUnmount() {
        // If we have a trajectory we need to tell it that there's no control to update for
        // the nonce.
        if (this.anim.frame.traj) {
            this.anim.frame.traj.setInvoker(null);
        }
    }
    
    parseProgram(text, src) {
        if (src == null) {
            src = "paste buffer";
        }
        let sequence = new CommandParser().parse(text);
        if (sequence.size == 0)  {
            this.setState({stage: "empty", sequence: sequence});
            this.anim.setQuickHTML("Empty trajectory");
            Util.log("Empty trajectory found after parsing");

        } else {
    
            let strt  = sequence.start() - 86400*30;
            let stage = sequence.findStage(strt);  // Should be "before".
            this.anim.setTime(strt);
            this.setState({stage: stage, sequence: sequence});
            this.anim.setQuickHTML("Initiated saved trajectory: "+sequence.size+" events");
            
            // We don't want this message to hang around forever, so
            // we insert an blank echo command, but mark it as generated
            // by the first real command so it gets deleted when that command
            // is executed going forward.
            let firstCmd = sequence.first.next.elem;
            let xCmd = new Command(sequence.start()-1, "echo", "");
            let ptr = sequence.add(xCmd);
            xCmd.setGenerated(ptr.next);                        
            
        }
            
        Util.log("Read and initiated trajectory from "+src+".");
    }

}

export default TrajControl;
