import Gravity from "../math/Gravity.js";
import VThrust from "../math/VThrust.js";
import CompoundForce from "../math/CompoundForce.js";
import Constants from "../std/Constants.js";
import SolarSystem from "../animations/SolarSystem.js";

class ThrustAndGrav extends CompoundForce {
    constructor(camera, thrust, x, y, trajectory) {        
        super();
        this.thrust = thrust;
        let pos = function(t) { return [0,0,0];};
        let mass = Constants.MSun;
        if (trajectory.primaryName) {
            let data = SolarSystem.getTrackedEntry(trajectory.primaryName); 
            if (data) {
                mass = data.mass;
                pos = function(t) {
                    return trajectory.primary.position(t);
                };
            } else{
                throw new Error("Unknown center for gravity:"+trajectory.primaryName);
            }
        }
        this.add("Grav",   new Gravity(mass, pos));
        this.add("Thrust", new VThrust(thrust, camera, x, y), true);
    }
    magnitude() {
        return Math.abs(this.thrust);
    }
}

export default ThrustAndGrav;