class Particle {
    // params:  the initial set of parameters.
    // cost;    a function that can evaluate the cost of the set of parameters.
    constructor(params, costFunction) {
        this.x          = params;
        this.cost       = costFunction(params);
        this.bestCost   = this.cost;
        this.bestX      = [...this.x]; 
        this.v          = new Array(params.length).fill(0);
    }
}

export default Particle;
