import Action from "./Action.js";

// Camera actions are those where we are trying to adjust the view
// of the camera in some fashion: zoom, pan, rotate.
// Camera actions are normally applied in a continuous fashion to
// smoothly transition over a period of time.

class CameraAction extends Action {
    constructor(ptr, anim, traj) {
        super(ptr,anim,traj);
    }
    
    // For visualization commands, find out whether the camera target or camera positions should
    // be moved.
    getMovant() {
        if (this.argInfo.keyvals.movant == "camera") {
            this.movant = "camera";
            return this.anim.frame.camera.position;
        } else {
            this.movant = "target";
            return this.anim.frame.controls.target;
        }
    }
    
    // For some visualization commands we may wish to add an offset to a target position.
    getZOffset() {
        let val = 0;
        if (this.argInfo.keyvals.zoffset) {
           val =  Number.parseFloat(this.argInfo.keyvals.zoffset);
        }
        return val;
    }

}

export default CameraAction;
