import Animation        from "../elems/Animation.js";
import AnimationFactory from "../animations/AnimationFactory.js";
import Util             from "../std/Util.js";
import Constants        from "../std/Constants.js";

import Satellite        from "../animations/Satellite.js";

import CoordTrans       from "../std/Coords.js";
import Orbit            from "../orbits/Orbit.js";
import TransformedOrbit from "../orbits/TransformedOrbit.js";
import Planet           from "../solarsystem/Planet.js";
import ParameterFactory from "../orbits/ParameterFactory.js";
import SolarPlanets     from "../solarsystem/SolarPlanets.js";
import ssData           from "../data/PlanetaryData.js";
import Satellites       from "../earth/Satellites.js";
import NoradReader      from "../earth/NoradReader.js";
import SolarSystem      from "../animations/SolarSystem.js";

import {Scene, Vector3, Euler, AmbientLight, DirectionalLight} from "three";
import {Mesh, Color, MeshPhongMaterial} from "three";

class PlanetarySystem extends Animation { 

    constructor(planet, params) {
        Util.log("Planetary system: "+planet);
        super(params);
        
        let info = ssData.Sol.planets[planet];
        

        this.delta         = 2;
        this.moons         = {};
        this.longClickTime = 1000;  // A little shorter since
                                    // we do less clicking here.

        this.scene          = new Scene();
        this.name           = planet;
        this.planetName     = planet;
        this.centerBody     = planet;
        this.centralMass    = info.mass;
        this.rotAxis        = info.rotAxis;
        this.rotationPhase  = info.rotationPhase;
        this.rotationPeriod = info.rotationPeriod;
        this.moonInfo       = info.moonInfo;
        this.texture        = info.render.texture;
        this.ring           = info.ring;
        this.satelliteURL   = info.satelliteURL;
        // Don't look past an element of this type.
        this.blockingTypes  = ["planet", "moon"];
        this.sceneCoord     = "PEq";
        if (info.radius  && !this.minScale) {
            // Range from just under the radius to 300 radii
            this.minScale = Math.log10(info.radius)+.1;
            this.maxScale = 2.5 + Math.log10(info.radius);
        } else if (!this.minScale) {
            this.minScale = 6.5;
            this.maxScale = 10;
        }
        
        this.cameraPos     = new Vector3(0,-4,3);  // Note 3/4/5 triangle so five units away in radius.
        this.baseAnimation = "Solar System";
        
        this.segments = 40;
        const here = this;
        // 
        // For displaying a planetary system we want
        // the reference plane to be the equatorial plane of the
        // planet.
        let  xtr = PlanetarySystem.getTransforms(this.rotAxis.ra, this.rotAxis.dec);
        this.eceqE  = xtr.eceqE;
        this.eqEeqP = xtr.eqEeqP;
        this.eqPeqE = this.eqEeqP.inverse();
        
        // Get the planets orbit.  We should use the same orbit as the
        // Solar System animation.
        let planetData    = SolarSystem.solarObjects[this.planetName.toLowerCase()];
        this.planetOrbit  = planetData.orbit;
        this.planetRadius = planetData.radius;  // diameter in km to radius in m.
        this.sceneScale   = this.planetRadius;        
        
        // Convert to local equator.
        this.ecOrbit     = this.planetOrbit;
        this.planetOrbit = new TransformedOrbit(this.planetOrbit);
        this.planetOrbit.addTransform(this.eceqE);
        this.planetOrbit.addTransform(this.eqEeqP);  
        
        // Find the ecliptic pole in planetary coordinates.
        let ecPole = [0,0,1];
        ecPole = this.eceqE.vTransform(ecPole);    // In Earth equatorial coordinates.
        ecPole = this.eqEeqP.vTransform(ecPole);   // In planet equatorial coordinates.
        let theta = Math.asin(ecPole[2]);          // Latitude of pole
        let alpha0  = Math.atan2(ecPole[1], ecPole[1]);
        
        // ... and the planet pole in ecliptic coordinates.
        let pPole = [0,0,1];
        pPole = this.eqEeqP.invTransform(pPole);
        pPole = this.eceqE.invTransform(pPole);
        let alpha1  = Math.atan2(pPole[1], pPole[0]);
        
        this.eceqP = CoordTrans.getCoords([alpha1, theta, alpha0]);
        
        const r0         = this.planetOrbit.position(this.time);

        const sunlight = new DirectionalLight(0xffffff, 1);
        sunlight.position.x = -1000*r0[0];
        sunlight.position.y = -1000*r0[1];
        sunlight.position.z = -1000*r0[2];
        sunlight.castShadow = true;        
        let sunl = {name: "sunlight", component: sunlight,
                         render: function(time) {
                             const r0 = here.planetOrbit.position(time);
                             
                             sunlight.position.x = -1000*r0[0];
                             sunlight.position.y = -1000*r0[1];
                             sunlight.position.z = -1000*r0[2];
                         }};
        this.addElement("sunlight", sunl, true);
                     
        this.scene.add(new AmbientLight(0x333333));

        var radius   = 1;
        let centralBody = this.createPlanet(this.planetName, radius, this.texture, this.ring);
        centralBody.component.meta = {...info, name: this.planetName, type: "planet"};
        this.addElement(this.planetName, centralBody);
        this.addTimeDisplay();
        
        if (this.moonInfo) {
            this.addMoons(this.moonInfo);
        }
        
        if (this.satelliteURL) {
            NoradReader(this.satelliteURL, this.addSatellites.bind(this));
        }
        
        this.coordSystem = this.eceqP;                
    }
    
    // Get desired transforms
    //    ra,dec are the coordinates of the north pole of the rotation axis
    // in Earth equatorial coordinates.
    static getTransforms(ra,dec) {
        let eceqE = CoordTrans.getCoords("eceq");        
        // transformation from Earth equatorial to planet equatorial
        let  angs = [ra, dec, Math.PI/2];
        let eqEeqP = CoordTrans.getCoords(angs);
        return {eceqE:eceqE, eqEeqP:eqEeqP};
    }
    
    // Find the center of the animation in heliocentric ecliptic coordinates
    center(t) {
        return this.ecOrbit.stateVector(t);
    }
                
    findBody(name, time) {
        if (this.moons[name]) {
            return this.moons
        }
    }
    
    // We set this up as a static method so that we
    // can get to moon orbits in trajectory calculations.
    static moonOrbit(md, planetRadius, ra, dec, time) {
       // The orbit in whatever system the data base given
       let   morbBase = PlanetarySystem.getBaseMoonOrbit(md, planetRadius, time);
       // The orbit in the frame of the planetary system animation.
       let morbPEq = new TransformedOrbit(morbBase);
       let xtr = PlanetarySystem.getTransforms(ra, dec);
       let eceqE  = xtr.eceqE;
       let eqEeqP = xtr.eqEeqP;
       let eqPeqE = eqEeqP.inverse();
            
       // The orbit (relative to the planet), in a frame aligned with
       // heliocentric ecliptic coordinates.  We can just add this
       // toe the planets orbit to get the position of the moon relative
       // to the solar system center of mass.
       let morbEEc = new TransformedOrbit(morbBase);
       let moonTrans = CoordTrans.getCoords("unit");
            
       if (md.frame && md.frame.type != "Equatorial") {
           if (md.frame.type == "Ecliptic" ) {
               // Same transformation as for planet orbit.
               moonTrans = moonTrans.add(eceqE);
               moonTrans = moonTrans.add(eqEeqP);
               morbPEq.addTransform(moonTrans);
                  
            } else if (md.frame.type == "Laplace") {
                // The Laplace axis is given in Earth Equatorial coordinates.
                // So we transfrom from the Laplace frame to the Earth equatorial
                // frame and then from the EEq to PEq
                // Need the transform from Earth
                // equatorial to the Laplace frame.
                    
                // lapTrans is transform from EEq to Lap
                const lapTrans = CoordTrans.getCoords([md.frame.ra,md.frame.dec,Math.PI/2]);
                moonTrans = lapTrans.inverse();
                moonTrans = moonTrans.add(CoordTrans.getCoords("eqec"));
                morbPEq.addTransform(lapTrans.inverse()); // Lap -> EEq;
                morbPEq.addTransform(eqEeqP);        // EEq -> PEq
                    
                // We want to end in standard ecliptic coordinates, so we just instead
                // of converting from Earth equatorial to Planet equatorial, we
                // convert to Earth ecliptic.
                morbEEc.addTransform(lapTrans.inverse());
                morbEEc.addTransform(CoordTrans.getCoords("eqec"));
            }
        }
        return [morbPEq, morbEEc, moonTrans];        
    }
    
    addMoons(moonInfo, time) {
        for (let moonName in moonInfo) {
            const md   = moonInfo[moonName];
            let [morbPEq, morbEEc, moonTrans] = 
                    PlanetarySystem.moonOrbit(md, this.planetRadius, this.rotAxis.ra, this.rotAxis.dec, this.time);
            
            // Usually we expect that the moon's rotation is tidally locked and we infer the
            // period and plane from the primary, but we allow this to be specified explicitly/
            let rotation = null;
            if (md.rotationPeriod) {
                rotation = {rotationPeriod: md.rotationPeriod, rotationPhase:md.rotationPhase,
                            rotAxis: md.rotAxis};
            }
            SolarSystem.addTrackedObject(moonName, this.planetName, morbEEc, md.mass, md.radius, rotation);
            var rad = 0.2;
            if (md.render && md.render.frac) {
                rad = md.render.frac;
            }
            
            // Outer moons disappear so make them bigger
            let ratio = md.elems.a/this.planetRadius;
            if (ratio > 300) {
                rad = 1;
            } else if (ratio > 20 && ratio <= 200) {
                rad = 0.2 + 0.8*Math.log10(ratio/20);
            }
            
            var moon;
            var color = md.render.color? md.render.color: 0xFFFF00;
            
            moon = Planet(moonName, this.time, 
                          morbPEq, rad, color, false, true);
            let meta = {...moonInfo[moonName], name: moonName, type: "moon", orbit: morbPEq};
            moon.component.meta = meta;
                          
            if (md.render && md.render.texture) {
                // Replace the featureless sphere
                let pos = morbPEq.position(this.time);
                let texturedSphere = this.createSphere(rad, this.segments, md.render.texture);               
                texturedSphere.position.set(pos[0], pos[1], pos[2]);
                moon.component = texturedSphere;
                moon.component.meta = meta;
            }
            
            this.addElement(moonName+"Body", moon);
            this.moons[moonName] = {rendering: moon, data: md, orbit: morbPEq, ecOrbit: morbEEc, moonTrans: moonTrans};
        }

    }
    
    createPlanet(name, radius, texture, ring) {
        const planet = this.createSphere(radius, this.segments, texture, ring, name);
        const here = this;
        return {
            name:      name,
            component: planet,
            render:    function(time) {
                let phase = here.rotationPhase + 2*Math.PI * (time/here.rotationPeriod);
                phase %= 2*Math.PI;
                planet.rotation.y = phase; 
            }
        }      
    }
    static getBaseMoonOrbit(moonData, planetRadius, time) {
        let  morb = new Orbit();
        let mElems = moonData.elems;
        if (mElems.t == null) {
            if (moonData.prec) {
                mElems.t = moonData.prec.ep0;
            } else {
                mElems.t = time;
            }
        } else {
        }
        morb.addStructure(moonData.elems);
        const rm = morb.getParameter("r", true);
        morb = morb.quickOrbit();  // Just get this...
        if (moonData.prec) {
            morb.addPrecession(
                moonData.prec.ep0,
                moonData.prec.fOmega,
                moonData.prec.fNu
            );
        }
        morb.scale = 1/planetRadius;
        return morb;
    }
    
    find(name, callback) {
        let here = this;
        function find2(found) {
            if (!here.satelliteData) {
                callback(found);
                return;
            }
            let regstr = "^"+name.replaceAll("*", ".*")+"$";
            let regex = new RegExp(regstr, "i");
            
            for (let i=0; i<here.satelliteData.length; i += 1) {
                let sat = here.satelliteData[i];
                if (sat.name.match(regex)) {
                    let meta = {...sat, type:"satellite"};
                    found.push({meta: meta, distance: 0});
                }
            }
            callback(found);
        }
        super.find(name, find2);
    }
    
    addSatellites(data, epoch) {
        Util.log("Epoch for satellites: "+epoch/(365.25*86400));
        Util.log("Number of satellites: "+data.length);
        this.satelliteData = data;
        if (!this.frame.times) {
            this.frame.times = {};
        }
        this.addMetaTime("sat", epoch);
        this.addElement("satellites", Satellites(data, epoch));
        this.finish();
    }

    doLongClick(event) {
      
        const matched = this.frame.raycast(event);
        let found = null;
        
        for (let i=0; i<matched.length; i += 1) {
            let meta = matched[i].meta;
            if (meta.type == "moon" && this.moonInfo[meta.name].render.texture) {
                this.animateMoon(meta.name);
                return;
            }
        }
        super.doLongClick(event);
    }
    
    animateMoon(name) {
        let moon = this.moons[name];   // This is the displayed component.
        let meta = moon.data;
        let anim = new Satellite({
          frame:            this.frame,
          name:             name,
          meta:             meta,
          planet:           this.name,
          animationParent:  this,
          centralMass:      meta.mass,
          planetOrbit:      this.planetOrbit,
          planetEcOrbit:    this.ecOrbit,
          primary:          this.name,
          satelliteOrbit:   moon.orbit,
          satelliteEcOrbit: moon.ecOrbit,
          satelliteFrame:   moon.moonTrans,
          sceneScale:       meta.radius,
          texture:          meta.render.texture,
          cameraPos:        new Vector3(0, -4, 3)
        });
        this.frame.setAnimation(anim);
        return;
    }
}

export default PlanetarySystem;