import MotionAction     from "./MotionAction.js";
import ThrustAndGrav    from "../../math/ThrustAndGrav.js";
import ThrustByGradient from "../../math/ThrustByGradient.js";
import TrajGradient     from "../../traj/TrajGradient.js";
import OrbitsDiff       from "../../orbits/OrbitsDiff.js";
import Constants        from "../../std/Constants.js";

class thrust extends MotionAction {
    constructor(ptr, anim, traj) {
        super(ptr, anim, traj);
    }
    
    // Going forward initiate continuous thrust in the direction specified.
    // Going backward go into the orbit defined by the current state.
    doAction(delta, command, flds) {
        console.log("Thrust starts!");
        let mag  = parseFloat(flds[0]);
        

        // Thrust along velocity axis
        if (flds.length == 1) {
            this.thrustAlongVelocity(mag);
        } else if (flds.length == 2) {
            this.thrustByFunction(mag, flds[1]);
        } else if (flds.length == 3) {
            this.thrustInDirection(mag, parseFloat(flds[1]),                                                         parseFloat(flds[2]));
        } else {
            throw new Error("Illegal THRUST command: "+this.elem.toString());
        }
    }
    
    thrustAlongVelocity(mag) {
        // The time this transition is occurring.
        let time = this.time;
        if (this.forced) {
            time = this.forceTime;
        }
              
        let force = new ThrustAndGrav(this.anim.frame.camera, mag, 0, 0, this.traj);
        this.traj.rocket.setToIntegrate(time, force);
            
        if (mag < 0  && this.anim.delta > 0) {
            // Need to worry about undefined velocity.
            let here = this;
            function zerov(exc) {
                // Need to insert an orbit command at the time of the issue
                if (exc.meta && exc.meta.cause == "zerov") {
                    let t     = exc.meta.t;
                    let state = exc.meta.lastState;
                    here.anim.frame.traj.changeToOrbit(t, state);
                    exc.meta.status = "handled";                        
                    // Rethrow the exception so that we
                    // don't return from this call successfully.
                }
                return false;
            }
            force.setHandler(zerov);
        }
    }
    
    thrustByFunction(mag, target) {

        let here = this;
        
        let runFunction = this.runThrust.bind(this);
        let params = {mag: mag};
        this.getNamedOrbit(target, this.time, params, runFunction);
    }
    
    runThrust(params) {
        let goal = params.orbit;
        let grad  = new OrbitsDiff(goal);
        grad.setThrust(params.mag);
        // We invert the force since we want to minimize the function.
        // If we wanted to maximize it we'd use a positive value.
        
        // We need to worry about ravelling and unravelling.
        // We may need to unravel before initiating thrust,
        // and ravel after we reach the destination orbit.
        let force = new ThrustByGradient(-params.mag, grad);
        this.traj.rocket.setToIntegrate(this.time, force);
        let here = this;
        function match(exc) {
            // Need to insert an orbit command at the time of the issue
            if (exc.meta && exc.meta.cause == "match") {
                let t     = exc.meta.t;
                let state = exc.meta.lastState;
                here.anim.frame.traj.changeToOrbit(t, state);
                exc.meta.status = "handled";
                // Rethrow the exception so that we
                // don't return from this call successfully.

            }
            return false;
        }
        force.setHandler(match);

    }
    
    thrustInDirection(mag, x, y) {
        let force = new ThrustAndGrav(this.anim.frame.camera, mag, x, y, this.traj);
        this.traj.rocket.setToIntegrate(this.time, force);
    }
}

export default thrust;

