import Action from "./Action.js";

class hide extends Action {

    constructor(ptr, anim, traj) {
        super(ptr, anim, traj);
    }
    
    execute() {
        let reverse = this.anim.delta < 0;
        this.execAs(reverse);
    }
    
    // Show or hide the elements indicated.
    execAs(setVisible) {
        let fields = this.ptr.elem.forward.split(/\s+/);
        for(let i in fields) {            
            let field = fields[i];
            
            // Check if we have a wildcard match.
            let asterisk = field.indexOf("*");
            if (asterisk >= 0) {
                
                let matches = new RegExp( field.substring(0, asterisk) + '.' + field.substring(asterisk));
                
                // Wild card match against elements of the current animation.
                // When we go backwards we should be in the same animation,
                // so we don't need to do anything special to keep this reversible.
                for (let name in this.anim.sceneElements) {
                    if (name.match(matches)) {
                        this.anim.frame.setVisibility(name, setVisible);
                    }
                }
                
            // No wildcard, just update the visibility of the specified element.
            } else {
                this.anim.frame.setVisibility(field, setVisible);
            }
        }
    }    
}

export default hide;
    
