import Util      from "../std/Util.js";
import Constants from "../std/Constants.js";
import QOrb      from "../orbits/QOrb.js";
import CalcAccel from "../traj/CalcAccel.js";

// This class calculates an offset between two orbits.  The functions
// are designed to have a global minimum of 0 only when the two orbits
// are identical.
// 
// The offset is calculated as a weighted sum of one or more functions using
// either the four default functions specified here, or other functions supplied
// by the user.  The functions may be changed at any time.
//
// The functions should the difference between two orbits in
// units of velocity-squared.  With these units we have a check on
// whether we may be using too large a time step.

// Each function should take arguments in the following order:
//    test: The orbit to be tested.
//    want: The desired orbit.
//    gm:   G x the mass of the primary.


// Difference in semimajor axis.  
function semi(test, want, gm) {
    // GM/a0 - GM/a1 = deltaV^2
    let a0 = want.a;
    let a1 = test.a;
    let val =  Math.abs( gm * (a1 - a0)/(a1*a0));
    // But the above has a non-differentialble minimum at the desired value 
    // (from the Math.abs) so we multiply by the following factor
    // which gives us a gentler minimum.
    val *= (a1-a0)*(a1-a0)/ (a0*a0);
    return val;
}

 
    
// Difference between the angular momenta, scaled by
// the semi-major axis to give a velocity.
function ang(test, want) {
    let r0 = test.rot;
    let r1 = want.rot;
    let v0 = want.Lm/want.a;  // Typical velocity.
    
    // l0 and l1 are the unit vectors of the angular momentum.
    let l0 = [r0[1], r0[3], r0[4]];
    let l1 = [r1[1], r1[3], r1[4]];
    
    let diff = Util.diff(l0, l1);
    return v0*v0*Util.dot(diff, diff);
}

// Difference in phase.  The use of the sine function means that we have 0's
// for any time value which is offset by an integral number of periods
// from the wanted value.  Note the factor of 0.5 since we only
// wnat this to be 0 when the phases match, not when they are
// exactly opposite.  We multiply by the average speed around the orbit.
// to convert to velocity.
function t0(test, want) {
    let v0 = want.Lm/want.a;
    let sin = Math.sin(0.5*Math.PI*(want.t0 - test.t0));
    return sin*sin*v0*v0;
}

// Difference in the eccentricity vectors.  This depends upon the argument
// of periastron as well as the eccentricty.  For the nonce we simply return
// the distance, but this may result in this term having insufficient weight...
function ecc(test, want, gm) {

    // We use the result that the eccentricity vector points to periastron
    // and has a magnitude equal to the scalar eccentricty.
    function getEcc(orb) {
        let r = orb.rot;
        let e = orb.e;
        // In the standard orbit context we need to add the true anomaly to
        // the argument of periastron here, so in the general case it is premature to
        // store the sine/cosine.  That's why we have the actual value
        // of the argument of periastron while we precomputed the sine/cos of the 
        // other angles.
        let cnu = Math.cos(r[5]);
        let snu = Math.sin(r[5]);
        const x = e*(r[0]*cnu - r[1]*snu);
        const y = e*(r[2]*cnu + r[3]*snu);
        const z = e*snu*r[4];
        return [x,y,z];
    }

    // These are the eccentricity vectors.
    let e0 = getEcc(test);
    let e1 = getEcc(want);

    // e_vec = (v x L)/GM - r_norm;
    // but the first term is v x (r x v).  so dimensionally its rv^2.
    // So we can get a value for the needed velocity difference...
    let de  = Util.mag(Util.diff(e0, e1));
    let dv2 = gm*de/want.a;
    return dv2;
}


class OrbitsDiff {
    
    // Get an object to find the difference.
    // We supply the desired orbit and optionally the GM of the central body.
    constructor(to, gm) {
        this.funcs = {};
        this.n     = 0;
        // Add in the default functions
        this.addFunc("semi", semi, 20);
        this.addFunc("t0", t0, .0000001);
        this.addFunc("ecc", ecc, .0000001);
        this.addFunc("ang", ang, .0000001);
        this.to = to;
        this.gm = gm;
        if (this.gm == null) {
            this.gm = Constants.GMSun;

            
            
            this.count = 1
        }
        // The magnitue of small changes in velocity used to evaluate the gradient.
        this.dv = 0.01  // e.g., 1 cm/s
        
        // If the offset is smaller than this value, we assume that we have reached
        // the desired orbit.
        this.matchValue = 0.1 // m/s
        this.completed = false;
        this.thrust = 0;
    }
    setThrust(mag) {
        this.thrust = mag;
    }

    // Add a function to the set of distances giving a name (to allow it to be deleted),
    // the function itself -- which should not require anything other than the current orbit,
    // the desired orbit, and the GM value.
    addFunc(name, func, weight) {
        this.funcs[name] = {func: func, weight: weight};
        this.n += 1;
    }

    // Delete a named function.
    delFunc(name) {
        if (this.funcs[name]) {
            delete(this.funcs[name]);
            this.n -= 1;
        }
    }
    
    // Calculate the gradient from the current orbit to the 
    // desired orbit.  Note that this uses the state vector information
    // rather than specifying the current orbit.
    gradient(x, v, t) {
        let params = {r: x, v: v, t: t, GM: this.gm};
        this.count += 1;
        let curr   = QOrb.stateOrbit(params);
        let base   = this.delta(curr);
        if (base < this.matchValue) {
            if (!this.completed) {
                console.log("Throwing completion", this.completed);
                this.completed = true;
                console.log("Offset is near 0:", base);
          
                
                
                let err = new Error("");
                err.meta = {};
                err.meta.cause     = "match";
                err.meta.t         = t;
                err.meta.lastState = [x,v];
                console.log("About to throw: ", err);
                console.log("  meta:", err.meta);
                console.log("Calling window.stop");
                throw err;
            } else {
                console.log("Already completed at time:", t);
                throw new Error("Multiple completion");
            }
        }
        this.lastOffset = base;
/*        let calc = new CalcAccel(curr, this.to);
        let t1   = calc.getThrustTime(t, this.thrust);
        let fit  = calc.getEqMag(t, t1);
        return Util.times(-1, fit.accels[0]);*/
        let grad = [];
        for (let i = 0; i< 3; i += 1) {
            let vc   = [...v];
            vc[i]   += this.dv;
            params.v = vc;
            curr     = QOrb.stateOrbit(params);
            let tst  = this.delta(curr);
            grad[i]  = (tst-base)/this.dv; 
        }
        let gradval = Util.mag(grad);
        let cosang = Util.dot(grad, v)/(Util.mag(grad)*Util.mag(v));
        let ang = Util.toDegrees(Math.acos(cosang));
        if (this.count % 100 == 0) {
            console.log("Velocity offset angle:",this.count, base, ang);
        }
        return grad;
    }
    
    getLastOffset() {
        return this.getLastOffset;
    }
    
    delta(curr) {
        let sum    = 0;
        let weight = 0;
        for (let name in this.funcs) {
            let wgt = this.funcs[name].weight;
            weight += wgt;
            let val = this.funcs[name].func(curr, this.to, this.gm);
            sum += wgt*val;
            if (this.cnt % 100 == 0) {
                console.log(cnt, name, this.funcs[name].weight, val, sum, weight);
            }
        }
        return sum/weight;
    }
}

export default OrbitsDiff;
