import Util        from "../std/Util.js";
import Constants   from "../std/Constants.js";
import Equinoctial from "../orbits/Equinoctial.js";
import Feather     from "../math/Feather.js";

/** This class implements a continuous thrust from one orbit to another. 
 * 
 *  We use equinoctial coordinates to represent the two orbits and smoothly
 *  interpolate between the two over the interval.  Note that while we can
 *  get the positions this way, the velocity is not the velocity of the interpolated
 *  orbit.  Instead we use numerical differentialtion to get the velocity and if
 *  needed acceleration.
 */
class Burn {
    // from: The initial orbit
    // to:   The final orbit
    // tstart: Time initial orbit is left
    // to:   Time final orbit is achieved.
    constructor(from, to, tstart, tend) {
        console.log("In my new constructor");
        console.log("To t0 is:", to.t0);
        this.tstart = tstart;
        this.tend   = tend;
        this.fromTest = from;
        this.eqFrom = Equinoctial.getElems(from);
        this.eqTo   = Equinoctial.getElems(to);
        let sqgm     = this.eqFrom.sqGM;
        this.GM     = sqgm * sqgm;
        this.timeInt = tend-tstart;
        
        // In principal the reference times for the orbits can be very different
        // since they are really only modulo the orbital period.  Make sure
        // that we use the nearest possible reference times.
        this.fixT0(from,to);
        
        console.log("Initiall:", this.timeInt, from.per, to.per);
        // Find the smallest relevent time scale.
        if (from.per < this.timeInt) {
            this.timeInt = from.per;
        }
        if (to.per < this.timeInt) {
            this.timeInt = to.per;
        }
        this.feather = Feather.quadFeather(0.1);
        this.lastT   = null;
        console.log("TimeInt:", this.timeInt);
    }
    
    fixT0(from, to) {
        // If we have two hyperbolic orbits, don't do anything.
        if (from.e >= 1 && to.e >= 1) {
            return;
        }
        
        let orbits;
        let chng;
        
        // If the 'from' orbit is hyperbolic but the final orbit isn't,
        // then get the closest periapsis for the 'to' orbit to the
        // perapsis of the 'from' orbit.
        if (from.e >= 1) {
            orbits = (from.t0 - to.t0)/ to.per;
            chng = t0;
            
        } else if (to.e >= 1) {
            orbits = (to.t0 - from.t0)/ from.per;
            chng   = from;
        } else {
            // Both bound orbits.
            // In principal we can find some time where the t0's are close,
            // but we don't want to move the reference times too much.
            let small = from;
            let big   = to;
            if (from.per > to.per) {
                small = to;
                big   = from;                
            }
            orbits = (big.t0 - small.t0)/small.per;
            chng = small;
        }
        
        let n     = Math.trunc(orbits);
        let delta = orbits-n;
        if (delta > 0.5) {
            n += 1;
        } else if (delta < -0.5) {
            n -= 1;
        }
        // Change the periapsis time.
        chng.t0 += n*chng.per;
    }
    
    position(t, noCheck) {
        // Allow test beyond limits (for velocity and force calculations
        let delta = (t-this.tstart)/(this.tend-this.tstart);
        
        // Are we feathering the interpolation?
        if (this.feather) {
            delta = this.feather(delta);
        }
        
        if (!noCheck) {
            if (t < this.tstart || t > this.tend) {
                console.log("Invalid checked time in burn:", t, this.tstart, this.tend);
                throw new Error("Burn time imvalid");
            }
        }
        
        let eqOrb = Equinoctial.interp(this.eqFrom, this.eqTo, delta);
        let orb   = Equinoctial.getOrbit(eqOrb);
        return orb.position(t);
    }
    
    stateVector(t) {
        return [this.position(t), this.velocity(t)];
    }
    
    // Determine the velocity by numeric differntiation of the position
    velocity(t) {
        //  v(t) = (p(t+dt) - p(t-dt))/ (2 dt)
        let deltaP = 1.e-8*this.timeInt;
        let pm = this.position(t-deltaP, true);
        let pp = this.position(t+deltaP, true);
        return Util.times(0.5/deltaP, Util.diff(pp, pm));
    }
    
    // Determine the acceleration by numeric differention of the position.
    // Note that we use a somewhat larger step than for velocity.  We have
    // the untested intuition that this will give a more stable acceleration.
    accel(t, pos) {
        if (pos == null) {
            pos = this.postion(t);
        }
        //  a(t) = (p(t+dt) + p(t-dt) = 2 [(t)) / dt
        let deltaP = 1.e-6*this.timeInt;
        let pm = this.position(t - deltaP, true);
        let pp = this.position(t + deltaP, true);
        let v0 = Util.diff(pos,pm);
        v0 = Util.times(1/deltaP, v0);
        let v1 = Util.diff(pp, pos);
        v1 = Util.times(1/deltaP, v1);
        let a  = Util.diff(v1, v0);
        let r3 = Math.pow(Util.mag(pos), 3);
        let fG = Util.times(-this.GM/r3, pos);
        let mfG = Util.mag(this.fG);
        let vsum = Util.vadd(pp, pm);
        vsum = Util.vadd(vsum, pos, -2);
        let tacc = Util.times(1/(deltaP*deltaP), vsum);
        let acc  = Util.diff(tacc, fG);
        return acc;
    }
}

export default Burn;