import CalcAction from "./CalcAction.js";
import Command    from "../Command.js";
import Util       from "../../std/Util.js";
import GenTraj    from "../../traj/GenTraj.js";

// This class supports the trajectory command which
// allows for a variety of different kinds of trajectorys
// to be executed.  In this context a trajectory is a series
// of impulses which are connected by periods of free orbiting.
// 
// The arguments to the trajectory are generally keywords except
// for tStart which is inferred from reference time of the trajectory command
//     dest     - the destination object (required)
//     tStart   - the earliest time any impulses may occur.
//                Set as the reference time of the command
//     tEnd     - the latest time any impulses may occur.
//                Defaults to twice the synodic period after tStart.
//     nMid     - the number interior impulses.  Defaults to 0
//     startFixed - flag indicating that the first impulse should be exactly at tStart.
//                Defaults to false
//     endFixed   - flag indicating the the last impulse should be at exactly tEnd
//                Defaults to false
//     duration   - the exact duration of the trajectory from first impulse to last.
//     within     - the length of an interval from tStart in which the trajectory is to finish
//                  Equivalent to setting t0 tEnd the appropriate date.
//     durFixed   - Flag to indicate that the duration is not allowed to vary.  Defaults to false.
//     impulseMag - intermediate impulses are to have a fixed magnitude.  Defaults to null
//     srcVe      - The escape velocity from the original orbit. Defaults to 0.
//     dstVe      - The escape velocity of the destination. Defaults to 0.
//  Examples:
//      trajectory dest=Mars   -- lowest dV transfer to Mars with just two impulses within next two synodic periods.
//      trajectory dest=Mars within=5y -- two impulse transfer to Mars within the interval starting at the time
//                                        command and finishing within 5 years
//      trajectory dest=Mars within=5y duration=180d -- As above, but with an exact duration of 180 days.
//      trajectory dest=Mars nMid=2 srcVe=11200 dstVe=5000 within=3y -- Four impulse transfer to Mars in
//                                        the next 3 years with the cost of the first and last impulses
//                                        calculated assuming a dV near the surface of the planets
//                                        so that the cost of these impulses is less.  However
//                                        the escape velocities themselves will be added to the total
//                                        cost
//      trajectory dest=Mars tEnd=2024-10-10 endFixed  -- Calculate the best transfer which ends at
//                                         the specified time.

class trajectory extends CalcAction {
    constructor(ptr, anim, traj) {
        super(ptr, anim, traj);
    }
    
    
    // Find the best impulses that meet the requirements.
    computeAction(curr, dest, gm) {
        this.findFlags();
        this.normVals();

        let tr    = new GenTraj(this.args.keyvals, curr, dest, gm);
        let imps  = tr.getImpulses();
        let t0    = imps[0].t;
        let t1    = imps[imps.length-1].t;
        return {t0: t0, t1: t1, data: imps};
    }
    
    // Add the impulses into the command sequence.
    addCommands(str) {
        let imps = str.data;
        for (let i in imps) {
            let imp     = imps[i];
            let impcmd  = new Command(imp.t, "impulse", imp.imp.join(" "));
            impcmd.setGenerated(this);
            this.traj.sequence.add(impcmd);
        }
    }
    
    // Allow just fixedStart/End in argument list.
    findFlags() {
        let pos  = this.args.posvals;
        let keys = this.args.keyvals;
        for (let i=0; i<pos.length; i += 1) {
            let arg = pos[i].toLowerCase();
            if (arg == "fixedstart") {
                keys.fixedstart = true;
            }
            if (arg == "fixedend") {
                keys.fixedend = true;
            }
        }
    }
    
    // Convert the input keys to standard units as needed.
    normVals() {
        let keys = this.args.keyvals;
        
        // Use the command time as the start time.
        keys.starttime = this.ptr.elem.t;
        
        if (keys.endtime != null) {
            keys.endtime = Util.parseTime(keys.endtime);
        }
        if (keys.within != null) {
            keys.within = Util.parseDuration(keys.within);
        } 
        if (keys.duration != null) {
            keys.duration = Util.parseDuration(keys.duration);
        }
        if (keys.srcve != null) {
            keys.srcve = Util.parseWUnits(keys.srcve);
        }
        if (keys.dstve != null) {
            keys.dstve = Util.parseWUnits(keys.dstve);
        }
        if (keys.impulsemag != null) {
            keys.impulsemag = Util.parseWUnits(keys.impulsemag);
        }
    }
}
export default trajectory;
