import Action from "./Action.js";
import Command from "../Command.js";

class animation extends Action {
    constructor(ptr, anim, traj) {
        super (ptr, anim, traj);
    }
    // Change the speed of the animation.  The argument
    // is the number of steps to increase (decrease if negative)
    // the speed when going forward.  Each step increases the time
    // delta by sqrt(2).  Negative values slow down.  When going backwards
    // the negative if the value is used.  
    execute() {
        let dest = this.ptr.elem.forward;
        let curr = this.anim.name;
        let bck = this.anim.delta < 0;  // Are we moving backward?
        let gen = this.ptr.elem.generated !== false;  // Is this a generated command.
        
        // Only execute generated animations when going backward
        // and non-generated changes going forward.
        let newTime = this.time;
        if (gen === bck) {
            if (this.anim.setAnim(dest)) {
                // Insert a command to send us back to the current animation.
                if (!gen) {
                    let command = new Command (this.time, "animation", curr);
                    command.setGenerated(this.ptr.elem);
                    this.traj.sequence.insert(this.ptr, command);
                }
            } else {
                throw new Error("Unable to find requested animation");
            }
        }
    }
}

export default animation;

