import  {Component}     from "react";
import Util             from "../std/Util.js";
import Dump             from "../std/Dump.js";
import Constants        from "../std/Constants.js";
import TrajArgs         from "../traj/TrajArgs.js";
import TimeFormatter    from "../elems/TimeFormatter.js";

import nelderMead       from "../benfred/nelderMead.js";

class TrajCalculator extends Component {
    // The value is the underlying value of the parameter in unscaled units.
    // The entry is how the user entered it.
    // Validated indicates that the parameter has not been modified
    // since the last time it was validated.  Computed indicates
    // that the parameter was calculated, not entered.
    // unitIndex is the current index for the unit being used for this
    // parameter.  InitUnit is the unit index in which a non-computed parameter
    // was entered.
    constructor(props) {
        super(props);
        this.displayCount = 0;
        // Note that the states for each row are indexed
        // by the unique row names.
        this.state = {
            frombody:  'Earth',
            tobody:    'Mars',
            starttime: '2001-01-01',
            endtime:   '+5y',
            fixstart:  false,
            fixend:    false,
            duration:  '',
            vescstart: '',
            vescend:   '',
            vmaxfinal: '',
            midpoints: '0',
            haveCalc: false
        }
    }
    
    update(e) {
        let id=e.target.id;
        let v   = {haveCalc: false};
        ``
        let val = null;
        if (id.startsWith("fix")) {
            val = !this.state[id];
        } else {
            val=e.target.value;
        }
        v[id] = val;
        this.setState(v);
    }
        
    
    // This may be from an invoking page.
    setAnimFactory(animFactory) {
        this.animFactory = animFactory;
    }

 
    render() {
        let upd = this.update.bind(this);
        return (
    <div style={{margin:30}}>         
    <h2><a href="./traj.html" target="help"> Trajectory Calculator </a></h2>
        
        <table border='1'>
            <tbody>
                <tr><th colSpan='2' align='center' >Required</th></tr>
                <tr><th align='center'>From:</th><th align='center'>To:</th></tr>
                <tr><td><input onChange={upd} size='15' value={this.state.frombody} id='frombody' placeholder='source'     /></td><td>
                        <input onChange={upd} size='15' value={this.state.tobody}   id='tobody'   placeholder='destination'/></td></tr>
                <tr><th align='center'>Start after</th><th>End before</th></tr>
                <tr><td><input size='15' onChange={upd} id='starttime' value={this.state.starttime} placeholder='ISO or MJD' /></td><td>
                        <input size='15' onChange={upd} id='endtime'   value={this.state.endtime}   placeholder='ISO, MJD or delta'/> </td></tr>
                <tr><td align='center'> 
                Fixed: <input onChange={upd} id='fixstart' type='checkbox' checked={this.state.fixstart}/></td><td align='center'>
                Fixed: <input onChange={upd} id='fixend'   type='checkbox' checked={this.state.fixend}/></td></tr>
                <tr><td colSpan='2'><hr/></td></tr>
                <tr><th colSpan='2' align='center' >Optional</th></tr>
                <tr><th align='left'>Duration:<input size='8' onChange={upd} value={this.state.duration} id='duration' placeholder='s, d or y'/></th><th aligh='right'>
                Midpoints:<input size='2' id='midpoints' value={this.state.midpoints} onChange={upd} /></th></tr>
                <tr><th colSpan='2' align='center'>Escape Velocities</th></tr>
                <tr><td>Source</td><td>Destination</td></tr>
                <tr><td><input onChange={upd} size='15' id='vescstart' value={this.state.vescstart} placeholder='m/s' /></td><td>
                        <input onChange={upd} size='15' id='vescend'   value={this.state.vescend}   placeholder='m/s' /></td></tr>
                <tr><th colSpan='2' align='center'> Max terminal velocity:<input onChange={upd} size='15' id='vmaxfinal' value={this.state.vmaxfinal} placeholder='m/s'/></th></tr>                    
                <tr><td colSpan='2'><hr/></td></tr>
                <tr><td align='center'><button onClick={this.calc.bind(this)}>Calculate</button></td><td align='center'>
                     <button onClick={this.clear.bind(this)}>Clear</button></td></tr>
                <tr><td align='center'><button onClick={this.showProg.bind(this)} disabled={!this.state.haveCalc}>TrajProj</button></td><td align='center'>
                <button disabled={!this.state.haveCalc} onClick={this.export.bind(this)}>Export to animation</button></td></tr>                  
            </tbody>
        </table>
        <div id='statusdiv' />
    </div>    
    );
    }
    
    
    showProg() {
        let prog = this.args.cost.writeProgram();
        let str = "Program:<br>";
        for (let i=0; i<prog.length; i += 1) {
            str += prog[i] + "<br>";
        }
        this.message(str);
    }
    
    export() {
        let prog = this.args.cost.writeProgram();
        let str = "";
        for (let i=0; i<prog.length; i += 1) {
            str += prog[i]+"\n";
        }
        let anim = this.animFactory.getAnimation("solar system");
        this.animFactory.getAnimation("solar system").frame.trajControl.parseProgram(str, "calculator");               
    }
        
    clear() {
        let p = {...this.state};
        for (let n in p) {
            if (p[n] === true) {
                p[n] = false;
            } else if (p[n] !== false) {
                p[n] = '';
            }
        }
        p.haveCalc = false;
        this.clearStatus();
        this.setState(p);
    }
    calc() {
        let trajParams = this.getParams();
        if (trajParams == null) {
            return;
        }
        this.args    = new TrajArgs(trajParams);
        let final   = null;
        let params  = this.args.initArray();
        if (params.length == 0) {
            // Everything is fixed.
            final = this.args.cost;
        } else {
            let func    = this.args.getCost.bind(this.args);
            let result  = nelderMead(func, params);
            final = this.args.cost;
        }
        let frmt = new TimeFormatter();
        let str = "<table border=1>";
        str += "<tr><th colspan=2 align='center'>Results</th></tr>";
        let total = 0;
        let costs = final.costSeg;
        
        str += "<tr><td> StartTime: "+frmt.doFormat(final.startTime, 3600)+"</td><td>"+
                " Cost: "+costs[0].toFixed(1)+"</td></tr>";
        total += costs[0];
        for (let i=0; i<final.nMid; i += 1) {
            let m = i+1;
            str += "<tr><td> Mid "+m+":"+frmt.doFormat(final.points[m].t, 3600)+"</td><td>"+
                   "Cost: "+costs[m].toFixed(1)+"</td></tr>";
            total += costs[m];
        }
        str += "<tr><td> EndTime: "+frmt.doFormat(final.endTime, 3600)+"</td><td>"+
               "Cost: "+final.costSeg[final.nMid+1].toFixed(1);
        str += "</table>";
        let last = final.nMid+1;
        total += costs[last];
        str += "<br>Total cost: "+total.toFixed(1);
        this.setState({haveCalc: true});
        this.message(str);
    }
    
    // Check and parse the arguments and put them in a structure
    // using standard uunits.
    getParams() {
        let treq = {};
        try {
            treq.startTime = Util.parseTime(this.state.starttime);
            treq.endTime   = NaN;
            let end = this.state.endtime.trim().toLowerCase();

            if (end.startsWith("+") || end.endsWith("y") || end.endsWith("d")) {
                treq.endTime   = treq.startTime + Util.parseDuration(end);
            } else {
                treq.endTime   = Util.parseTime(this.state.endtime);
            }
            if (isNaN(treq.startTime * treq.endTime)) {
                this.error("Time bounds not specified or invalid: '"+ this.state.starttime + "' to '"+this.state.endtime+"'");
                return null;
            }

            treq.fixedStart = this.state.fixstart;
            treq.fixedEnd   = this.state.fixend;
            if (this.state.duration) {
                treq.duration = Util.parseDuration(this.state.duration);
                if (this.numCheck(treq.duration, this.state.duration, "Invalid duration")) {
                    return null;
                }
            }
            if (treq.fixStart && treq.fixEnd && treq.duration) {
                error("Both fixed endpoints and duration specified");
                return null;
            }
            if (this.state.vescstart) {
                treq.vEscStart = Number.parseFloat(this.state.vescstart);
                if (this.numCheck(treq.vEscStart, this.state.vescstart, "Invalid leaving escape velocity")) {
                    return null;
                }
            }
            if (this.state.midpoints) {
                treq.midpoints = Number.parseFloat(this.state.midpoints);
                if (this.numCheck(treq.midpoints, this.state.midpoints, "Invalid midpoint count")) {
                    return null;
                }
                let tfix = Math.floor(treq.midpoints);
                if (tfix != treq.midpoints) {
                    error("Midpoints not integer");
                    return null;
                }
            }
            if (this.state.vescend) {
                treq.vEscEnd   = Number.parseFloat(this.state.vescend);
                if (this.numCheck(treq.vEscEnd, this.state.vescend, "Invalid arrival escape velocity")) {
                    return null;
                }
            }
            if (this.state.vmaxfinal) {
                treq.vMaxFinal = Number.parseFloat(this.state.vmaxfinal);
                if (this.numCheck(treq.vMaxFinal, this.state.vmaxfinal, "Invalid maximum closing velocity")) {
                    return null;
                }
            }

            let anim = this.animFactory.getAnimation("solar system");
            treq.fromName = this.state.frombody;
            treq.toName  = this.state.tobody;
            let fb = anim.frame.finder.getLocalList(treq.fromName, anim.smbData, 'asteroid');
            if (fb == null || fb.length < 1 || fb[0] == null || fb[0].meta.orbit == null) {
                this.error("Unable to find starting orbit");
                return null;
            } else {
                treq.startOrbit = fb[0].meta.orbit;
            }
            let tb = anim.frame.finder.getLocalList(treq.toName,   anim.smbData, 'asteroid');
            if (tb == null || tb.length < 1 || !tb[0].meta || !tb[0].meta.orbit) {
                this.error("Unable to find final orbit");
                return;
            } else {
                treq.endOrbit = tb[0].meta.orbit;            
            }
            this.clearStatus();
        } catch (t) {
            this.error("Error thrown:"+t);
            return null;
        }
        
        return treq;
    }
    
    numCheck(f, orig, msg) {
        if (Number.isNaN(f)) {
            error(msg+": "+orig);
            return true;
        }
        return false;
    }
    
    error(msg) {
        let text = "<strong>Error: </strong>"+msg;
        this.message(text);
    }
    message(text) {
        document.getElementById("statusdiv").innerHTML = text;
    }
    clearStatus() {
        this.message("");
    }
}

export default TrajCalculator;