// Calculate the first order precession of an orbit,
// assuming we have the appropriate data for the primary.
function precession(primary, orbit) {
    // Calculate the rates of precession of the argument of perihelion and the 
    // longitude of the ascending node.
    if (!primary || !primary.J2  || !primary.radius) {
        // Can't get the approximate values.
        return [0,0];
    }
    let sin_i = orbit.rot[4];
    let cos_i = orbit.rot[3]/orbit.rot[0];
    
    let j2 = primary.J2;
    let ell = orbit.a*(1-orbit.e*orbit.e);
    
    // Calculate common factor for the two derivatives.
    let comm = 1.5*j2 * (primary.radius*primary.radius)/(ell*ell);
    
    let d_omega = comm*cos_i;
    let d_nu    = comm*(2-2.5*sin_i*sin_i);
    
    return [d_omega, d_nu];
}

export default precession;