import Updater   from "../components/Updater.js";
import Util      from "../std/Util.js";
import {Vector3} from "three";

// Have the camera follow an object in an orbit.
class Panner extends Updater {
    constructor(anim, targ, movant, startTime, duration, startPos, endPos) {
        super(anim, targ, movant, startTime, duration);
        this.startPos = startPos;
        this.deltaPos = Util.diff(endPos,startPos);
        this.zcount = 0;
    }
    action(time) {
        this.zcount += 1;
        let delta = (time-this.start)/this.duration;
        let pos = Util.vadd(this.startPos, this.deltaPos, delta);

        let v3 = new Vector3(pos[0], pos[1], pos[2]);
        this.vector.copy(v3);
    }
}

export default Panner;