import Util from "../std/Util.js";
// A coasting, non-accelerated, trajectory.
class Coast {
    constructor(x0, v, t0) {
        this.x0  = x0;
        this.v  = v;
        this.t0 = t0;
    };
    position(t) {
        return Util.vadd(this.x0, this.v, t-this.t0);
    }
    stateVector(t) {
        return [this.position(t), [...this.v]];
    }
}
export default Coast;