// Sorted sequence of elements implemented
// in a doubly linked list.
// This sequence maintains a state that includes
// a current time and position within the sequence.
// Users can ask for a 'popper' iterator which returns
// the elements within a range.  Note that this may change as
// elements are processed.
import Util from "../std/Util.js";

class Sequence {
    
    
    constructor() {
        
        // These following two elements bound the sequence but are never returned.
        this.first       = {elem: {command:"START",t: Number.NEGATIVE_INFINITY}, prev: null,       next: null};
        this.last        = {elem: {command:"END",  t: Number.POSITIVE_INFINITY}, prev: this.first, next: null};        
        // Link the endpoints together to initialize the list
        this.first.next  = this.last;
        
        // The following fields are the state of the sequence (as distinguished
        // from its content).  These change as we move up and down through the sequence
        // processing elements.
        
        // The time currently associated with the sequence.
        this.currentTime = -1.e100;
        // A pointer to the beginning of the interval that contains the current time.
        // Note that the interval is open at the lower limit.
        // Number of 'real' elements in the sequence.
        this.size       = 0;
    }
    
    // Insert a command before a current position in the sequence
    insert(next, cmd) {
        let t = cmd.t;
        
        // First check that it fits in this location
        if (next.elem.t <t || next.prev.elem.t > t) {
            throw new Error("Attempt to insert element out of sequence");
        }
        let ptr = {next: next, prev: next.prev, elem: cmd};
        next.prev.next = ptr;
        next.prev      = ptr;  
    }
        
    // Add an element into the sequence.
    add(element) {
        if (element.t == null) {
            Util.log("No time in element"+element.toString());
            return null;  // Ignore nulls.
        }
        
        let curr = this.last;
        
        // Insert.  We make it efficient
        // if the sequence is built in time order, but 
        // don't do anything special ortherwise.
        // We don't expect very long lists.
        while (curr.elem.t > element.t) {
            curr = curr.prev;
        }
        let oldNext  = curr.next;
        curr.next    = {elem: element, next: oldNext, prev: curr};
        oldNext.prev = curr.next;
                
        this.size   += 1;
        return curr.next;  // Return pointer to the element we added.
    }
    
    
    // Delete an element of the sequence.
    del(element) {
        
        
        // Find the element in the sequence and excise it.
        let curr = this.last.prev;
        let treq = element.elem.t;
        while (curr.elem.t >= treq) {
            if (curr.elem === element.elem) {
                curr.prev.next = curr.next;
                curr.next.prev = curr.prev;
                // Successful deletion
                this.size -= 1;
                return true;
            } else {
                curr = curr.prev;
            }
        }
        
        // Not found.
        return false;
    }
    
    // Get the time of the first (real) element.
    // Return null if there are no real elements.
    start() {
        if (this.first.next === this.last) {
            return null;
        } else {
            return this.first.next.elem.t;
        }
    }
    
    // Get the time of the last (real) element.
    // Return null if there are no real elements.
    finish() {
        if (this.last.prev === this.first) {
            return null;
        } else {
            return this.last.prev.elem.t;
        }
    }
    
    toString(seconds) {
        if (seconds == null) {
            seconds = false;
        }
    
        let res = "";
        let curr = this.first;
        while (curr.next != this.last) {
            curr = curr.next;
            let row = curr.elem.toString(seconds);
            res += row+"\n";           
        }        
        return res;
    }
    
  
    // Find the first event to be processed in the given
    // interval. 
    //   start,end:  interval inclusive of end
    //   fwd: Are we processing in the forward time direction.
    firstEvent(start, end, fwd) {
        let next = null;
        let p = this.first.next;
        while (true) {
            let t = p.elem.t;
            if (t <= start) {
                // Haven't gotten to interval yet.
                p = p.next;
                continue;   
            } else if (t > end) {
                // Done with interval so I can return whatever I found last, if anything.
                // We will only have found something if we're going backwards, since
                // we'd have returned right away if we were going forwards.
                return next;
            } else {
                next = p;
                p = p.next;
                if (fwd == true) {
                    return next;  // Return the first element in a forward interval
                }
            }
        }
    }
    
    // Find the next event to be processed in the given interval
    // given some previous event.
    //     start,end: The interval to be processed including end, but excluding start.
    //     fwd: Are we processing events in the forward intervale
    //     p: the previous event processed in the interval.
    nextEvent(start, end, fwd, p) {
        
        let nxt = fwd? p.next: p.prev; 
        
        let t = nxt.elem.t;
        if (t > start && t <= end ) {
            return nxt;
        } else {
            return null;
        }
    }
                
        
    // Find the stage we should be in for the sequence at a given time.
    // We distinguish the following stages:
    //     empty:  no orbit requests (and thus no rocket) in the sequence.
    //             User can specify start location of rocket.
    //     before: before any orbit request in the sequence, so before the rocket
    //             appears.  
    //             There is no rocket yet.  No actions permitted.
    //     during: after an initial orbit request but before at least one orbit, impulse or thrust
    //             request.  This is the period for which we have a defined trajectory for the rocket.
    //             The user cannot interactively pilot in this period.
    //     after:  after an initial orbit, and all other orbit, impulse or thrust requests.
    //             The user can interactively pilot if the simulation is proceeding forward.
    //             Manual piloting and destination specification permitted.
    findStage(t) {
        
        let stage = "empty";
        let curr  = this.first.next;
        
        while (curr != null  && curr.elem.t <= t) {
            if (curr.elem.command == "orbit"  || curr.elem.command == "coast"  || curr.elem.command == "rest") {
                stage = "after";
            }
            curr = curr.next;
        }
        
        // If we found an orbit, then we are "during" if there are some manuevers
        // still to be completed.
    loop2:  
        while (curr != null) {
            switch (curr.elem.command) {
                case "orbit": case "coast": case "rest":                             
                    if (stage == "empty") {
                        stage = "before";
                    } else {
                        stage = "during";
                    }
                    break loop2;

                case "impulse": case "thrust": case "accel": case "jump": 
                    if (stage == "after") {
                        stage = "during";
                        break loop2;
                    } else {
                        throw new Error("Thrust or impulse with no prior orbit in trajectory");
                    }
            }
            curr = curr.next;
        }
        return stage;
    }
}

export default Sequence;