// ChatGPT created component with lots of customization (note ChatGPT didn't know about need for useRef.)

import { useState, useRef } from 'react';
import Util from "../std/Util.js";

const CounterComponent = (props) => {
    const index               = props.index;
    const controller          = props.controller;
    var   count               = controller.state.impulse[index];
    const intervalId          = useRef();
    let   incrementAmount     =  1; // Starting increment amount
    const maxIncrementAmount  = 10; // Maximum increment amount
    const incrementAmountStep =  1; // Step to increase the increment amount
    const intervalDuration    = 75; // Interval duration in milliseconds
    let   cls = "";
    if (props.xclass) {
        cls = props.xclass;
    }
    
    const setCount = (newVal) => {
        let imp = [...controller.state.impulse];
        imp[index] = newVal;
        let mag = Util.mag(imp)>0;
        controller.setState({hasImpulse: mag, impulse:imp});
    };

    // Modify count from button presses (possible sustained).
    const modifyCount = (amount) => {
        let prev = count;
        
        // Treat non-number previous states as 0.
        if (prev == null  || prev === ""  || 
            prev === "-"  || prev === "+" || 
            prev === ".") {
            prev = 0;
        }
        const sum = prev + amount;
        count = sum;
        setCount(sum);
    };

    // Ramp up the rate at which the value changes as the
    // button continues to be pressed
    const updateIncrementAmount = () => {
        if (incrementAmount < maxIncrementAmount) {
            incrementAmount += incrementAmountStep;
        }
    };
    
    // Start modifying the value based upon a button.
    const startModifying = (baseAmount) => {
        stopModifying();
        modifyCount(baseAmount);
        intervalId.current = setInterval(() => {
            modifyCount(baseAmount * incrementAmount);
            updateIncrementAmount();
        }, intervalDuration);
    };
    
    //  Start incrementing.
    const startModifyingP = () => {
        startModifying(+1);
    };
    
    // Start decrementing.
    const startModifyingM = () => {
        startModifying(-1);
    };

    // No more updates from a button.
    const stopModifying = () => {
        if (intervalId.current) {
            clearInterval(intervalId.current);
            intervalId.current = null;
        }
        incrementAmount = 1; // Reset increment amount
    };

    // Handle updates entered directly by the user.
    const handleInputChange = (e) => {
        const trm = e.target.value.trim();
        // A few strings aren't legal numbers but we want to
        // allow the users to start with them...
        if (trm != "" && trm && "-" && trm != "+" && trm != "."
                 && 
            !isNaN(parseFloat(trm) ) ) {
            setCount(trm);
        }
    };
    
    const clear = () => {
        setCount(0);
    }

    
    return (
            <div>
                <button 
                    onMouseDown={startModifyingP}
                    onMouseUp={stopModifying}
                    onMouseLeave={stopModifying}
                    >
                    +
                </button>
                <input
                    size="1"
                    className={cls}
                    onReset={clear}
                    type="text" 
                    value={count} 
                    onChange={handleInputChange}
                    style={{textAlign: "right"}}
                    />
                <button 
                    onMouseDown={startModifyingM}
                    onMouseUp={stopModifying}
                    onMouseLeave={stopModifying}
                    >
                    -
                </button>
            </div>
            );
};

export default CounterComponent;