import Util from "../std/Util.js";

class PSO {
    
    // nPart:        the number of particles in the swarm
    // nVar:         the number of variables
    // nStep:        the maximum number of steps to take.
    // cost:         a function that will evaluate the cost function for a  particle
    //               the goal of PSO is to find the set of variables that minimize the cost.
    // constraints:  checks that a given particle is in the allowed range.
    // initLimits:   an initial set of particles.
    
    // The PSO method treats the parameters of the function we are trying to 
    // minimize as the coordinates of a particle in a n-dimensional space.
    // We create a flock of these particles randomly and then they 'move'
    // according to some simple rules.  So there is a kind of timestep from
    // one iteration of the fit to another. Note however that this is simply
    // a convenient visualization, there is no physical reality to the 'time's
    // as we go from one step to another.
   
    constructor(nVar, cost, constraints, init) {

        this.particles    = init;
        this.nPart        = init.length;
        this.nVar         = nVar;
        this.constraints  = constraints;

        // Best particle right now.
        this.minCostNow   = 1.e100;
        this.bestPartNow  = 0;
        this.stepCount    = 0;
        
        this.fixCount     = 0;
        this.cost         = cost;  // The cost function.
        this.history      = [];
        
        
        // Best particle ever in the simulation.
        this.minCostEver  = 1.e100;
        this.bestPartEver = 0;
        
        for (let i=0; i<this.nPart; i += 1) {
            if (init[i].cost < this.minCostNow) {
                this.minCostNow = init[i].cost;
                this.bestPartNow = i;
                this.minCostEver = this.minCostNow;
                this.bestPartEver = this.bestPartNow;
            }
        }  
        this.fixLevel = 0;
//        In the example code the initial values for the social and cognitive 
//        coefficients was 1.496180 and inertia was as given 0.729844.
//        It's unclear why such precise values were used and it seems
//        likely that the appropriate coefficients are related to the range
//        of the function parameters (i.e., higher velocities with a larger
//        range).  The example had a range of -4 to +4 so it's not surprising
//        that we use smaller coefficients since we try (and for times
//        strickly enforce) that the valid range is no greater than -1 to 1.
//        Lower inertia seems to make convergence more rapid perhaps reflecting
//        the shape of the minimim.
        this.fCog = 0.5; // Cognitive coefficient
        this.fSoc = 0.5; // Social coefficient
        this.w    = 0.4; // Inertia  
        //
        //
        this.damp = 0.5       // Dampening of velocity at collisions with other parameters or limits.
        // I.e., if a parameters reaches its limit, or the value of another parameter with which there
        // is an ordering relationship, then the 'velocity' of the parameter is reversed as if it collided,
        // inelastically with the velocity reduced by the given factor.
        
        
    }    
    
    // Return the best fit ever found till now.
    getBestEver() {
        return [this.particles[this.bestPartEver].bestX, this.particles[this.bestPartEver].bestCost];
    }
    
    // Progress 1 step.
    step() {
        this.updateVelocity();
        this.updatePosition();
        this.evaluate();
        this.stepCount += 1;
    }
    
    // Evaluate the current positions of the swarm and update
    // the best positions for each particle, the best current particle, and the best position ever.
    evaluate() {
        let stepMin  = 1.e100;
        let indexMin = 0;
        let costSum = 0;
        let costs = [];
        
        for (let i=0; i<this.nPart; i += 1) {
            let part = this.particles[i];
            part.cost = this.cost(part.x);
            // Is this the best particle in the simulation so far this step?
            if (part.cost < stepMin) {
                this.bestPartNow = i;
                this.minCostNow  = part.cost;
                stepMin          = part.cost;
            }
            costs[i] = part.cost;
            costSum += part.cost;
            
            // Is the the best position this particle has ever had?
            if (part.cost < part.bestCost) {
                part.bestCost    = part.cost;
                part.bestX  = [...part.x];
                
                // Since it's the best ever for this particle, see if it's also the best ever
                // for the simulation as a whole.
                if (part.cost < this.minCostEver) {
                    this.minCostEver  = part.cost;
                    this.bestPartEver = i;
                }
            }            
        }
        this.history[this.stepCount-1] = costs; 
        
    }
    
    // Update the positions of the particle.
    // The nominal update just uses the current velocity.  However
    // we need to check that we haven't gone outside the allowed range.
    updatePosition() {
        for (let i=0; i<this.nPart;  i += 1) {
            const part = this.particles[i];
            let t = 0;
            
            while (t < 1-1.e-12) {
                let left = 1 - t;
                // Find the next event.
                let [delta, i, j] = this.findNextEvent(part, left);
                // Advance the variables to the next event.
                // At this point the velocities of the i'th and j'th variables will be reversed.
                this.advance(part, delta, i, j);
                t += delta;
            }
            if (part.x[0] > part.x[1]) {
                console.log("Looking at a problem?", i, part);
            }
        }
    }
    
    // Advance the particles the requested interval.
    // If this interval ends with a constraint limit met, reverse
    // the velocity of the parameters involved in the constraint
    // violation (just 1 if a limit violation, or 2 if two paraemeters cross).
    // So the parameters 'bounce' inelastically and lose half their velocity.
    advance(part, dt, i, j) {
        
        for (let i=0; i<part.x.length; i += 1) {
            part.x[i] += dt*part.v[i];
        }
       
        if (i >= 0) {
            part.v[i] = -this.damp*part.v[i];
        }
        if (j >= 0) {
            part.v[j] = -this.damp*part.v[j];
        }
    }
    
    // See if any constraints would be violated during the
    // movement of the parameters during the nominal remaining
    // 'time' for the step.  If so return the time and parameters
    // involved of the next violation.
    
    findNextEvent(part, t) {
        let x = part.x;
        let v = part.v;
        // Find the earliest event that will occur in the interval between
        // 0 and t.
        
        
        let i = -1;
        let j = -1;
        let earliest = t;
        
        for (let p=0; p < this.constraints.smaller.length; p += 1) {
            let [a,b] = this.constraints.smaller[p]; 
            let dx = x[b] - x[a];  // Dx must be >= 0 since x[b] > x[a] to start.
            let dv = v[b] - v[a];
            if (dx < -dv*earliest) {
                i = a;
                j = b;
                earliest = -dx/dv;
            }
        }
        
        for (let p=0; p < this.constraints.limits.length; p += 1) {
            let [a,min, max] = this.constraints.limits[p];
            let dv = v[a];
            let dx1 = x[a] - min;
            let dx2 = max  - x[a];
            if (dv > 0) {
                if (dx2 < dv*earliest) {
                    i =  a;
                    j = -1;
                    earliest = dx2/dv;
                }
            } else if (dv < 0) {
                if (dx1 < -dv*earliest) {
                    i = a;
                    j = -1;
                    earliest = -dx1/dv;
                }
            }                        
        }
        // Return the time we advance to and the indices of the parameters
        // whose velocities should be reversed (-1 for null)
        return [earliest, i, j];
        
    }
    
    // Update the velocities of the particle.
    // At each step there are three components to the velocity:
    //    - A fraction w of the previous steps velocity is retained.
    //    - A component in the direction to the best ever position for this partcle (fCog)
    //    - A component in the direction to the current best particle in the swarm (fSoc)
    updateVelocity() {
               
        // Create a pair of random vectors.  These vectors add randomness to
        // the search so that we don't lock on too quickly to the first best points.
        let [r1,r2] = [[],[]];
        let std;
        for (let j=0; j<this.nVar; j += 1) {
            r1[j] = Math.random();
            r2[j] = Math.random();
        }
        // Only bestXNow is used in the velocity computation, but
        // it should be possible to use bestXEver too.
        let bestXNow  = [...this.particles[this.bestPartNow].x];
        let bestXEver = [...this.particles[this.bestPartEver].bestX];
        
        let xavg      = 0;
        let variance  = 0;
        for (let i=0; i<this.nPart; i += 1) {

            const p = this.particles[i];
            let xold   = p.x[0];
            let vold   = p.v[0];
            xavg      += xold;
            variance  += xold*xold;
            
            // v = w*v + fCog*r1*(bestX - x) + fSoc*r2*(bestXEver - x)
            for (let j=0; j<this.nVar; j += 1) {
                let v1 = this.fCog*r1[j]*(p.bestX[j]-p.x[j]);
                let v2 = this.fSoc*r2[j]*(bestXNow[j]-p.x[j]);
                let vi = this.w*p.v[j];
                p.v[j] = vi + v1 + v2; 
            }
        }        
        xavg = xavg/this.nPart;
        variance = variance/this.nPart - xavg*xavg;
        
    } 
}

export default PSO;
