import Util        from "../std/Util.js";
import Constants   from "../std/Constants.js";
import QOrb        from "../orbits/QOrb.js";
import SolarSystem from "../animations/SolarSystem.js";

// This describes an orbit which is composed of two motions,
// the orbit of the primary and the orbit or rotation of the secondary.
// This can be used to describe both a moon moving around a planet, 
//    -- sec will be a QOrb object with the orbit of the moon around the planet
// and a fixed position on the surface of a rotating body.
//    -- sec will be a Rotation object with the radius, period, and rotation pole
//    plus an optional position on the surface.
class Epicycle {
    constructor(primary, secondary, primaryName) {
        this.prime = primary;
        this.sec   = secondary;
        this.primaryName = primaryName;
        
        // Are we on the surface of the primary?
        if (this.sec.isRotation) {
            this.onGround = primaryName;
        }
    }
    
    updSecondary(sec) {
        this.sec = sec;
        if (sec.isRotation) {
            this.onGround = this.primaryName;
        } else {
            this.onGround = null;        
        }
    }
    
    position(time) {
        
        let p = this.sec.position(time);
        if (this.sec.scale && (this.sec.scale !== 1  && this.prime.scale != this.sec.scale)) {
            p = Util.times(1/this.sec.scale, p);
        }
        let q = this.prime.position(time);
        if (this.prime.scale && (this.sec.scale !== 1  && this.prime.scale != this.sec.scale)) {
            q = Util.times(1/this.prime.scale, q);
        }
        return Util.vadd(q,p);
    }
    
    stateVector(time) {
        const pstate = this.prime.stateVector(time);
        const sstate = this.sec.stateVector(time);
        return [
            Util.vadd(pstate[0], sstate[0]),
            Util.vadd(pstate[1], sstate[1])
        ];
    }
    
    // Using the current position and velocity unravel the epicycle.
    // Unravel only a single level if a multilevel orbit.
    // E.g., given an orbit of a satellite revolving around the Moon,
    // revolving around the Earth, revolving around the Sun, return the
    // satellite in an epicyclic orbit around the Earth (losing the
    // epicule around the Moon).  May return either a simple orbit, or an
    // epicycle.
    unravelOrbit(t) {
        let [r,v] = this.stateVector(t);        
        let GM  = Constants.GMSun;
        let primaryName = this.prime.primaryName;
        if (primaryName) {
            // Multilevel orbit.
            let [r2,v2] = this.prime.prime.stateVector(t);
            r = Util.diff(r, r2);
            v = Util.diff(v, v2);
            let GM = Util.Constants.G * SolarSystem.getTrackedObject(primaryName).mass;
            
        }
        let str = {r: r, v: v, t: t, GM: GM};
        let orb = QOrb.stateOrbit(str);
        if (this.prime.primaryName) {
            return new Epicycle(this.prime.prime, orb, this.prime.primaryName);
        } else {
            return QOrb.stateOrbit(str);
        }
    }
    
    // Truncate a sequence of epicyclic motions so only motions smaller than the
    // requested frame are included.
    truncate(frame) {
        
        if (frame == "Sun") {
            // Just return the full orbit.
            return this;
        } else if (frame == this.primaryName) {
            return this.sec;            
        } else {  // Intermediate frame...
            if (!this.prime.primaryName) {
                throw new Error("Attempt to truncate epicycle to non-contained frame:", frame);
            }
           
            let prime = this.prime.truncate(frame);
            return new Epicycle(prime, this.sec, this.primaryName);
        }
    }
    
    // Ravel an orbit such that instead of revolving around its current primary,
    // it revolves around a body orbiting the current primary.
    // E.g., if we have a spacecraft orbiting the Sun, get the difference between
    // its current position/velocity and that of Mars, and treat it as
    // an epicyclic orbit around Mars.  The original orbit may or may not
    // be an epicycle, so this is a static method in the class unlike unravelOrbit.
    static ravelOrbit(orbit, t, primary) {
        let state = orbit.stateVector(t);
        let primeData = SolarSystem.getTrackedObject(primary);
          
        let primeState = primeData.orbit.stateVector(t);
        let GM = Constants.G * primeData.mass;
        let dx = Util.diff(state[0], primeState[0]);
        let dv = Util.diff(state[1], primeState[1]);
        let orb = QOrb.stateOrbit({r: dx, v: dv, t: t, GM: GM});
        return new Epicycle(primeData.orbit, orb, primary);
    }
    
    // Given an orbit directly around the same, convert this
    // to an orbit in the same frame as the epicycle.
    from
}

export default Epicycle;

