import {LineBasicMaterial, BufferGeometry,Line, Vector3} from "three";

import Util from "../std/Util.js";

// This returns an orbit with the distances scaled to AU by default.
class OrbitPlot  {
    constructor (name, orbit, color, t) {
        const orbitR = orbit.orbitXYZ(360, t);
        const points = [];
        for (var pi=0; pi<orbitR.length; pi += 1) {
            const r = orbitR[pi];
            points.push(new Vector3(r[0], r[1], r[2]));
        }
   
        this.name     = name;
        this.material = new LineBasicMaterial( { color: color } );
        this.geometry = new BufferGeometry().setFromPoints( points );
        this.line     = new Line(this.geometry, this.material );
    }
    comp() {
        let here = this;
        let xrender = function(t) {
            here.render(t);
        }
        return {component: this.line, name:this.name+"Orbit", render: xrender, baseObj: this};
    }
    
    render(t) {
        // Do nothing by default.
    }
}

export default OrbitPlot;