import CalcAction from "./CalcAction.js";
import Command    from "../Command.js";
import Constants  from "../../std/Constants.js"; 
import Util       from "../../std/Util.js";
import CalcAccel    from "../../traj/CalcAccel.js";
import SolarSystem from "../../animations/SolarSystem.js";

import Equinoctial from "../../orbits/Equinoctial.js";
import Trans       from "../../traj/Trans.js";

// This class computes acceleration trajectories to specific bodies or orbits.
// An acceleration trajectory does not include gravitational effects and thus
// is a reasonable approximation only when the acceleration is significantly larger
// than the gravitational acceleration of the central body.  E.g., if we are considering
// an acceleration orbit from Earth to Mars, we are ignoring the acceleration of
// the Sun which is about 0.006 m/s^2 or about 0.0006 g.  If we are contemplating
// a 1 g drive, then the computed trajectory is not unreasonable.  However this is
// entirely inappropriate for the very low continuous acceleration drives currently 
// deployed.  
//
// The user may specify that they wish the orbit to take a specified interval,
// or they may specify the acceleration that the orbit is to take.  In the later case
// we estimate the time the trajectry will take and then refine the oribinal estimate.
// Generally we know that the required thrust will go to infinity as the interval
// becomes small, and to 0 as the time required gets very large, so we expect that
// there will always be at least one time at which the desired thrust is used.
// However we have not proven that the magnitude of the thrust is a continuous function
// of the interval...
// The computed orbit is broken into two sections essentially an acceleration phase
// and a decleration phase.  The acceleration is constant within each phase.  It is unlikely
// that this is the optimal trajectory satisfying the constraint that the magnitude
// of the accleration is constant, but for the large accelerations contemplated here 
// it may not be bad.
// 
// Currently relativistic effects are ignored.

class accelto extends CalcAction {
    constructor(ptr, anim, traj) {
        super(ptr, anim, traj);
        this.withgrav = false;
    }
    
    // Calculate the requested accelerations
    computeAction(curr, to, gm) {
        const keys = this.args.keyvals;
        if (keys.withgrav) {
            this.withgrav = true;
        }
        if (keys.dt) {            
            return this.computeWithSpecifiedDelta(keys, curr, to, gm);
        } else if (keys.thrust) {
            return this.computeWithSpecifiedThrust(keys, curr, to, gm);
        }
        throw new Error("Must specify either DT or THRUST in accelto");
    }
    computeWithSpecifiedDelta(keys, curr, to, gm) {
        if (keys.dt < 0) {
            throw new Error("Missing or illegal interval for acceleration calculation");
        }
        let dt = parseFloat(keys.dt);
        return this.computeWithKnownDelta(dt, curr, to, gm);
    }
    
    computeWithSpecifiedThrust(keys, curr, to, gm) {
        let thrust = keys.thrust;
        if (keys.thrust < 0) {
            thrust = Math.abs(thrust);
        }
        
        if (keys.thrust == 0) {
            throw new Error("Zero thrust acceleration requested");
        }
        
        let acc = new CalcAccel(curr, to);
        let t1  = acc.getThrustTime(this.time, thrust);
        let delta = t1 - this.time;
        let res = this.computeWithKnownDelta(delta, curr, to, gm);
        console.log("The results are:", res);
        console.log("Thrust equivalent:", this.thrustEquiv(res));
       
        let fromElems = Equinoctial.getElems(curr);
        let toElems   = Equinoctial.getElems(to);
        console.log("FromElems:", fromElems);
        console.log("ToElems:", toElems);
        console.log("CurrPos:", curr.position(this.time));
        let regen = Equinoctial.getOrbit(fromElems);
        console.log("Regen is:", regen);
        regen.scale = 1/Constants.AU;
        console.log("RegenPos:", regen.position(this.time));
        let chk0 = Trans.getDeltas(curr, to, this.time, t1);
        let dt = t1-this.time;
        console.log("Impulses are:", chk0);
        console.log("Thrust equiv:", this.thrustEquiv(chk0, t1-this.time));
        let i=0;
        while(true) {
            i += 1;
            let delta = Math.pow(2,-i);
            let interp = Equinoctial.interp(fromElems, toElems, delta);
            console.log("Interp:", interp);
            let toN = Equinoctial.getOrbit(interp);
            let chkN = Trans.getDeltas(curr, toN, this.time, this.time + dt*delta);
            console.log("Checking for dtN",i,this.thrustEquiv(chkN, dt*delta));
            if (i > 20) {
                break;
            }
        } 
        
                
        return res;
    }
    thrustEquiv(res, dt) {
        let m1 = Util.mag(res[0]);
        let m2 = Util.mag(res[1]);
        return (m1+m2)/dt;
    }
    
    computeWithKnownDelta(dt, curr, to, gm) {
        let t0 = this.anim.time;
        let t1 = t0 + dt;
        let acc  = new CalcAccel(curr, to);
        let soln = acc.getEqMag(t0, t1);
        if (!soln) {
            throw new Error("Unable to calculate accelerations requested");
        }
        let [p0, v0] = curr.stateVector(t0);
        let [p1, v1] = to.stateVector(t1);    
        return {t0: t0, t1: t1, data: soln};
    }
    
    getThrust(t0, t1) {
        let res = this.calc.getEqMag(t0, t1);
        return res.mag;
    }
    
    // Add the acceleration commands plus an orbit command to terminate the accelerations.
    // ** Question: should we go back to a coast if that's where we start?  Or 
    //    theoretically we could have plugged this while we are in any of the
    //    basic motions...
    addCommands(info) {
        let dt = info.t1-info.t0;
        let ts  = [info.t0, info.t0+info.data.alpha*dt];
        let soln = info.data;
        let dv = dt*soln.mag;
        Util.log("Total DV for accelerations is: "+dv.toFixed(2)+" at "+(soln.mag/9.8).toFixed(6)+" g");
        for (let i=0; i<soln.accels.length; i += 1) {
             let acc = soln.accels[i];
             let params = acc.join(" ");
             if (this.withgrav) {
                 // Propogate the end time for the acceleration so
                 // that we can do some calculations...
                 let tend = info.t1;
                 if (i<soln.accels.length-1) {
                     tend = ts[i+1];
                 }
                 params += " withgrav=true tend="+tend;
             }
             let acccmd  = new Command(ts[i], "accel", params);
             acccmd.setGenerated(this);
             this.traj.sequence.add(acccmd);
        }
        let orbcmd = new Command(info.t1, "orbit", "");
        orbcmd.setGenerated(this);
        this.traj.sequence.add(orbcmd);
    }
}

export default accelto;
