import Action from "./Action.js";
import Util   from "../../std/Util.js";

import Rotation from "../../orbits/Rotation.js";
import Epicycle from "../../orbits/Epicycle.js";



// This is the parent class for all basic trajectory actions.
class MotionAction extends Action {
    
    // One of these must be the first MotionAction found.
    static initialCommands = ["rest", "orbit", "coast"];
    
    // These commands persist until another of this set is found.
    // (impulses or jumps can be interspersed inside)
    static persistCommands = [...MotionAction.initialCommands, "thrust", "accel"];
    
    // These are all of the motion commands, we add delta's to the velocity and position.
    // Note that impulse and jump do not extend motionAction since they
    // are executed instantaeously.
    static motionCommands = [...MotionAction.persistCommands, "impulse", "jump"];
    
    // Which command assume we have gravity?
    static gravityCommands = {coast: false, accel: false, orbit: true, thrust: true, rest: true};
    
    constructor(ptr, anim, traj) {  
        super(ptr,anim,traj);
    }
   
    
    // Run the command
    execute(forced, forceTime) {
    
        let delta   = this.anim.delta;
        let command = this.ptr.elem;
        let args    = this.args.posvals;
        this.forced = forced;
        this.forceTime  = forceTime;
       
         
        this.check(delta, command, args);
        
        // If going forward, or if the force flag is set we run this command.
        if (delta > 0  || this.forced) {
            this.doAction(delta, command, args);
        } else {
            // We're going backward in time and have reached the time this command
            // would be executed going forward.  So instead we look for the previous
            // request and run it.  The routine executePrev will set the forcing flag. 
            this.executePrev(this.ptr, MotionAction.persistCommands);
        }
    }
    

    
    // Make sure that this command can happen here.   I.e., we don't have
    // multiple initializations or changes of trajectory before we've initialized it.
    check(delta, command, args) {
        
        let prevInit = this.findPrev(this.ptr, MotionAction.initialCommands);
        // Check if this is an trajectory initialization -- there can only be one.
        if (MotionAction.initialCommands.includes(command.command) && args.length > 0) {
            if (this.startsInteger && this.startsInteger(args)) {   // If this is an orbit reframing command, then just execute it.
                this.forced = true;
            } else  if (prevInit != null) {
                Util.log("Multiple trajectory initialization commands found");
                throw new Error("Multiple entry starts");
            }
            // Going back in time past the original orbit command.
            // We just stay in orbit/coast and don't change anything.
            if (delta < 0 && command.forward) {
                return;
            }
        } else {
            // There needs to be an initialization command sometime before this request
            if (prevInit == null) {
                Util.log("Motion command without trajectory initialization");
                throw new Error("Command "+command.command+" found before initialization");
            }            
        }
    }
    
    

}

export default MotionAction;
