import Util from      "../std/Util.js";
import Constants from "../std/Constants.js";
import {Matrix4, Euler} from "three";

class VThrust {
    
    constructor(mag, camera, x, y) {
        this.mag = mag;
        //  If we are decelerating, stop thrust when the velocity gets less than this.
        this.minV = 1;
        
        if (camera == null) {
            this.cam    = null;
            this.velvec = null;
        } else {
            let cp      = camera.position;
            this.cam    = Util.times(Constants.AU, [cp.x, cp.y, cp.z]);
            this.velvec = Util.vec3([0,0,mag]);
            let rot     = new Euler(x-Math.PI/2, y, 0, "XYZ");
            this.velvec.applyEuler(rot);
            this.count  = 0;
        }
        this.traced = false;
        this.lastTime = null;
        this.lastState = null;
    }
    
    magnitide() {
        return Math.abs(this.mag);
    }
    
    a(x,v,t) {
        let acc;
        let vmag = Util.mag(v);
        
        // If the velocity gets too small we can't determine
        // the appropriate direction for the thrust.
        // We throw an error which includes time we ran into
        // this problem.  Higher level code will convert
        // the trajectory to an orbit or coast.
        if (vmag < this.minV  && this.mag < 0) {
            Util.log("Exiting aligned thrust due to indeterminate velocity");
            let err = new Error("");
            err.meta = {};
            err.meta.cause     = "zerov";
            err.meta.t         = this.lastTime;
            err.meta.lastState = this.lastState;
            throw err;
        }
        if (this.cam == null) {
            let unit = Util.unit(v);
            acc = Util.times(this.mag, unit);
        } else { 
            // Unit vectors of the frame in which the instantaneous thrust is defined.
            let units = Util.viewedCoordFrame(this.cam, x, v);
            let mat = new Matrix4();
            mat.makeBasis(Util.vec3(units[0]),Util.vec3(units[1]),Util.vec3(units[2]) );
            let vc = this.velvec.clone();
            vc.applyMatrix4(mat);
            acc = [vc.x, vc.y, vc.z];
            this.lastAcc = [...acc];
        }
        this.count += 1;
        this.lastTime = t;
        this.lastState = [x,v];
        return acc;
    }
}

export default VThrust;

