import Util from "../std/Util";
import Constants from "../std/Constants.js";

class CoordTrans {
    // Construct a transformation  between coordinate systems
    // using coordinates of the poles. The terms alphaG, deltaG
    // and lonE are suggestive of  the right ascension and declinaton
    // of the Galactic pole, and the Galactic longitude of the Equatorial
    // pole, but any coordinate systems may be used though the transformations
    // transformations among Galactic, Ecliptic and Equatorial coordinates
    // are made available using strings like 
    //        eceq   to transform from ecliptic to equatorial coordinates or
    //        galeq  for galatic to equatorial.
    // 
    //    alphaG = longitude of the pole of 
    //         the destination system in the original system,
    //    deltaG = latitude of the pole of the destination
    //         system in the original system (and also of the original
    //         system pole in the destination system)
    //    lonE =  the longitude of the pole
    //         of the original system in the destination system.
    //         
    // Note that the inverse transformation simply inverts the order (but does
    // not negate the values) of these angles.
    
    constructor(ang) {
        this.sin_dg = Math.sin(ang[1]);
        this.cos_dg = Math.cos(ang[1]); 
        this.alphaG = ang[0];
        this.deltaG = ang[1];
        this.lonE   = ang[2];
        
        
        // Transform the unit vectors to get the full transformation
        // matrix
        const vx = this.toVector(this.transform(0.,        0.));
        const vy = this.toVector(this.transform(Math.PI/2, 0.));
        const vz = this.toVector(this.transform(0.,        Math.PI/2));
        this.mat = [vx, vy, vz];
    }
    
    
    // Pole locations for standard transformations.    
    static coordDefs = {
        // To describe a transformation from one system to another we
        // use the coordinates of pole of the new system in the old system
        // and vice versa.  [Of course the coordinates of each pole in
        // its own system is just 0,90].  Since there is a fixed distance
        // between the two poles, the latitude of the poles must be the same.
        // [E.g., if there if you are 70 degrees from the pole where the
        // latitude is 90 degrees, then you must be at 20 degrees, whichever
        // way you go...]
        // We use degrees since that's how this is normally documented 
        // The three numbers given are:
        //     The longitude in the old system of the new pole.
        //     The latitude in the old system of the new pole.
        //     The longitude in the new system of the old pole.
        //  E.g., when converting from Equatorial coordinates to Galactic
        //   The Galactic pole in equaltorial coordinates is:
        //      (192.859481, 27.128251), 
        //   while the Equatorial pole in Galactic coordinates is 
        //      (122.931918, 27.128251)
        //    So eqgal uses the values:[192.859481, 27.128251,  122.931918]
        unit:  [0,          90,         180       ],
        // The unit transformation is special, because we can't
        // really say what the longitude of the new pole is:
        // it's at the pole!  Consider
        // a transformation where the new pole is a tiny distance
        // from the old pole and we want just move from one pole to
        // the next with no extra rotation.  In that case, then the longitude
        // of the old pole in the new system is going to be 180 offset
        // from the longitude of the new pole in the old system.   We have two
        // points the pole, and a point very close to it. If we switch the pole from
        // to the second point, then the original pol has a longitude offset
        // from the original by 180.  Any pair of longitudes
        // where the difference is 180 degrees would work.  If we made both
        // longitudes 0, then we'd be rotating the whole sphere by 180 degrees
        // to the the pole longitudes both 0.  So as we make the transformatino
        // infinitesimal we get the result like that above.
        
        eqgal: [192.859481, 27.128251,  122.931918],
        eqec:  [270.,       66.560709,   90.],
        galeq: [122.931918, 27.128251,  192.859481],
        eceq:  [ 90.000000, 66.560709,  270.],
        ecgal: [180.023217, 29.811440,   96.383971],
        galec: [ 96.383971, 29.811440,  180.023217]
    };
    static transformations = {};
    
    // Get a coordinate transformation either by specifying
    // a name or the pole angles.
    static getCoords(name_or_angles) {
        if (Array.isArray(name_or_angles)) {
            // User is specifying angles directly.
            // so names is really angles
            return new CoordTrans(name_or_angles);
        }
        let name = name_or_angles.toLowerCase();
        
        if (!CoordTrans.transformations[name]) {
            if (!CoordTrans.coordDefs[name]) {
                Util.log("Unknown coordinate System:"+name);
            }
            CoordTrans.transformations[name] = new CoordTrans(Util.times(Constants.DTOR, CoordTrans.coordDefs[name]));
        }
        return CoordTrans.transformations[name];
    }
        
    // Coordinates: radians to radians
    transform(a,d) { 
        const cos_d = Math.cos(d);
        const sin_d = Math.sin(d);
        const cos_delta = Math.cos(a-this.alphaG);
        const sin_delta = Math.sin(a-this.alphaG);
        
        const sin_b = sin_d*this.sin_dg + 
                      cos_d*this.cos_dg*cos_delta;
        
              
        const b     = Math.asin(sin_b);  // Range is OK...
        const cos_b = Math.cos(b);
        
        const num   = cos_d*sin_delta;
        const denom = sin_d*this.cos_dg - cos_d*this.sin_dg*cos_delta;
        var l     = this.lonE - Math.atan2(num, denom);
        l %= 2*Math.PI;
        if (l < 0) {
            l += 2*Math.PI;
        }
        return [l,b];
    }
        
    
    // Coordinates: Degrees to degrees
    transformd(a,d) {        
        return Util.times(Constants.RTOD,
           this.transform(a*Constants.DTOR, d*Constants.DTOR)
        );
    }

    // Return the unit vector corresponding to a particular direction.
    toVector(crd) {
        const a = crd[0];
        const d = crd[1];
        const vec =  [
            Math.cos(a)*Math.cos(d), 
            Math.sin(a)*Math.cos(d), 
            Math.sin(d)
        ];
        return vec;
    }
    
    // Vector transformation
    vTransform(v) {
        if (!v.length || v.length != 3) {
            return null;
        }
        let [a,b,c] = this.mat;
        let x = v[0]*a[0]+v[1]*b[0]+v[2]*c[0];
        let y = v[0]*a[1]+v[1]*b[1]+v[2]*c[1];
        let z = v[0]*a[2]+v[1]*b[2]+v[2]*c[2];
        return [x,y,z];        
    }
    
    // Return the inverse transformation
    inverse() {
        return new CoordTrans([this.lonE, this.deltaG, this.alphaG]);
    }
    
    // Inverse vector transformation
    invTransform(v) {
        if (!v.length || v.length != 3) {
            return null;
        }
        let [a,b,c] = this.mat;
        let x = v[0]*a[0]+v[1]*a[1]+v[2]*a[2];
        let y = v[0]*b[0]+v[1]*b[1]+v[2]*b[2];
        let z = v[0]*c[0]+v[1]*c[1]+v[2]*c[2];
        return [x,y,z];
    }
    
    // Given an input frame and coordinates,
    // return the coordinates in Equatorial, Ecliptic and Galactic
    // coordinates.  Also return in the planetary equatorial frame if
    // that is the input.
    static coordsSet(iFrame, ilon, ilat, eqPeqE) {
        // First convert to Equatorial coordinates.
        let eq = null;
        switch (iFrame) {
            case "Ga":
               eq = CoordTrans.getCoords("galeq").transform(ilon, ilat);
               break;
            case "Eq":
                eq = [ilon, ilat];
                break;
                
            case "Ec":
                eq = CoordTrans.getCoords("eceq").transform(ilon, ilat);
                break;
            
            case "PEq": 
                eq = eqPeqE.transform(ilon, ilat); 
                break;
            
            default:
              Util.log("Invalid input coordinates:"+iFrame);
              return null;
        }
        let arr = [ ["Eq", eq]];
        arr.push(["Ec", CoordTrans.getCoords("eqec").transform(eq[0], eq[1])]);
        arr.push(["Ga", CoordTrans.getCoords("eqgal").transform(eq[0], eq[1])]);
        if (iFrame == "PEq") {
            arr.push(["PEq", [ilon,ilat]]);
        }
        return arr;       
    }
    
    // Add transform to this one.  I.e., the current transform is applied first, and then the added transform.
    // (Get the inverse for the other order).  This does not update the initial transform.
    add(upd) {
        // Add the transform to the existing transform.  
        // 
        // Find the pole of the initial system in the final system
        // and vice versa.
        let iPole = [0,0,1];
        let fPole = [0,0,1];
        iPole = this.vTransform(iPole);
        iPole = upd.vTransform(iPole);
        
        fPole = upd.invTransform(fPole);
        fPole = this.invTransform(fPole);
        
        let lonFPole = Math.atan2(fPole[1], fPole[0]);
        let lonIPole = Math.atan2(iPole[1], iPole[0]);
        let theta    = Math.asin(iPole[2]); // Should also equal Math.asin(fPole[2])
        return CoordTrans.getCoords([lonFPole, theta, lonIPole]);
    }
    
    static renderCoords(frame, lon, lat) {
        if (frame != 'Eq') {
            let sp1 = "";
            if (lon < 10) {
                sp1 = "  ";
            } else if (lon < 100) {
                sp1 = " ";
            }
            let sp2 = "";
            if (lat > 0) {
                sp2 += " ";
            }
            if (Math.abs(lat) < 10) {
                sp2 += " ";
            }
            return frame+": "+sp1+lon.toFixed(5)+", "+sp2+lat.toFixed(5);
        } else {
            // Display to seconds
            let ra = lon/15;
            let raFlds  = CoordTrans.sexa(ra,   24);
            let decFlds = CoordTrans.sexa(lat, 360);
            let space = ' ';
            if (lat < 0) {
                space = '';
            }
            return frame+": "+
                    raFlds[0]+"h "+raFlds[1]+"m "+raFlds[2]+"s" +  ", "+
                    decFlds[0]+"d "+decFlds[1]+"' "+decFlds[2]+'"';
        }
    }
    
    // Split an angle into degrees/minutes/seconds strings
    // where the minutes/seconds are suitably rounded and have
    // leading 0's appended where needed.
    // 
    //    val   -- the angle to be formated.
    static sexa(val) {
        let sign = "";
        if (val < 0) {
            sign = "-";
            val = Math.abs(val);
        }
        let unit = Math.floor(val);
        let frac = val - Math.floor(unit);
        let sec  = 3600 * frac;
        sec     += 0.5;
        sec      = Math.floor(sec);
        let min  = Math.floor(sec/60);
        sec      = sec % 60;
        if (Math.abs(unit) < 10) {
            unit = sign+'0'+unit;
        } else {
            unit = sign + unit;
        }
        if (min < 10) {
            min = "0"+min;
        } else {
            min = ""+min;
        }
        if (sec < 10) {
            sec = "0"+sec;
        } else {
            sec = ""+sec;
        }
        return [unit,min,sec];
    }
    
    static posString(coords) {
        let retStr = "";

        for (let i=0; i<coords.length; i += 1) {
            let cval = coords[i];
            let cstr = CoordTrans.renderCoords(cval[0], cval[1][0]*Constants.RTOD, cval[1][1]*Constants.RTOD);
            retStr += "<br/>&nbsp;&nbsp;&nbsp;"+cstr;
        }
        return retStr;
    }

}
export default CoordTrans;
