// This is the parent class of the Actions taken in response to scripted commands.
// Note the distinction between the Command, which is the queued request to do something
// and the Action which carries it out.  
// 
// By convention the commands are assumed to be in all lower case (the parser uses toLowerCase())
// so the associated JavaScript files begin with a lower case letter.
// 
// This module includes a number of utility capabilities that are needed by multiple commands,

import Util       from "../../std/Util.js";
import Constants  from "../../std/Constants.js";
import QOrb       from "../../orbits/QOrb.js";
import FixedOrbit from "../../orbits/FixedOrbit.js";

import Acts from "./Acts.js";

class ScaledOrbit {
    constructor(base, scale) {
        this.base   = base;
        this.factor = 1/scale;
    }
    position(t) {
        return Util.times(this.factor, this.base.position(t));
    }
    stateVector(t) {
        return this.base.stateVector(t);
    }
}

// The long/lat of points where we initiate/terminate trajectories.
let pointsOnSphere = {
    ksc: [-80.6520, 28.5744]
};

class Action {
    
    static definedOrbits= {};
    
    
    // The constructor parses the arguments to the command.
    constructor(ptr, anim, traj) {
        this.ptr  = ptr;
        this.anim = anim;
        this.traj = traj;
        this.time = ptr.elem.t;
        this.argInfo = this.parseArgs();
    }
    
    
    // Parse the arguments.
    parseArgs() {
        let args = this.ptr.elem.forward;
        return this.parseString(args);
    }
    
    // Parse a string returning a structure with all the fields, the 
    // key value pairs (keyvals) and the positional fields (posvals).
    parseString(args) {
        if (args == null) {
            args = "";
        }
        args = args.trim();        
        let fields = args.split(/\s+/);
        let keyvals = {};
        let posvals = [];
        for (let i=0; i<fields.length; i += 1) {
            let str = fields[i];
            let pos = str.indexOf("=");
            if (pos > 0) {
                let key = str.substring(0,pos).trim().toLowerCase();
                let val = str.substring(pos+1).trim();
                keyvals[key.toLowerCase()] = val;
            } else {
                str = str.trim();
                if (str.length > 0) {
                    posvals.push(str);
                }
            }
        }
        return {fields:fields, posvals: posvals, keyvals:keyvals};
    }
    
    exec(forced, time) {
        let forward = this.anim.delta > 0;
        let dir     = this.ptr.elem.direction;
        
        // Only do the direction check at the nominal time of the
        // command execution, do not do it when the execution is
        // forced by a later command running backwards.
        if ( !forced ) {
            if ( (forward && dir == 1) || (!forward && dir == -1) ) {
                Util.log("Command direction Violation:"+time);
                return;  // Don't do anything!
            }
            if (forward) {
                this.ptr.elem.direction = 1;
            } else {
                this.ptr.elem.direction = -1;
            }
        }
        
        
        this.args = this.parseArgs();
        if (this.anim.delta > 0 && (this.args.keyvals.reverseonly != null)) {
            return;
        } else if (this.anim.delta < 0  && this.args.keyvals.forwardonly) {
            return;
        }
        if (this.anim.delta > 0  && !this.ptr.elem.generated) {
            // If we are moving forward, then any commands generated in
            // some previous cycle through this command should be thrown out.
            // Commands should never be generated when moving backwards.
            this.cleanGenerated();
        }
        this.execute(forced, time);
    }
    
    // Placeholder for command execution.
    execute() {
        Util.log("No commmand action specified for command: ",this.ptr.elem.toString());
        console.trace();
    
    
       // Every instantiating subclass of Action will define a method
       //   execute(force)
       // which actually performs the request.  The force argument is
       // true when a request is being forced by another request that is
       // being requested while going backwards in time.  (E.g., if we are going backwards
       // in time and run into a thrust command, this means that we've reached the 
       // beginning of the thrusting period and since we're going earlier still we
       // need to execute the previous orbit command.
    }
    
    // Execute the previous command of a given set -- generally when
    // we are going backwards.
    // 
    // Cmds: which kind of coomands to look for
    // should have the same values for.
    executePrev(ptr, cmds, reqKeys) {
        let prev = this.findPrev(ptr, cmds, reqKeys);
        if (prev == null) {
            return false;
        } else {
            this.runPrev(prev);
            return true;
        }
    }
    
    // Returns true if the required keywords (if any) match.
    // keywords in the given command.
    matchKeys(reqKeys, cmd) {
        if (reqKeys) {
            let actKeys = this.parseString(cmd.forward).keyvals;
            for (let k in reqKeys) {
                let act = actKeys[k];
                let req = reqKeys[k];
                if (act) {
                    act = act.toLowerCase();
                }
                if (req) {
                    req = req.toLowerCase();
                }
                if (req != act) {
                    return false;
                }
            }
        }
        return true;
    }
    
    // Find the most recent previous command of the specified types.
    findPrev(ptr, cmds, reqKeys) {
        let curr = ptr.prev;
        while (true) {
            let cmd = curr.elem.command;
            if (cmd == "START") {
                return null;
            }
            if (cmds.includes(cmd)  && this.matchKeys(reqKeys, curr.elem)) {
                return curr;
            }
            curr = curr.prev;
        }
    }
    
    // Run a previous command with the force flag set.
    runPrev(prev) {
        let Aclass = Acts[prev.elem.command];
        let prevAct = new Aclass(prev, this.anim, this.traj);
        // Do it now, not at the time the other command is executed going forward.
        prevAct.exec(true, this.time);
    }
    
    // Remove all events generated by the current event.
    cleanGenerated() {
        let cmp  = this.ptr.elem;
        if (cmp.generated) {
            return;   // Generated commands cannot generate new commands.
        }
        
        // Find the first element.
        let curr = this.ptr.prev;
        while (curr.elem.command != "START") {
            curr = curr.prev;
        }
        
        // Eliminate entries generated by the current command.
        // Note that the original command does not have a generated flag
        // so we won't delete it.        
        while (curr.elem.command != "END") {
            if (curr.elem.generated  == cmp) {
                this.traj.sequence.del(curr);
            }
            curr = curr.next;
        }        
    }
    
    // Find the position associated with the arguments and do a callback to the
    // given function. This may be a fixed position or moving target.
    handlePosition(time, args, params, callback) {
        // Callback will be called with params.position having the appropriate position.
        // targetPosition will be used if we need to follow an orbit.
        if (params == null) {
            params = {};
        }
        
        let vec = [];
        
        if (args.length == 3) {
            for (let i=0; i<3; i += 1) {
                vec[i] = Number.parseFloat(args[i]);
            }
            params.position = vec;
            callback(params);
            
        } else {
            this.targetPosition(time, args, params, callback);
        }
    }
    
    // Render an error message on the display.
    err(msg) {
        let prefix = this.ptr.elem.command+": ";
        this.anim.setQuickHTML(prefix+msg);
    }
    
    
    // Find the orbit associated with the name given in args (which may be more than a single token)
    getOrbit(time, args, params, callback) {
        console.log("In getOrbitg:", time, args, params);
        
        // Callback will be called  with params.orbit being a value with a position(time)
        // function that gives the position as a function of time. 
        let name = this.args.keyvals.primary;
        if (name == null) {
            name = args.join(' ').trim();
        }
        console.log("Getting named orbit:", name, time, params);
        this.getNamedOrbit(name, time, params, callback);
    }
    
    getNamedOrbit(name, time, params, callback) {
        console.log("name, time, params:", name, time, params);
        console.log("In getNamedOrbit:", name);
        // Check to see if this is a define'd orbit.  If so just
        // call the callback directly and return.
        
        let lcn = name.toLowerCase();
        if (Action.definedOrbits[lcn]) {
            params.orbit = Action.definedOrbits[lcn];
            params.name  = name;
            callback(params);
            return;
        }
        // We cannot extrapolate the rocket position (since there may
        // be additional impulses or thrusts incurred during the extrapolation period)
        // so only allow the rocket to be used if we are looking for a position at
        // the current time.  Center and Follow are fine, but pan is not.
        if (lcn == "rocket"  || lcn == "myrocket") {
            if (time != this.anim.time) {
                this.err("Cannot extrapolate trajectory to requested time");
            } else {
                // Trajectory position is not scaled...
                let here = this;
                params.orbit = new ScaledOrbit(this.traj.rocket.traj, Constants.AU);
                callback(params);
            }
        } else if (lcn == "sol" || lcn == "sun") {
            params.orbit = new FixedOrbit();
            callback(params);
        } else {
            let here = this;
            function handleFind(bodies) {
                if (!bodies || bodies.length == 0) {
                    here.err("Unable to resolve body: "+name);
                } else if (!bodies[0].meta.orbit) {
                    here.err("No orbit known for body:"+name);
                } else {
                    params.orbit = bodies[0].meta.orbit;
                    params.meta  = bodies[0].meta;
                    params.name = name;
                    callback(params);
                }
            }
            this.anim.find(name, handleFind);            
        }        
    }
    
    // Find the position of a target at a given time.  Note that
    // this sets up a new callback surrounding the user callback,
    // so that we first get the orbit,
    // then use that to get the position before invoking the user's callback.
    targetPosition(time, args, params, callback) {
        // Callback is called with params.position having the appropriate position at the given time.
        
        function getTargetPosition(params) {
            params.position = params.orbit.position(time);
            callback(params);
        }
        this.getOrbit(time, args, params, getTargetPosition);
    }
    
    // Install a (presumably generated) command to handle an event when
    // going backwards in time.
    installRevert(cmd) {
        let revert = {elem: cmd};
                
        // Insert into the sequence immediately before the current command.
        this.ptr.prev.next = revert;
        revert.prev        = this.ptr.prev;
        revert.next        = this.ptr;
        this.ptr.prev      = revert;
    }
    
    lonlat() {
        if (!this.args.keyvals.site) {
            return [0,0];
        }
        let pos = this.args.keyvals.site.toLowerCase();
        if (pointsOnSphere[pos]) {
            return pointsOnSphere[pos];
        }
        let flds = pos.split(",");
        if (flds.length != 2) {
            Util.log("Unable to recognize named point:"+pos);
            return null;
        }
        return [Util.toRadians(flds[0]), Util.toRadians(flds[1])];
    }
    

    
    // Run a command which running forward executes the command and
    // saves the orbit just prior to execution.  When the command is run
    // in reverse we simply restore the previous orbit.  
    // This function calls two other methods: actualCmd and restoreOrbit which
    // do the command execution and the orbit restoration (which may be a little
    // more than just a simple update to the trajectory if we are ]un]ravelling.)
    saveAndRestoreOrbits() {

        let delta   = this.anim.delta;        
        let command = this.ptr.elem;
        let xtraj   = this.traj.rocket.traj;
        
        let initOrb = xtraj.traj;
        if (initOrb.primaryName) {
            initOrb = initOrb.sec;
        }
        let initState = xtraj.stateVector(this.time);
          
        
        // Going forward we just add the impulse into the current orbit...
        if (this.anim.delta > 0) {
            
            // Execute the requested command.  This will normally be
            // in the file specific to the command.
            this.actualCommand();
            command.svData = {initOrb: initOrb};
        } else {
            let svData = command.svData;
            
            // If we are going backward it is possible for errors to accumulate in
            // a way which means that we will not properly retrace the
            // forward trajectory as we go backward.  Notably if we are going to
            // have an extended period orbiting some object, then even a tiny error
            // in the period can accumulate to a significant error over enough time.
            // So instead we recreate simply reuse the orbit that was established
            // when we did the forward trajectory, ensuring consistency.
            
            // Recover the prior orbit from saved data.
            
            this.restoreOrbit(xtraj, svData);
            
            let r = initState[0];
            let finalState = xtraj.stateVector(this.time);
            let dr = Util.mag(Util.diff(r, finalState[0]));
            console.log("Reverse impulse using prior orbit with jump:", dr);
            if (dr > 1000) {
                this.anim.setQuickHTML("Gap in backwards impulse:", dr);
            }            
        }        
    }
}

export default Action;

