import Constants from "../std/Constants.js";
import Util      from "../std/Util.js";
import Orbit     from "../orbits/Orbit.js";
import ssData    from "../data/PlanetaryData.js";

class SolarPlanets {
    
    // Allow case insensitve data requests.
    static lcNames;
    
    /** Get the metadata for a planet */
    static getMetadata(name) {
        if (SolarPlanets.lcNames == null) {
            SolarPlanets.lcNames = {};
            for (let p in ssData.Sol.planets) {
                SolarPlanets.lcNames[p.toLowerCase()] = ssData.Sol.planets[p];
            }
        }
        return SolarPlanets.lcNames[name.toLowerCase()];
    }
    
    /** Get the elements for a planet at a specific time. */
    static getElements(name, time) {
        
        // Convert t from seconds to centuries...
        const t = time/Constants.CENTURY;
        const elems = {};
        // Remember to get the planets of Sol.
        const p     = SolarPlanets.getMetadata(name);
        elems.a     = (p.elems.a + t*p.derivs.a)*Constants.AU;
        elems.Eccen =  p.elems.e + t*p.derivs.e;
        // Defer conversion to radians.
        var   ML    =  p.elems.ML + t*p.derivs.ML;
        elems.i     = Util.toRadians(p.elems.i     + t*p.derivs.i);
        var   LonP  = Util.toRadians(p.elems.LonP  + t*p.derivs.LonP);
        elems.Omega = Util.toRadians(p.elems.Omega + t*p.derivs.Omega);

//      The following definition is not exactly consistent with the
//      orbital period based on the semi-major axis.  If we want
//      trajectories to be reproducible from the state vectors, then
//      we need to rectify this inconsistency (even though the value based upon
//      the change in mean longitude may be more accurate and includes the
//      effect of the mass of the planet).        
//        elems.Per   = 360./p.derivs.ML * Constants.CENTURY;
        elems.Per   = 2*Math.PI*elems.a * Math.sqrt(elems.a/Constants.GMSun);
        
        elems.nu    = LonP - elems.Omega;
        
        // In particular the JPL data gives the Earth a small negative inclination.
        // To fix this we set i->-1, Omega -> Omega+PI, nu->nu+PI  since we want
        // to switch the ascending node to the other side.
        if (elems.i < 0) {
            elems.i = -elems.i;
            elems.nu += Math.PI;
            if (elems.nu > 2*Math.PI) {
                elems.nu -= 2*Math.PI;
            }
            elems.Omega += Math.PI;
            if (elems.Omega > 2*Math.PI) {
                elems.Omega -= 2*Math.PI;
            }            
        }
        
        let MA      = Util.toRadians(ML) - LonP;
        if (p.corr != null) {
            let corr =  p.corr[0]*t*t + 
                        // Paper doesn't explicitly indicate that the trig functions
                        // are in degrees, but in other cases in paper they clearly are.
                        p.corr[1]*Math.cos(Util.toRadians(p.corr[3]*t)) +
                        p.corr[2]*Math.sin(Util.toRadians(p.corr[3]*t));
             MA += Util.toRadians(corr);
        }
        MA = MA % (2*Math.PI);
        
        elems.t0    = time - MA/(2*Math.PI) * elems.Per;
        let ringAngle = null;
        let ringColor = null;
        if (p.ring) {
            ringAngle = p.ring.ringAngle;
            ringColor = p.ring.color;
        } 
        return {elements: elems, mass: p.mass, diameter: 2*p.radius/1000, color: p.render.color, rotationPhase: p.rotationPhase, rotationPeriod: p.rotationPeriod, rotAxis: p.rotAxis, ringColor: ringColor, ringAngle: ringAngle};
    }
        
    // Get the orbit for a planet at a given time.
    static getOrbit(pname, time) {
        const planetData = SolarPlanets.getElements(pname, time);
        const elems = planetData.elements;

        const orb = new Orbit(pname);

        for (var key in elems) {
            orb.addParam(key, elems[key]);
        }
        orb.addParam("t", time);
        // Make sure we can get positions.
        const r0 = orb.getParameter("r", true);
        if (r0 == null) {
            return null;
        }
        return orb.quickOrbit();
    }
}

export default SolarPlanets;