import Constants from "../std/Constants.js";
import {Vector3} from  "three";

// Smallest normalized number.
const smallNorm = Math.pow(2, -1022);

class Util {
    
    // Log a message to the console. Normally we use this
    // instead of calling console.log directly for outputs that
    // we wish to remain in operational code, and
    // use console.log for termporary or debugging output.
    static log() {
        var msg = "";
        var div = "";
        for (var i=0; i<arguments.length; i += 1) {
            msg += div + arguments[i];
            div = " ";
        }
        console.log(msg);  
    }
    
    // The determinant of the 3x3 matrix.
    static determinant3(a) {
        const x =  a[0][0]*( (a[1][1]*a[2][2]) - (a[1][2]*a[2][1]) );
        const y = -a[0][1]*( (a[1][0]*a[2][2]) - (a[1][2]*a[2][0]) );
        const z =  a[0][2]*( (a[1][0]*a[2][1]) - (a[1][1]*a[2][0]) );
        return x+y+z;
    }    
    
    // Unit vector in direction of v
    static unit(v) {
        let mag = Util.mag(v);
        if (mag != 0) {
            return Util.times(1/mag, v);
        }
        return v;
    }
    // Return the scalar magnitude of a vector.
    static mag(a) {
        var sum = 0;
        for (var c in a) {
            sum += a[c]*a[c];
        }
        return Math.sqrt(sum);
    }
    
    static magDiff(a,b) {
        return Util.mag(Util.diff(a,b))
    }
    
    // The scalar dot product between to vectors
    static dot(a, b) {
        if (a.length !== b.length) {
            throw new Error("Incompatible vectors in dot product");
        }
        var sum = 0;
        for (var i=0; i<a.length; i += 1) {
            sum += a[i]*b[i];
        }
        return sum;
    }
    
    // Multiple two quantities and return the product
    static times(a, b) {
        // We support 
        //    scalar*vector
        //    vector*scalar
        //    vector*vector
        //    matrix*vector
        //    matrix*matrix
        
        if (!Array.isArray(b)) {
            // Flip vector*scalar around
            if (Array.isArray(a)) {
                return Util.times(b,a);
            }
        }
        
        
        if (!Array.isArray(a)) {
            return b.map(x => a*x);
        }
        
        var a0 = a[0];
        // Check if the first element is a matrix
        if (!Array.isArray(a0)) {
            // Just 1D array.  Assume array*array
            if (a.length != b.length) {
                throw new Error("Incompatible arrays in multiply");                
            }
            let r = [...a];
            for (let i=0; i<a.length; i += 1) {
                r[i] *= b[i];
            }
            return r;
        }
                
        if (!Array.isArray(b[0])) {
            
            // Second element is vector so multiply it by matrix
            return [
                Util.dot(a[0], b),
                Util.dot(a[1], b),
                Util.dot(a[2], b)
            ];
        } else {
            // Second element is matrix, so we do matrix multiply here.
            var z = [];
            for (var i=0; i<3; i += 1) {
                z[i] = Util.times(a, b[i]);
            }
            return z;
        }
    }
    
    // Get a row vector from a matrix (given as a vector of columns)
    static rvec(a, n) {
        var res =  [a[0][n], a[1][n], a[2][n]];
        return res;
    }
     
    // The difference of two vectors a-b
    static diff(a,b) {
        if (a.length != b.length) {
            throw new Error("vectors differ in length");
        }
        const res = [];
        for (let i=0; i<a.length; i += 1) {
            res[i] = a[i] - b[i];
        }
        return res;
    }

    // Add two vectors (possibly scaling the second)
    static vadd(a, b, s) {
        if (a.length !== b.length) {
            throw new Error("Incompatible vectors in add");
        }
        if (s == null) {
            s = 1;
        }
        var res = [...a];
        for (var i=0; i < res.length; i += 1) {
            res[i] += s*b[i];
        }
        return res;
    }
    
    // Average of two vectors
    static vavg(a,b) {
        if (a.length !== b.length) {
            throw new Error("Incompatible vectors in average");
        }
        var res = [];
        for (var i=0; i<a.length; i += 1) {
            res[i] = 0.5*(a[i]+b[i]);
        }
        return res;
    }
    
    // Are two arrays equal.  [A null is equal to another null)
    static arrEq(a,b) {
        if (a == null && b == null) {
            return true;
        }
        if (a == null || b == null || a.length != b.length) {
            return false;
        }
        for (let i=0; i<a.length; i += 1) {
            if (a[i] != b[i]) {
                return false;
            }
        }
        return true;        
    }
    
    // Cross product of two vectors.
    static cross(a, b) {
        
        return [
           a[1]*b[2] - a[2]*b[1],
          -a[0]*b[2] + a[2]*b[0],
           a[0]*b[1] - a[1]*b[0]
        ];
    }

    // Rotation matrix for a rotation of the given angle around the specified axis.
    static rot(angle, axis) {
        
        var a,b,c;
        switch (axis) {
            case "x":
                a=1;
                b=2;
                c=0;
                break;
            case "y":
                a=0;
                b=2;
                c=1;
                break;
            case "z":
                a=0;
                b=1;
                c=2;
                break;
            default: throw new Error("Unknown axis");
        }
        
        var m = [[0,0,0],[0,0,0],[0,0,0]];
        
        m[c][c] = 1;
        m[b][b] =  m[a][a] = Math.cos(angle);
        m[a][b] =  Math.sin(angle);
        m[b][a] = -m[a][b];
        return m;
    }
    
    static toRadians = function(a) {
        return a*Constants.DTOR;
    }
    
    static toDegrees = function(a) {
        return a*Constants.RTOD;
    }

    // Convenience function for printing a matrix
    static printMatrix(a) {
        Util.log("Matrix: ");        
        for (var i=0; i<3; i += 1) {
            Util.log("    "+a[0][i].toFixed(5)+" "+a[1][i].toFixed(5)+" "+a[2][i].toFixed(5));            
        }
    }

    // Given a UTC date return seconds
    // since 2000
    static datetime(str) {
        let flds   = str.split("T");
        let dtflds = flds[0].split("-");
        let tmflds = flds[1].split(":");
        let date = new Date();
        date.setUTCFullYear(dtflds[0]);
        date.setUTCMonth   (dtflds[1]-1); // Stupid!!
        date.setUTCDate    (dtflds[2]);
        
        date.setUTCHours   (tmflds[0]);
        date.setUTCMinutes (tmflds[1]);
        if (tmflds[2]) {
            date.setUTCSeconds(tmflds[2]);
        } else {
            date.setUTCSeconds(0);
        }
        date.setUTCMilliseconds(0);
        return date.getTime()/1000 - Constants.Epoch0;        
    }
    
    // Returns the angle between two vectors.
    // While we can get the cosine of the angle easily
    // from the dot product, the sine is ambiguous, reflecting that we can measure
    // an two angles which sum to 360 degrees. We can say it depends
    // upon the order in which we do the cross-product.  Here
    // the order is defined to be such that the dot
    //     (c X d) dot north 
    // is greater than zero (e.g., that we measure the angle in a prograde 
    // direction where north is a vector pointed to a nominal north).  Here c and d are a and b
    // in the desired order.
    static vecAngle(a,b, north=[0,0,1]) {
        let cross = Util.cross(a,b);
        let cdot  = Util.dot(cross,north);
        
        // Magnitude of cross product is |a| |b| |sin(angle)|
        let cmag = Util.mag(cross);
        
        // Magnitude of dot product is |a| |b| cos(angle)
        let dot  = Util.dot(a,b);
        
        // See if we need to negative value for sine.
        if (cdot < 0) {
            cmag = - cmag;
        }
        
        // Now we just return angle.
        let result = Math.atan2(cmag, dot);
        if (result < 0) {
            result += 2*Math.PI;
        }
        
        return result;
    }
    
    /** Project a vector v onto the plane through the origin with the normal vector n.
     *  N is assumed to be normalized 
     */
    static project(v, n) {
        let dot = Util.dot(v, n);
        return Util.vadd(v, n, -dot);        
    }
    
    static pVec(v, nprec) {
        if (nprec == null  || nprec < 0) {
            nprec = 3;
        }
        // First get the maximum scale.
        let max = 0;
        for (let i=0; i<v.length; i += 1) {
            if (Math.abs(v[i]) > max) {
                max = Math.abs(v[i]);
            }
        }
        let scale = 0;
        if (max != 0) {
            scale = Math.floor(Math.log10(max));
        }
        let fac = Math.pow(10, -scale);
        let str = "[ ";
        let divp = " ";
        let divm = "";
        for (let i=0; i<v.length; i += 1) {
            let div = v[i] >= 0? divp: divm;
            str += div + (v[i]*fac).toFixed(nprec);
            divp = "  ";
            divm = " ";
        }
        // Use exactly three digits for the scale (we can handle -99 to 999
        str += " ] x 10^"+scale;
        if (scale >= 0) {
            if (scale < 10) {
                str += "  ";
            } else {
                str += " ";
            }
        } else {
            if (scale >= -9) {
                str += " ";
            }
        }
        return str;
    }
    static showState(r, v, nprec=3, prefix="state") {
        if (Math.abs(r[0]) > 1.e3) {
            r = Util.times(1/Constants.AU, r);
        }
        Util.log(prefix, "r: " + Util.pVec(r, nprec) + "   v: "+Util.pVec(v, nprec));
    }
    
    // Given the rot array, return the standard orbit angles.
    static rotToAngles(rot) {
        let nu    = rot[5]
        let Omega = Math.atan2(rot[2], rot[0])
        let i     = Math.atan2(rot[4], rot[3]/rot[0]);
        return {i: i, Omega: Omega, nu: nu};
    }
    
    // Given a structure with the rotation angles {i,nu,Omega} get the rot array.
    static anglesToRot(str) {
        const o  = str.Omega;
        const co = Math.cos(o);
        const so = Math.sin(o);
                
        const i  = str.i;
        const ci = Math.cos(i);
        const si = Math.sin(i)
                
        const n  = str.nu;
        return [
                
            // Six element vector with to make efficient position computations.
            co,  -so*ci,  // Coefficients for x 
            so,   co*ci,  // Coefficients for y
            si,           // Coefficients for z
            n
        ];            // Save nu so all rotation information stored in rot.    

    }
 
    // Parse a string as a time in ISO, decimal years, or Julian days.
    // Decimal values less than 100000 are assumed to be in years.  Greater
    // (absolute) values are assumed to be Julian days.
    static parseTime(time) {
        
        let aTime = null;
        if (time.indexOf("-") < 1) {  // Allow negative times but any other hyphen is date.
            // Not ISO date so assume numeric
            let numb  = parseFloat(time)
            let scale  = 1;
            let offset = 0;
            time = time.toLowerCase();
            // Keep the order of the following.
            if (time.endsWith("mjd")) {
                scale  = 86400;
                offset = 51544*scale;
                return numb*scale - offset;
            } else if (time.endsWith("jd")) {
                scale = 86400;
                offset = 2451544.5*scale;
                return numb*scale - offset;
            } else if (time.endsWith("d")) {
                scale = 86400;
                return numb*scale;
            } else if (time.endsWith("s")) {
                return numb;
            }
            
            if (Math.abs(numb) < 100000) {
                aTime = Util.getTimeFromYear(numb);
            } else {
                aTime = (numb - Constants.JD0) * 86400;
            }
        } else {
            // Add in Zulu time zone to untimezoned ISO strings.
            if (time.match(/^\d\d\d\d+-\d+-\d+$/)) {
                // Just the day, e.g., 1950-01-01
                time += "T00:00Z";
            } else if (time.match(/.*:\d+$/)) {
                // Something that ends with a time of day, e.g., 1910-01-01T10:00
                time += "Z";
            }
            let date = Date.parse(time);
            if (date != null) {
                aTime = date/1000 - Constants.Epoch0;
            }            
        }
        return aTime;
    }
    
    static getTimeFromYear(yr) {
        
        let iyr = Math.floor(yr);

        // Get the time at the start of the year.
        let strt = new Date(iyr + "-01-01T00:00Z")/1000 - Constants.Epoch0;
        if (yr == iyr) {  // Whole year?
            return strt;
        }
        // If we want fractional years to match smoothly to calender years we
        // need to compute the length of the actual year to convert the
        // fractional year to a number of seconds. We assume a Gregorian calendar.
        let leap = (iyr%4) == 0;
        // Check century rules where most century years are not leap years.
        if (leap && ((iyr%100 == 0)  && (iyr%400 != 0))) {
            leap = false;                        
        }
        
        let days = leap? 366:365;                    
        let len  = days*86400;
        
        // yr-iyr is guaranteed to be in the range 0-1
        return strt + (yr-iyr)* len;   // Add in the fractional part of the year.
                            
    }
    
    static parseDuration(inp) {
        let dur = null;
        inp = inp.trim();
        inp = inp.toLowerCase();
        let fac = 1;
        if (inp.endsWith("d")) {
            fac = 86400;
            inp = inp.substring(0, inp.length-1);
        } else if (inp.endsWith("y")) {
            fac = Constants.CENTURY/100;
            inp = inp.substring(0, inp.length-1);
        }
        return Number.parseFloat(inp)*fac;
    }
    
    // Parse a double value that may have a unit attached.
    // Often it will be required that the unit immediately
    // follow the numeric value, but this routine allows for spaces there.
    //  e.g., 36.5 km/s, is fine here, but in commands this would
    // cause problems for the tokenizing, so entering 36.5km/s is preferred.
    static parseWUnits(input) {
        const units = {
            // Lengths
            au: Constants.AU, pc: Constants.PC, mpc: 1.e6*Constants.PC,
            // Times
            d: 86400,  y: Constants.CENTURY/100, 
            // Velocities
            "km/s": 1000, c: Constants.c
        };
        input = input.trim().toLowerCase();
        let scale = 1;
        if (input.match(/.*[a-z]$/)) {
            // If a string ends in a letter, then it must have units attached.
            for (let unit in units) {
                if (input.endsWith(unit)) {
                    input = input.substring(0,input.length-unit.length);
                    break;
                }
            }
            // If no unit is found this should ignore the end and will give
            // an initial number unscaled.
            input = input.trim();  // space between number and units.
        }
        return scale*Number.parseFloat(input);
    }

    
    static vec3(arr) {
        return new Vector3(arr[0], arr[1], arr[2]);
    }
    
    // camera: Position of the camera/viewer
    // obj:    Position of the object
    // vel:    Velocity of the object.
    //    Returns unit vectors of standard frame.
    static viewedCoordFrame(camera, obj, objVel) {
        let v = Util.diff(camera, obj);  // Viewing direction (from obj to camera)
        let x = Util.unit(Util.cross(objVel, v));
        let y = Util.unit(objVel);
        let z = Util.cross(x, y);
        return [x,y,z];        
    }
    
    static getDistanceScale(unit) {
        if (unit == null) {
            return null;
        }
        unit = unit.toLowerCase();
        switch (unit) {
            case 'm':  return 1;
            case 'km': return 1000;
            case 'au': return Constants.AU;
            case 'pc': return Constants.PC;
            case 'kpc': return 1000*Constants.PC;
            case 'mpc': return 1000000*Constants.PC;
            default: Util.log("Unknown length unit ("+unit+") returning 1");
                   return 1;
        }
    }
    
    // Fix the range of an angle between -PI to PI
    static fixRange(angle) {
        while (angle > Math.PI) {
            angle -= 2*Math.PI;
        }
        while (angle < -Math.PI) {
            angle += 2*Math.PI;
        }
        return angle;
    }
    
    // Return a string giving the integer value prepended with spaces to extend
    // to length n.
    static prInt(i, n) {
        let s = i+"";
        let d = n - s.length;
        if (d > 0  && d < 30) {
            s = "                              ".substring(0,d) + s;
        }
        return s;
    }
    
    // Get the next representable floating point number going towards -infinity
    static previousNumber(f) {
        
        let rat = 1;
        if (f == 0) {
            return -Number.MIN_VALUE;
        // Handle unnormalized numbers which can have
        // much larger ratios between consecutive values
        // than the usual EPSILON.
        } else if (Math.abs(f) < smallNorm) {
            rat *= smallNorm/Math.abs(f);
        }
        
        // If positive, then decrease the magnitude.
        if (f > 0) {
            return f/(1+rat*Number.EPSILON);
        // If negative, then increase the magnitude.        
        } else {
            return f*(1+rat*Number.EPSILON);
        }
    }

    // Return a random number generator.
    static sfc32(a,b,c,d) {
        return function() {
            a |= 0; b |= 0; c |= 0; d |= 0; // Cast to 32-bit integer
            let t = (a + b | 0) + d | 0;
            d = d + 1 | 0;
            a = b ^ b >>> 9;
            b = c + (c << 3) | 0;
            c = (c << 21 | c >>> 11);
            c = c + t | 0;
            return (t >>> 0) / 4294967296;
        }
    }
    
    static testSFC() {
        return Util.sfc32(123456789, 98765432, 100100100100100, 661155224433978);
    }
}

export default Util;