import GlobalMinimum from "../math/GlobalMinimum.js";
import Util          from "../std/Util.js";
import Constants     from "../std/Constants.js";

class OrbitCompare {
    static lastComp = null;
    static count = 0;
    constructor(destination) {
        this.to = destination;
        OrbitCompare.lastComp = this;
        
    }
    setFrom(from) {
        this.from = from;
        let p1 = this.to.per;
        let p2 = this.from.per;
        this.synodic = p1*p2/Math.abs(p1-p2);
        OrbitCompare.count += 1;            
    }
    
    at(t) {
        let from = this.from.position(t);
        let to   = this.to.position(t);
        let diff = Util.mag(Util.diff(from,to));
        return {from:from, to:to, diff: diff, t: t};
    }
    
    delta(t) {
        return this.to.offsetBetween(this.from, t);
    }
    
    // Find the time and distance of the minimum between these two orbits for
    // a given interval.  Get the minimum within 1 hour.
    minDist(start, stop) {
        if (this.from == null) {
            throw new Error("Attempt to compare with nonexistent orbit");
        }
        if (stop == null) {
            stop = start + this.synodic;
        }
        // The synodic period can get very large if the periods are too close.
        // In such a case we look only tgen years ahead.
        if (this.synodic > Constants.CENTURY/10) {
            stop = start + Constants.CENTURY/10;
        }
        return GlobalMinimum(this.delta.bind(this), start, stop, this.synodic/10, 100);
    }
}

export default OrbitCompare;

