// Download content and call the success callback
// if some content was successfully downloaded.
// Call the failure callback if there is an error,
// or no content is returned.
function GetUrl(url, success, failure) {

    const getter = new XMLHttpRequest();
    getter.onerror = function() {
        failure("Network error");
    }
    getter.onload  = function() {
        if (getter.status == 200 || getter.status == 202) {
            if (getter.responseText.length > 0) {
                success(getter.responseText);
            } else {
                failure("Empty file");
            }
        } else {
            failure("HTTP Error: Response code is:"+getter.status);
        }
    }
    getter.open("GET", url);
    getter.send();    
}

export default GetUrl;