import QOrb from "../../orbits/QOrb.js";
import Action from "./Action.js";
import Util   from "../../std/Util.js";
import Command from "../Command.js";

class jump extends Action {
    
    constructor(ptr, anim, traj) {
        super(ptr, anim, traj);
    }

    execute() {
        
        let delta     = this.anim.delta;
        let command   = this.ptr.elem;
        
        let keys      = this.args.keyvals;
        let flds      = this.args.posvals;
        let generated = this.ptr.elem.generated;
                          
        // Only do input jumps when going forward
        // Only do generated jumps when going backward.
        // Generated jumps will always have 3 parameters.        
        if (flds.length == 1) {
            // Only do named jumps forward.
            if (delta > 0) {
            
                let dest   = flds[0];
            
                // Allow something like   jump target/3     to jump 1/3 of the way to the target
                let factor = 1;
                let df = dest.split("\/");
                if (df.length == 2) {
                    factor = parseFloat(df[1]);
                    dest = df[0];
                }
                let currState = this.traj.rocket.traj.stateVector(this.time);
                let here = this;
            
            
                let doJump = function(params) {
                    let orb = params.orbit;
                    let [pos,vel] = orb.stateVector(here.time);
                    let jmp = Util.diff(pos, currState[0]);
                    jmp = Util.times(factor, jmp);
                    here.traj.rocket.addJump(jmp, here.time);
                    // If we are executing a Jump to some other object,
                    // then we only know the magnitude of the jump when
                    // we execute it (since the object may be moving, and
                    // we have to integrate the trajectory up to the time of
                    // the jump before we know where we are starting from).
                    // So we insert a generated jump before this one that
                    // allows us to jump back.
                    here.insertBackJump(jmp);
                    
                };
                // Need to use callback for names.
                this.getOrbit(this.time, [dest], {} , doJump);
            } else {
            }

        } else if (flds.length == 3) {
            if(generated && delta > 0) {
                // Skip generated jumps when moving forward.
                return;
                
                
            }
            let jmp =  [parseFloat(flds[0]), parseFloat(flds[1]), parseFloat(flds[2])];
            this.traj.rocket.addJump(jmp, this.time);
            // For a fixed jump we don't need a backjump since we just need
            // to invert the direction of the jump.
            
        } else {
            throw Error("Invalid Jump request:"+command.toString());
        }
    }
    
    // We can't generally calculate the jump when going backwards in time
    // until we actually do the jump, since we don't know we're coming from
    // until we get to the jump.  So we add a generated command to do the
    // back jump.
    insertBackJump(jmp) {
        this.cleanGenerated();
        // Note that we don't invert the vector here.  The dt < 0 will be used
        // to put a - sign in front of the back jump
        let cmd = new Command(this.ptr.elem.t, "jump", jmp[0]+" "+jmp[1]+" "+jmp[2]+" reverseonly=true");
        cmd.setGenerated(this);
        this.installRevert(cmd);
    }
}

export default jump;
  