import Sequence  from "../trajanim/Sequence.js";
import Command   from "../trajanim/Command.js"; 
import TravellingRocket from "../elems/TravellingRocket.js";
import OrbitCompare from "../orbits/OrbitCompare.js";
import QOrb      from "../orbits/QOrb.js";
import Util      from "../std/Util.js";
import Constants from "../std/Constants.js";
import {Group}   from "three";

// This class takes care of running a sequence of trajectory commands.
// It adds and removes the actual rocket icon from the animation when appropriate.
class TrajSequencer {
    
    // Create the sequence with an initial list of commands.
    constructor(args) {
        this.sequence = args.sequence;
        this.anim     = args.anim;
        this.invoker  = args.invoker;
        this.control  = args.trajControl;
        this.rocketHolder = new Group();
        if (this.anim.frame.traj) {
            throw new Error("Trajectory already present when adding new trajectory");
        }
        this.anim.frame.traj = this;
        
        let render = function(time) {
//            this.runCmds(time);
            if (this.rocket) {
                this.rocket.comp.render(time);
            }
        }
        let nm = "TrajSequencer";
        this.comp = {name: nm, component: this.rocketHolder, render: render.bind(this)};
        
        // Add this into the animation as a non-rendered element.
        this.anim.addElement(nm, this.comp);
        this.lastTime = this.anim.time;
        
        // Find the current state of the sequence.
        this.lastStage    = this.sequence.findStage(this.anim.time);
        this.lastState    = null;
        this.origin       = null;
        this.dest         = null;
        this.destOrbit    = null;
        this.orbCompare   = null;
        this.testOrbit    = null;
        this.before       = false;
        this.noRocket     = false;
    }    
    
    
    // Not that invoker is the general TrajControl object
    setInvoker(invoker) {
        this.invoker = invoker;
        // Update the animation if we have a new animation (but not when disconnecting from
        // the current animation.
        if (this.rocket && this.invoker) {
            if (this.rocket.anim != invoker.anim) {
                this.rocket.setAnimation(invoker.anim);
            }
        }
    }
    
    setOrigin(name) {
        this.origin = name;
    }
    
    setDest(name, orbit) {
        this.dest      = name;
        this.destOrbit = orbit;
        this.orbCompare = new OrbitCompare(this.destOrbit);
        if (this.testOrbit) {
            this.orbCompare.setFrom(this.testOrbit);            
        } else {
            let state = this.lastState;
            let corb  = QOrb.stateOrbit({t: this.anim.time, r: state[0], v:state[1]});
            corb.scale = 1/Constants.AU;
            this.orbCompare.setFrom(corb);
        }
    }
    
    setNoRocket() {
        this.noRocket = true;
        if (this.invoker) {
            this.invoker.setState({noRocket:true});
        }
    }
    
    setTestOrbit(orbit) {
        this.testOrbit = orbit;
        if (this.orbCompare) {
            this.orbCompare.setFrom(orbit);
        }
    }
    
    minDelta() {
        if (this.orbCompare) {
            let t      = this.anim.time;
            
            let minD   = this.orbCompare.minDist(t);
            // Note that minD = [t,d]
            return minD;
        } else {
            return null;
        }
    }
    
    // Get rid of the sequencer (presumably when the trajectory is deleted).
    cleanup() {
        this.anim.removeElement("TrajSequencer");
    }
    
    // This the RocketController object tied to 'this.rocket' if
    // the user has instantiated a rocket controller.
    setRocketController(rc) {
        this.rocketController = rc;
        if (this.rocket) {
            this.rocket.setRocketController(rc);
        }
    }    
    
    // Run the commands associated with the program.
    // Time is the time up to which we hope to run,
    // but the method will return the time to which we actually run.
    runCmds(initTime) {
        let time = this.runCmds2(initTime);        if (this.rocket && this.rocket.traj) {
            this.lastState = this.rocket.traj.stateVector(time);
        }
        this.lastTime = time;
        return time;
    }
    
    runCmds2(time) { 
        
        // Running commands is made complex because running a command may
        // alter the command sequence, e.g., running
        // a command might delete the command being run, or others, or it might
        // add new commands.  To handle this robustly, we look at
        // a given time interval and start a loop.  Each time
        // we start the loop we look for the first command in the given
        // interval.  If that command has already been executed we look
        // for the next command until we find a command in the interval that
        // has not been executed.  Since this command may affect the command
        // sequence, we start a new iteration where we again look for the first
        // command in the original interval.  However this time the command we
        // have just run (and any others run previously) will be skipped.
        // We iterate until there are no unrun commands in the interval.
        // 
        // There are several special cases:
        //    - A new command may be generated in the current interval but prior
        //    to the command that generated them.  These should be skipped.
        //    - The command may affect the interval being used.  We immediately
        //    terminate the loop at the time this command runs.
        //    - The command may affect the time at which the animation is to run
        //    This is done by updating the value of this.returnTime;
        //    - The execution of the command may affect the stage of the trajectory
        //    requiring changes to the display (e.g., adding a rocket).  So the
        //    sequence stage is queried after every command.
        //    - If an instantaneous orbit is being displayed, then the
        //    command may affect it so that it needs to be updated.
        
        
        if (this.anim.delta > 0) {
            this.before = false;
        } else if (this.anim.time < this.sequence.start() && !this.before) {
            this.anim.setQuickHTML("Not extrapolating trajectory before program start.");
            this.before = true;
        }
        
        let alreadyRun = [];
        this.returnTime = null;
        
  bigloop:  
        // This loop will only execute one command per iteration.
        // If there are multiple commands in the interval, then
        // We'll loop through them one at a time, but we
        // want to check after executing each command since 
        // it may have changed the sequence by adding additional
        // commands.
        while (true) {
            
            // We need to specify the same interval regardless of the
            // direction.  However we'll also give the sequence the direction.
            let fwd  = true;
            let strt = this.lastTime;
            let end  = time;
            if (time < this.lastTime) {
                fwd  = false;
                strt = time;
                end  = this.lastTime;
            }                        
            
            // Get the first command (in the appropriate direction)
            // that is in the sequence.  It may have been run in
            // some previous iteration.
            let cmd  = this.sequence.firstEvent(strt, end, fwd);
            let tcmd = this.lastTime;
        
            // If an executed command affects the animation delta, then
            // we want to change the end of the interval.  So
            // save this to check later.
            let initDelta = this.anim.delta;
                  
            // Interior loop finds the next command to execute.
            // This will skip through any previously executed commands.
            while (cmd != null) {
                if (alreadyRun.includes(cmd)) {
                    cmd = this.sequence.nextEvent(strt, end, fwd, cmd);
                    continue;  // little loop
                }
                
                if (fwd && cmd.elem.t < tcmd) {
                    // New command but it was inserted prior
                    // to a command we already executed, so
                    // we should not execute this one.
                    // It's waiting to run if we go in reverse.
                    // (Commands run in reverse should never add commands)
                    alreadyRun.push(cmd);  // Don't do this check again
                    cmd = this.sequence.nextEvent(strt, end, fwd, cmd);
                    continue;  // little loop
                }
                break;
            }
            
            
            // Run this in a try block in case we need to
            // handle issues that occur in the rocket trajectory integration.
            // If they get handled, the error will indicate that.
            try {

                if (cmd == null) {
                    // Update the trajectory to the time of the command before we execute 
                    // the command.  We need to do this now, since
                    // we may trigger the error we catch below, and usually
                    // this will not be in an interval that actually has a command.
                    if (this.rocket  && this.rocket.traj.traj != null) {
                       this.rocket.comp.render(time);
                    }
                    // No further commands (usually none at all).
                    break bigloop;
                }

                // If we get here, there is an unexecuted command in the
                // interval.  We run this and then restart the big loop.

                // Note the command time so that if new commands are generated
                // in the current interval we can decide if they should
                // be executed (i.e., if we generate a command in the 'past'
                // we don't want it executed.
                tcmd = cmd.elem.t;

                // If there is a command to be executed, update the
                // trajectory to the time of the command.
                if (this.rocket  && this.rocket.traj.traj != null) {
                    this.rocket.comp.render(time);
                }
            } catch (exc)  {
                if (exc.meta && exc.meta.status == "handled") {
                    return exc.meta.t;
                } else {
                    throw exc;
                }
            }
 
            // See if we've changed the state such that the rocket controller needs
            // to change (we haven't run the command yet, but we
            // use the time of that command).
            let newStage;
            if (this.anim.delta > 0) {
                newStage = this.sequence.findStage(tcmd);
            } else {
                newStage = this.sequence.findStage(cmd.prev.elem.t);
            }
            if (newStage != this.lastStage) {

                if ( (newStage == "during" || newStage == "after")) {
                    if (!this.rocket) {
                        this.addRocket();
                    }
                    if (this.rocket.controller) {
                        this.rocket.controller.setState({stage:newStage});
                    }

                } else if ( (newStage == "before" || newStage == "empty") &&
                              this.rocket) {                         
                    this.delRocket(true);
                }

                if (this.invoker) {
                    this.invoker.setState({stage:newStage});
                }

                if (this.rocketController) {
                    this.rocketController.setState({stage:newStage});
                }

                this.lastStage = newStage;
            }

            // Update the animation time to the command time (though
            // we don't do a full render.
            this.anim.time = tcmd;

            // Finally!!! Run the command
            Command.enact(cmd, this.anim, this);

            // Since the command may affect the sequence we
            // only want to execute a single command before getting
            // a refreshing the set of commands in the interval.
            // The alreadyRun array will
            // ensure that we don't execute the same command more than 
            // once.
            alreadyRun.push(cmd);


            // Worry if the command changed the instantaneous orbit.
            if (this.orbCompare) {
                let state = this.rocket.traj.stateVector(time);
                let orb   = QOrb.stateOrbit({t:tcmd, r: state[0], v:state[1]});
                orb.scale = 1/this.anim.sceneScale;
                this.orbCompare.setFrom(orb);
            }

            // Check if we changed the step size.  E.g., we may have
            // moved to an animation with a much smaller step
            // size and we don't want to integrate all the way to
            // the end of the original large step.
            if (initDelta != this.anim.delta) {
                // We don't want to exit because we may
                // have commands simultaneous with the one
                // that changed the interval.
                if (fwd) {
                    time = tcmd;
                } else {
                    // Since we are going backwards, the
                    // earliest time in the interval is not included
                    // in it, so set the end time of the interval to just
                    // before the current command, that means that
                    // if there are any commands simulataneous, they
                    // will still get executed.
                    time = Util.previousNumber(tcmd);
                }
            }                       
            
             
        }  // End of bigLoop.  
        // 
        // Did the command affect the time we should return?
        if (this.returnTime != null) {
            time = this.returnTime;
        }
        
        this.lastTime = time;
        return time;
    }
    
    changeToOrbit(t, state) {
        // First we change to an orbit, then
        // we backfill a generated command to handle the reverse trajectory.
        this.rocket.setToOrbit(t, state);
        let cursor = this.sequence.first;
        let thrust = null;
        
        // Find the previous thrust command that we are terminating
        while (t >= cursor.elem.t) {
            if (cursor.elem.command == "thrust") {
                thrust = cursor;
            }
            cursor = cursor.next;
        }
        
        let cmd = new Command(t, "orbit");
        cmd.setGenerated(thrust);
        // Note that there may be commands between the thrust and our generated
        // orbit command, so we don't use thrust here but cursor.
        let newLink = {next: cursor, prev: cursor.prev, elem:cmd};
        newLink.prev.next = newLink;
        newLink.next.prev = newLink;        
    }
        
    addTrajectory(anim) {
        this.anim = anim;
        this.anim.addElement("TrajSequencer", this.comp);
        if (this.rocket) {
            this.rocket.setAnimation(anim);
            this.addRocket();
        }
    }
    
    delTrajectory(remove) {
        if (this.rocket) {
            this.delRocket(false);  // Just remove it from the current animation, but save it for another.
        }
        this.anim.removeElement("TrajSequencer");
    }
    
    
    addRocket() {
        if (!this.rocket) {
            
            this.rocket = new TravellingRocket({name:"MyRocket", anim: this.anim});
            this.rocket.setTraveller();
        }
//        this.anim.addElement("MyRocket", this.rocket.comp);
        this.rocketHolder.add(this.rocket.comp.component);
    }
    
    delRocket(remove) {
        this.rocketHolder.clear();
        this.orbCompare = null;
        if (this.anim.sceneElements.TrajOrb) {
            this.anim.removeElement("TrajOrb");
        }
        if (remove) {
            this.rocket       = null;
        }
    }
}

export default TrajSequencer;