import MotionAction from "./MotionAction.js";
import Epicycle     from "../../orbits/Epicycle.js";
import SolarSystem  from "../../animations/SolarSystem.js";

import Util from "../../std/Util.js";

class orbit extends MotionAction {
    constructor(ptr, anim, traj) {
        super(ptr, anim, traj);
    }
    
    // Called when delta > 0.  This ravels or unravels the orbit as requested.
    // It saves the finest level orbit of the incoming orbit before
    // updating trajectory.  E.g., if we are orbiting Jupiter before this comment,
    // the orbit around Jupiter only is saved.  [Jupiter's orbit is saved permanently.]
    
    actualCommand() {
        let delta = this.anim.delta;
        let args  = this.args.posvals;
        let n = parseInt(args[0]);
        let orb = this.traj.rocket.traj.traj;
        let na = Math.abs(n);
        if (n < 0) {
            // This is a request to begin orbiting a more distant
            // primary.
            while (na > 0) {
                orb = orb.unravelOrbit(this.anim.time);
                na -= 1;
            }
        } else {
            for (let i=na; i>0; i -= 1) {
                let primary = args[i];
                orb = Epicycle.ravelOrbit(orb, this.anim.time, primary);
            }
        }
        this.traj.rocket.traj.updTraj(orb, this.time);        
    }
    
    
    // This is called when we encounter the command going backwrd
    // in time.  
    // If  the forward request is a ravelling, then we unravel. We look at the
    // first argument to find where we starting ravelling, in case we still want
    // to end up with an epicycle.
    // If the forward request is an unravelling, then look at the last argument to
    // get what our primary was before the unravelling.
    restoreOrbit(xtraj, svData) {
        let args  = this.args.posvals;
        let n = parseInt(args[0]);
        let orbit;
        if (n < 0) {
            // Going backwards we want to ravel, and the initOrb should have
            // the bottom level orbit.
            // Get the orbit of the primary and add this as an epicycle.
            let primary = args[Math.abs(n)];  // The number takes the 0th spot.
            let data = SolarSystem.getTrackedObject(primary);
            orbit = new Epicycle(data.orbit, svData.initOrb, primary);
        } else {
            // Unravelling orbit.
            let primary = args[1];  // Get where we unravelled to.
            let data  = SolarSystem.getTrackedObject(primary);
            primary = data.orbit.primaryName;
            if (primary && primary != "Sun") {
                // We still have an epicyclic orbit.
                let data = SolarSystem.getTrackedObject(primary);
                orbit = data.orbit;
                orbit = new Epicycle(orbit, svData.initOrbit, primary);
            } else {
                orbit = svData.initOrb;
            }            
        }
        xtraj.updTraj(orbit);
    }   
    
    // Set the trajectory to an orbit.
    doAction(delta, command, args) {
        
        if (this.startsInteger(args)) {
            // Handle changes in the primary the orbit is around.
            // The sign of the integer indicates if we are getting more or less epicycles.
            this.saveAndRestoreOrbits();
            
        // Handle initial orbits around some object.
        } else if (args.length > 0  && delta > 0) {
            
            // This is an initial stationing request.  We just specify the
            // orbit and continue.
            let here = this;
            // Callback when we are asking for a named orbit.
            let startOrbit = function(params) {
                let orbit = params.orbit;
                // Should we be on the surface of a body?
                // If so we update the orbit.
                here.traj.rocket.traj.updTraj(orbit, here.time);
            };
            // Match named orbit.
            this.getOrbit(this.time, args, {} , startOrbit);

        } else {
            if (args.length > 0 && this.startsInteger(args)) {   // Must be going backward
                // We need to transform the orbit into one that
                // uses a more local primary.
                let n = Math.abs(parseInt(args[0]));
                
            } else {
            // Start orbit with the current state.
                if (this.forced) {
                    this.traj.rocket.setToOrbit(this.forceTime);
                } else {
                    this.traj.rocket.setToOrbit(this.time);
                }
            }
        }
    }
        
    startsInteger(args) {
       
        return args && args[0] && (args[0].match(/[+-]?\d+/));
    }

}

export default orbit;
