import MotionAction from "./MotionAction.js";
import QOrb         from "../../orbits/QOrb.js";

class coast extends MotionAction {
    constructor(ptr, anim, traj) {
        super(ptr,anim,traj);
    }
    
    // Set the trajectory to coast (unaffected by gravity)
    doAction(delta, command, args) {
        // One of the following three commands can initialize the trajectory:
        // coast object   -- Take the instantaneous position/velocity of the object
        // coast object  vx vy vz  -- Take the instaneous position of the object, but use vx,vy,vz for velocity
        // coast x y z vx vy vz  -- Coast from the specified position relative to the center of the current animation
        // 
        // The following can be used at any point 
        // coast
        
        let time = this.time;
        if (this.forced) {
            time = this.forceTime;
        }
        if (args.length > 0) {
            // This is an initial coast
            // request.  We just specify the
            // coast parameters and continue.
            let here = this;
            
            let xargs = [args[0]];
            
            // Callback when we are asking for a named orbit.
            // or state (t,x,v) orbit.
            let str;
            let startOrbit = function(params) {
                let orb = params.orbit;
                
                // Get the orbit at the time of the current command.
                // and get the position and velocity from that.
                let [x, v] = orb.stateVector(here.time);
                str = {t: here.time, r:x, v:v};
                
                // Override the velocity if requested.
                if (args.length == 4) {
                    for (let i=1; i<args.length; i += 1) {
                        str.v[i-1] = Util.parseWUnits(args[i]);
                    }                    
                }                
                here.traj.rocket.setToCoast(time, str);
            };
            // Need to use callback for names.
            this.getOrbit(this.time, xargs, {} , startOrbit);

        } else {
            
            // Just coast using the current velocity and time.
            let [x,v] = this.traj.rocket.traj.stateVector(time);
            this.traj.rocket.setToCoast(time, {t: time, r:x, v:v});
        }
    }
}

export default coast;
