import CameraAction     from "./CameraAction.js";
import Command    from "../Command.js";
import TransCalc  from "../../traj/TransCalc.js";
import Util       from "../../std/Util.js"; 
import Constants  from "../../std/Constants.js"; 
import Follower     from "../../components/Follower.js";

import {Vector3}  from "three";
//
//  A follow command with an target should be 'followed' by a follow command without one, a la 'orbit'
let xCount = 0;
class follow extends CameraAction {
    constructor(ptr, anim, traj) {
        super(ptr, anim, traj);
    }
    
    execute(forced) {
        let here = this;
        let args = this.argInfo.posvals;
        let forward = this.anim.delta > 0;
        let reqKey = {movant:null};
        if (this.argInfo.keyvals.movant) {
            reqKey.movant = this.argInfo.keyvals.movant;
        }
        
        let hasArgs =  args.length > 0;
        if (forward && hasArgs) {
            // This follow command will likely shift the center.
            // Going backwards we need to shift back to the pervious origin (likely 0,0,0)
            let firstFollow = true;
            for (let prev=this.ptr.prev; prev.elem.command != 'START'; prev=prev.prev) {
                // If the previous follow command specified a target, then we don't need
                // to insert a 'center' command we'll just shift to the appropriate target.
                if (prev.elem.command.toLowerCase() == "follow"  && this.matchKeys(reqKey, prev.elem)) {
                    if (prev.elem.forward != null && prev.elem.forward.trim().length != 0) {
                        firstFollow = false;
                    } 
                    break;
                }
            }
            if (firstFollow) {
                let movant  = here.getMovant();
                let oldCent = movant.clone();                
                // Add in command to revert to current position when running backwards.                
                let revc = new Command(here.ptr.elem.t, "center", oldCent.x+" "+oldCent.y+" "+oldCent.z);
                revc.setGenerated(here);
                if (here.argInfo.keyvals.movant) {
                    revc.forward += " movant="+here.argInfo.keyvals.movant;
                }
                
                this.installRevert(revc);
            }
        }
        if (hasArgs) {

            // Find the closing follow.
            let tfinish = -1.e100;
            for (let next=this.ptr.next; next != null; next = next.next) {
                let cmd = next.elem.command;
                if (cmd == "END" || (cmd.toLowerCase() == "follow" && this.matchKeys(reqKey, next.elem))) {
                    tfinish = next.elem.t;
                    break;
                }
            }
            // Get the duration of the follow
            let delta = tfinish - this.ptr.elem.t;
            
            // Now find the object to follow.
            // The followbody callback will construct the approriate updater.
            function followBody(params) {
                let vec = here.getMovant();
                let nf = new Follower(here.anim, here.movant, vec, params.orbit, here.ptr.elem.t, delta, here.getZOffset());
            }
            
            this.getOrbit(here.anim.time, args, {}, followBody);
            
        } else if (!forward ) {
            this.executePrev(this.ptr, ["follow"], reqKey);
        } else {
            // Otherwise just let the updater expire.
        }
    }
}

export default follow;