// A trajectory undergoing constant (Newtonian) acceleration.
import Util from "../std/Util.js";
import Constants from "../std/Constants.js";
class Accel {            
    constructor(x0, v0, a, t0, update) {
        this.x0       = x0;           // Position at t0
        this.v0       = v0;           // Velocity at t0
        this.a        = a;            // Acceleration vector
        this.mag      = Util.mag(a);  // Magnitude of acceleration.
        this.t0       = t0;           // Reference time for start of acceleration.
        this.lastT    = t0;           // Time of last call
        this.update   = update;       // Routine to call to update total acceleration.
                                      //   F(timem acceleration)
        this.mass     = null;         // A central mass.
    }
    
    setMass(mass, tend) {
        this.mass = mass;
        this.tend = tend;
        console.log("In Accel.setMass:", mass, tend);
    }

    position(t) {
        // x = x0 + v0*dt + 1/2 a * dt*2 
        let dt = t - this.t0;
        let x      = Util.vadd(this.x0, this.v0, dt);

        if (this.update) {
            let f = this.a;
            if (t > this.t0  || (t < this.lastT && t == this.t0)) {
                // Add in the force we need to keep a constant acceleration
                // given the gravitational field.
                if (this.mass) {
                    
                    let mag = Util.mag(x);
                    // g = -GM r/}r|^3
                    let grav = Util.times(-Constants.G*this.mass/(mag*mag*mag), x);
                    // So the force we need to apply is actually a-g.
                    f = Util.diff(this.a, grav);
                }
                this.update(t, f);
            }
        }
        this.lastT = t;
        return Util.vadd(x, this.a, 0.5*dt*dt);
    }
    stateVector(t) {
        let dt = t-this.t0;
        return [this.position(t), Util.vadd(this.v0, this.a, dt)];
    }
}

export default Accel;