import hide from "./hide.js";

class show extends hide {

    constructor(ptr, anim, traj) {
        super(ptr, anim, traj);
    }
    
    // Run this as a hide, but going in the opposite direction in time.
    execute() {
        let forward = this.anim.delta > 0;
        this.execAs(forward);
    }
}

export default show;
    
