import Util from "../std/Util.js";

class Updater {
        
    static cnt          = 0;              // Used to create distinct names for each updater.
    static instances    = {};    // The quantity being updated
    
    // Create an object that will update another object in the animation.
    //     anim:      the animation the updater works within
    //     target:    the name of the vector being updated
    //     vector:    an element/vector to be updated
    //     start/duration: the interval for which the updater should be present in the animation.
    //     The action method should be replaced by whatever is intended to happen.

    constructor(anim, target, vector, start, duration) {
        
        this.anim     = anim;
        this.target   = target;
        this.vector   = vector
        this.start    = start;
        this.end      = start+duration;
        this.duration = duration;
        
        // Check to see if there is already something updating this target.
        // If so given the use a warning
        this.name     = "Updater_"+Updater.cnt;
        Updater.cnt += 1;
        if (!this.add(target) ) {
            throw new Error("Error adding updater for "+target);
        }        
        let here = this;
        let render = 
          function(time) {
            // Confirm that we are in the valid time range.
            if (here.start <= time && time < here.end) {
                // Yes.  Perform the desired action
                here.action(time);
            } else {
                // No. Remove the updater from the animation.
                here.remove(target);
            }
        };
        this.render = render;
    }
    
    // Add an updater for the given target.
    add(target) {
        if (Updater.instances[target]) {
            // Check if the existing instance should have expired already.
            // If so we can go ahead.
            if (!this.expired(target)) {
                return false;
            } else {
                this.remove(target);
            }            
        }
        Updater.instances[target] = this;
        this.anim.addElement(this.name, this, true);
        return true;
    }
    
    // Remove the updater
    remove(target) {
        if (!Updater.instances[target]) {
            Util.log("Warning: Attempt to remove updater for "+target+" when none exists");
        } else {
            this.anim.removeElement(this.name);
            delete Updater.instances[target];
        }
    }
    
    // See if the current updater for the given target is expired
    // so we should delete it before starting the next.
    expired(target) {
        let upd = Updater.instances[target];
        let t = this.anim.time;
        // We allow expiry so long as we are not inside
        // the limits of the interval.  It's ok to expiry and the start instant.
        if ((t > upd.start) && (t < upd.end )) {
            console.log("Failed to expire:", t, this.start, this.end, upd.start, upd.end);
            return false;
        } else {
            upd.remove(target);
            return true;
        }
    }
    
    action(time) {
        // This should be overriden to perform the action required during an update.
        // Normally this will update vec in some fashion.
        throw new Error("Updater with no content");
    }
}

export default Updater;