import Constants from "../std/Constants.js";
import Util from "../std/Util.js";

class TrojanOrbit {
    
    // Note that we use delegation rather than inheritance
    // to extend the QOrb class;
    
    /* Modify the orbit of Trojan and Hilda asteroids, so that they stay in
     * their respective clumps.  We assume that the angular velocity of the objects
     * changes in a sinusoidal pattern such that over some long period the average
     * angular velocity matches the apporpriate resonance frequency.  Note that
     * the current approach does not take into direct account the variation of
     * the angular velocity over the elliptical orbit.  This should ultimately average
     * out.  This is not a real solution, but since otherwise the Trojans and
     * Hilda's disperse over all angles, it is somewhat better than nothing and it
     * retains the qualitative appearance of the Trojans and Hildas.
     */
    
    
    // input:   The input base orbit at the given epoch.
    // epoch:   The epoch of the original orbital parameters.
    // primary: The orbit of the associated object (e.g., Jupiter)
    //          This is assumed to be fixed.
    // period:  The period of the added sinusoidal variation of the angular
    //          velocity.  Something of the order of a century seems reasonable.        
    // phase:   The phase (in radians) for the current oscillation.
    //          If the phase is incompatible with the current situation.
    //          (e.g, phase is pi/2 and the period is currently shorter than
    //          primary, then phase will be inverted.
    //          If the phase is given as 0, a random phase will be tried.
    // resonance:  desired ratio of angular velocities: 1/1 for trojans,  3/2 for Hildas.
    //          Defaults to 1.
    constructor(input, epoch, primary, period=0.00001*Constants.CENTURY, phase, resonance=1) {
        
        // If the user doesn't enter a phase, just pick a random number.
        if (!phase  || phase === 0) {
            phase = 2 * Math.PI * Math.random();
        }
        this.baseEpoch = epoch;
        // Sometimes we ask orbits for their radius...
        this.a = primary.a;  
        
        let leading = this.isLeading(input, primary, resonance, epoch);
        let fast    = this.isFast   (input, primary, resonance);
        
        // This makes sure we are in the right quadrant.
        phase   = this.matchPhase(phase, leading, fast);
        

        // Now make sure that we don't vary too much...
        const MAX_DELTA    = 0.03;
        let ratio    = (this.initialAngVel-this.primaryAngVel)/this.primaryAngVel;
        let absRatio = Math.abs(ratio);
        
        
        if (absRatio > MAX_DELTA) { 
            if (fast) {
                phase = Math.PI/2;
            } else {
                phase = 3*Math.PI/2;
            }
        } else if (Math.abs(absRatio/Math.sin(phase)) > MAX_DELTA) {
            phase = this.matchPhase(Math.asin(ratio/MAX_DELTA), leading, fast);
        }
        this.maxDev  = (this.initialAngVel - this.primaryAngVel)/Math.sin(phase);

        // We'll keep a copy of the original orbit here to delegate to
        this.delegate      = input.clone();
        this.primary       = primary;
        this.phasePeriod   = period;        
        this.baseEpoch     = epoch;
        this.orig          = input;
        
        let cbrt           = Math.cbrt(resonance);
        
        this.baseA         = this.primary.a/cbrt/cbrt;
        this.baseLm        = this.primary.Lm/cbrt;
        this.basePer       = this.primary.per/resonance;
        this.origA         = this.delegate.a;
        this.baseT0        = this.delegate.t0;
        this.phaseAtEpoch = phase;
        
        let phase0     = phase;
        let cosPhase0  = Math.cos(phase0);
        let maxDev     = this.maxDev;
        let ma0        = input.getMA(epoch);        
        
        // We get the mean anomaly directly rather than using the time of perihelion
        // since that's not really defined for this changing orbit.
        // Doubtless there's a simple formula that will correct it, but
        // we don't need it except to get the mean anomaly so why bother.
        
        function getMA(t) {
            let phase = phase0 + 2*Math.PI*(t-epoch)/period;
            
            let ma    = ma0 + resonance * 2*Math.PI*(t-epoch)/primary.per +
                          maxDev*period*(cosPhase0 - Math.cos(phase));
            return ma;
        }
        this.delegate.getMA = getMA;
        
        let posO = input.position(epoch);
        let posX = this.position(epoch);
        
    }
    // Find the phase with the same absolute magnitude
    // but the correct sign for the value and derivative.
    //   input   -- input phase
    //   leading -- should the negative cosine of the angle be positive?
    //   fast    -- should the derivative of the sine be positive.
    //   The derivative of the sine is our delta to the angular velocity
    //   which we could integrate (to the negative cosine) to get the
    //   lead we have over the resonance position.
    //   So leading means that we are ahead of the resonance, and
    //   fast means we are moving faster than the resonance.
    matchPhase(phase, leading, fast) {
        const PI = Math.PI;
        phase = phase % (2*PI);
        if (phase < 0) {
            phase += 2*PI;
        }
        // Get the correct phase for the velocity.
        if (fast && phase > PI) {
            phase -= PI;
        } else if (!fast && phase < PI ) {
            phase += PI;
        }
        if (fast) {
            if (!leading && phase > PI/2) {
                phase = PI - phase;
            } else if (leading && phase < PI/2) {
                phase = PI - phase;
            }
        } else {
            if (leading && phase > 3*PI/2) {
                phase = 3*PI - phase;
            } else if (!leading && phase < 3*PI/2) {
                phase = 3*PI - phase;
            }
        }

        return phase;
    }
    
    // Are we moving faster than the primary?
    isFast(input, primary, resonance) {
    
        // This is the desired average angular velocity
        this.primaryAngVel = 2*Math.PI/primary.per * resonance;        
        this.initialAngVel = 2*Math.PI/input.per;
        
        // Is the current angular velocity greater than the average needed?
        return  this.initialAngVel > this.primaryAngVel;
    }
    
    // Are we ahead of the resonance point?
    isLeading(input, primary, resonance, epoch) {
            // Compare the location to the centers of the groups.
        let posTroj = input.position(epoch);
        let posPrim = primary.position(epoch);
        
        let lonTroj = Math.atan2(posTroj[1], posTroj[0]);
        let lonPrim = Math.atan2(posPrim[1], posPrim[0]);
        
        let delta = lonTroj - lonPrim;
        
        // Put in the range -i to pi
        if (delta > Math.PI) {
            delta -= 2*Math.PI;
        }
        if (delta < -Math.PI) {
            delta += 2*Math.PI;
        }
        
        // We will calculate dev as the angle by which the
        // current position is leading or trailing the resonance point.
        // I.e., L4 or L5 for trojans and Hildas or a third point opposite the
        // primary for Hildas.  Not interested in the radius here, just the
        // difference in longitudes.
        let dev = 0;
        // Trojans and leading and trailing Hildas.  2 pi/3 = 120 degrees
        if (resonance == 1  || Math.abs(delta < 2*Math.PI/3)) {
            if (delta < 0) {
                dev = delta + Math.PI/3;
            } else {
                dev = delta - Math.PI/3;
            }
        } else {
            // Opposing Hildas.  -170 > 10 degrees leading, 170 -> 10 degrees trailing.
            if (Math.abs(delta) < 0) {
                dev += Math.PI;
            } else {
                dev -= Math.PI;
            }
        }
        return dev>0;
    }    

        
    position(t) {
        this.adjust(t);
        return this.delegate.position(t);
    }    
    stateVector(t) {
        this.adjust(t);
        return this.delegate.stateVector(t);
    }
    posTA(t) {
        this.adjust(t);
        this.delegate.posTA(t);
    }
    orbitXYZ(n,t) {
        if (t || t===0) {
            this.adjust(t);
        }
        return this.delegate.orbitXYZ(n,t);
    }
    
    // Using the calcuable phase of the variation,
    // adjust the period, semimajor axis and angular momentum of the
    // delegate.
    adjust(t) {
        let xpos        = null;
        let dt          = t - this.baseEpoch;
        let phase       = this.phaseAtEpoch + 
                          2*Math.PI* dt / this.phasePeriod;
        let angVel      = this.primaryAngVel + this.maxDev*Math.sin(phase);
        
        
        //  Just for amusement...
        //angVel = this.primaryAngVel;
        
        // Get the ratio of the average and current velocities.
        let m     = this.primaryAngVel/angVel;
        let cbrt  = Math.cbrt(m);
        // The period, semimajor axis and angular momentum all go as
        // powers of m.
        this.delegate.per  = this.basePer * m;
        this.delegate.a    = this.baseA   * cbrt*cbrt;
        this.delegate.Lm   = this.baseLm  * cbrt;
        
    }
}

export default TrojanOrbit;