import QOrb      from "../orbits/QOrb.js";
import OrbitPlot from "../solarsystem/OrbitPlot.js";
import Constants from "../std/Constants.js";
import Util      from "../std/Util.js";

class TrajOrbit extends OrbitPlot {
    
    constructor(cont) {
        super("Traj", cont.rockOrbit, 0x0000FF, cont.anim.time);
        this.cont        = cont;
        this.impTime     = null;
        this.lastImpulse = null;
        this.trajSeq     = cont.anim.frame.traj;
        this.lastImpulse = null;
    }
    
    render(t) {
        let imp      = this.cont.state.impulse;        
        let impMag   = Util.mag(imp);
        let diffImp  = !Util.arrEq(imp, this.lastImpulse);
        let animTime = this.cont.anim.time;
        let rocket = this.trajSeq.rocket;
        
        
        // We need to update the orbit if:
        //    -- we have applied a thrust since the last update
        //    -- we are stopped and the pending impulse has changed.
        //    -- we are moving and there is a pending impulse.  We use the current
        //       time for the pending impulse.
        //    -- an external user has requested an update by setting pulse -- probably due to an impulse command.
        if (rocket.orbChanging || rocket.orbChange  || diffImp  || (impMag && this.impTime != animTime)) {
            // Update to the new orbit
            let t = this.cont.anim.time;
            rocket.orbChange = false;
            let posAtt = this.geometry.getAttribute("position");
            let state  = this.cont.traj.lastState;
            let r = state[0];
            let v = state[1];
            let dv = this.cont.impXYZ();
            v = Util.vadd(v, dv);
            let newOrb = QOrb.stateOrbit({t:t, r: r, v: v});
            
            newOrb.scale = 1/Constants.AU;
            let newPos = newOrb.orbitXYZ(360, t);
            for (let i=0; i<360; i += 1) {
                let p = newPos[i];
                posAtt.setXYZ(i, p[0], p[1], p[2]);
            }
            posAtt.needsUpdate   = true;
            this.impTime         = animTime;
            this.lastImpulse     = imp;
            this.cont.impChanged = false;
            this.trajSeq.setTestOrbit(newOrb);
        }
    }
}


export default TrajOrbit;
