import MotionAction from "./MotionAction.js";
import Util from "../../std/Util.js";

class accel extends MotionAction {
    constructor(ptr, anim, traj) {
        super(ptr, anim, traj);
    }

    // Going forward initiate continuous acceleration in the direction specified.
    // Going backward go into the orbit/coast defined by the current state.
    doAction(delta, command, flds) {
        let mag  = parseFloat(flds[0]);
        let time = this.time;
        if (this.forced) {
            time = this.forceTime;
        }
        let av;
        let [xorig, vorig] = this.traj.rocket.stateVector(time);
        // Acceleration along velocity axis
        if (flds.length == 1) {
            let vn = Util.unit(vorig);
            let a  = parseFloat(flds[0])
            av = Util.times(a, vn);
            
            if (delta < 0) {
                let taccel = this.forceTime - this.time;
                let vmag  = Util.mag(vorig);
                if (a < 0  && (vmag < -taccel*a)) {
                    // Velocity flipped during acceleration.
                    av = Util.times(-1, av);  // So the direction of the acceleration is opposite the current velocity.
                }
                [xorig, vorig] = this.runBack(av, xorig, vorig);
            }

        } else if (flds.length == 3) {
            let ax = parseFloat(flds[0]);
            let ay = parseFloat(flds[1]);
            let az = parseFloat(flds[2]);
            av = [ax,ay,az];
            if (delta < 0) {
                let state = this.anim.frame.traj.rocket.stateVector(this.time);                
                [xorig, vorig] = this.runBack(av, xorig, vorig);
            }
        } else {
            throw new Error("Illegal Accel command: "+this.elem.toString());
        }
        this.traj.rocket.setToAccel(time, this.time, av, xorig, vorig);
        if (this.args.keyvals.withgrav) {
            // Get the end time for the acceleration...
            let tend = this.args.keyvals.tend;
            // Get the UpdatingTraj...
            let traj = this.traj.rocket.traj;            
            let mass = traj.primaryMass();
            console.log("The mass is:", mass);
            let ltraj = traj.localTraj();  // This should be a new Accel.
            ltraj.setMass(mass, tend);     // Send it the central mass so that
                                           // we can compute the gravitational force.
        }
    }
    
    // Find the position and velocity at the beginning of the acceleration.
    runBack(av, xorig, vorig) {
        let delta = this.forceTime - this.time;
        
        // Get the original velocity and position
        vorig = Util.vadd(vorig, av,    -delta);        
        xorig = Util.vadd(xorig, vorig, -delta);
        xorig = Util.vadd(xorig, av,    -0.5*delta*delta);
        return [xorig, vorig];
    }
}

export default accel;

