
import {Component}   from "react";
import SolarPlanets  from "../solarsystem/SolarPlanets.js";
import Equinoctial   from "../orbits/Equinoctial.js";
import Trans         from "../traj/Trans.js";
import Util          from "../std/Util.js";
import Constants     from "../std/Constants.js";
import Burn          from "../orbits/Burn.js";
import Feather       from "../math/Feather.js";

class TrajTest extends Component {
    render() {
        console.log("In TrajTest here.");
        console.log("Solar Accel:", Constants.GMSun/(Constants.AU/Constants.AU));
        let eorb = SolarPlanets.getOrbit("Earth", 0);
        let morb = SolarPlanets.getOrbit("Mars", 0);
        let t0 = 0;
        let dt = 1.e6;
        let nStep = 1000;
        for (let i=0; i<10; i += 1) {
            let dv = 0;
            let inc = dt/nStep;
            let brn = new Burn(eorb, morb, t0, t0+dt);
            for (let j=0; j<nStep; j += 1) {
                let t   = t0 + (j+0.5)*inc;
                let pos = brn.position(t);
                let f   = brn.accel(t, pos);
                let mag = Util.mag(f);
                dv     += mag*inc;
                console.log("i, j, t, fm, dv:", i, j, t, mag, dv);
            }        
            dt *= 10;
        }

        return <div></div>;
    }
}
export default TrajTest;