
// Globular clusters source
// https://spider.seds.org/spider/MWGC/mwgc.html
// Milky way companions:
// https://iopscience.iop.org/article/10.1088/0004-6256/144/1/4
// Pulsars: ATNF Pulsar catalog
// HII: Wise HII catalog v 2.3

import Util from      "../std/Util.js";
import Constants from "../std/Constants.js";
import Coords    from "../std/Coords.js";

import Animation from "../elems/Animation.js";

// Data inputs
import globClust from "../data/GlobularClusters.js";
import pulsars   from "../data/Pulsars.js";
import hii       from "../data/hii.js";
import mwsats    from "../data/mwsatellites.js";

import {Color, BufferGeometry, AdditiveBlending, DoubleSide,
        PointsMaterial, Float32BufferAttribute, Vector3,
        RingGeometry} from "three";
import AngPoints from "../three/AngPoints.js";


import {Scene, MeshBasicMaterial, 
        SphereGeometry, Euler,
        Mesh} from "three";

class Galaxy extends Animation {
    constructor(params) {
        super(params);
        
        this.delta     = Constants.CENTURY/10;
        this.paused    = true;
        this.time      = 0;
        this.name      = "The Milky Way"; 
        this.primeChild = "Local Galactic Neighborhood";
        this.longClickTime = 1500;  // A little shorter since
                                    // we do less clicking here.

        this.scene       = new Scene();
        // Distances in kiloparsecs.
        this.sceneScale  = 1000*Constants.PC;
        this.textShowing = true;
        this.centerBody  = "Solar Neighborhood";
        this.coordSystem = Coords.getCoords("ecgal");
        
        this.cameraPos = new Vector3(8.77,0,30);
        this.cameraRot = new Euler(0,0,0,"XYZ");
        this.frame.camera.lookAt(8.77,0,0);
        
        this.baseAnimation = "Nearby Galaxies";
        this.sceneCoord = "Ga";
        
        this.minScale = 18.79;
        this.maxScale = 21.8;
        this.biggest  = false;        
        this.rGal  = 8.0;  // kpc
        
        // Add the elements we show in the Galaxy.        
        this.addGCs();
        this.addSats();
        this.addPulsars();
        this.addHII();
        this.addGalCen();
        this.filledSphere([8,0,0], 1, 300, 0xAAAAFF, 1);
        this.addTimeDisplay(); 
        this.finish();
    }
    
    // Get the x,y,z coordinates give the decimal RA (in hours)/Dec (in degrees)
    // and the distance in kiloparsecs.   An optional coordinate transformation may be provided.
    getXYZ(ra, dec, r, csys) {
        const rar  = Util.toRadians(15*ra);
        const decr = Util.toRadians(dec);
         
        let [l,b] = [rar, decr];
        if (csys) {
            [l, b] = csys.transform(rar,decr);
        }
        let xyz = [r*Math.cos(l)*Math.cos(b), r*Math.sin(l)*Math.cos(b),r*Math.sin(b)];  
        return xyz;
    }
    
    filledSphere(x, r, n, color, zscale=1, opac=1) {
        const material = new MeshBasicMaterial(
          {color: color,
           side: DoubleSide,
           wireframe: false, 
           blending: AdditiveBlending,
           transparent: true, 
           depthWrite: false,
           opacity: opac/n});

        
        for (let i=0; i <= n; i += 1) {
            const logrs = (i-n/2)*2.5/n;
            const rs = r*Math.pow(10, logrs);
            let sphere = new SphereGeometry(rs, 15, 15);
            let sph = new Mesh(sphere, material);
            sph.position.set(8,0,0);
            this.scene.add(sph);             
        }        
    }
    
    addGalCen() {
        const red      = new MeshBasicMaterial({color:0xFF00FF, wireframe: false});
        const yellow   = new MeshBasicMaterial({color: 0x333300, wireframe: false, transparent: true, opacity: 0.5, depthWrite: false, blending: AdditiveBlending});
        const geometry = new SphereGeometry(.2, 20, 20); // 200 pc radius, unscaled.
        const galcen   = new Mesh(geometry, red);
        galcen.meta    = {name:"Galactic Center", type: "Region"};
        galcen.position.set(this.rGal,0,0);
        this.addElement (
               "GalCen", 
               {name: "GalCen", component: galcen}
        );
        const solngh     = new Mesh(geometry, yellow);
        solngh.renderOrder = 1;
        solngh.meta = {name:"Solar Neighborhood", type: "Region"};
        solngh.scale.set(0.5,0.5,0.5);
        this.addElement(
                "SolarNeighborhood", {name: "Solar Neighborhood", component: solngh}
        );
    }
    
    addGCs() {
        const clusters    = globClust;
        const csys        = Coords.getCoords("eqgal");
                
        const globFac = 2;  // Make globulars this many times lareger than they really are.
        const saveQuiet = this.quiet;
        this.quiet = true;
        let lyToPc = Constants.LY/Constants.PC;
        for (let i=0; i<clusters.length; i += 1) {
            let clust = clusters[i];

            let r = clust.rsun * lyToPc;  // Convert from light years to parsecs.
            let scale = 0.5;
            let size  = globFac * r*clust.size * 1/60. * Math.PI/180;   // gives size in kpc
            let surf  = Math.pow(2.512, 4.83-clust.absmag)/ (size*size); // Surface brightness in L_sun/kpc^2
            
            let trans = 2*(Math.log10(surf) - 0.4);
            if (trans > 0.8) {
                trans = 0.8;
            } else if (trans < 0.2) {
                trans = 0.2;
            }
            
            let [x,y,z] = this.getXYZ(clust.ra, clust.dec, r, csys);
            // Get the angle between the cluster and the galactic center.
                        
            const material    = new MeshBasicMaterial(
                {transparent: true, 
                 blending: AdditiveBlending,
                 depthWrite: false,
                 opacity: 0.4,
                 color: 0xFF0000, 
                 wireframe: false}
            );
            if (size < 0.05) {
                size = 0.05;
            }
            const geometry    = new SphereGeometry(size, 20, 20);
            const sphere      = new Mesh(geometry, material);
            sphere.meta       = {...clust};
            sphere.meta.type  = "Globular";
            
            sphere.position.set(x,y,z);
            this.addElement (
               clust.name, 
               {name: clust.name, component: sphere}
            );
        }
        this.quiet = saveQuiet;
        this.bodyCount += clusters.length;
        Util.log("Added "+clusters.length+" globular clusters to "+this.name);
    }
    
    addSats() {
        const data  = mwsats;
        const csys  = Coords.getCoords("eqgal");
                
        const saveQuiet = this.quiet;
        this.quiet = true;
        for (let i=0; i<data.length; i += 1) {
            let sat = data[i];

            let size  = sat.size/1000;
            if (size < 0.1) {
                size = 0.1;
            }
            
            let [x,y,z] = this.getXYZ(sat.ra/15, sat.dec, sat.dist, csys);
            const material    = new MeshBasicMaterial(
                {transparent: true, 
                 blending: AdditiveBlending,
                 opacity: .4, 
                 color: 0x00AAFF,
                 depthWrite: false,
                 wireframe: false}
           );
            const geometry    = new SphereGeometry(size, 20, 20);
            const sphere      = new Mesh(geometry, material);
            sphere.meta       = {...sat};
            sphere.meta.type  = "Sat. Galaxy";
            
            sphere.position.set(x,y,z);
            this.addElement (
               sat.name, 
               {name: sat.name, component: sphere}
            );
        }
        this.quiet = saveQuiet;
        this.bodyCount += data.length;
        Util.log("Added "+data.length+" satellite galaxies to "+this.name);
    }
    
    find(name, callback) {
        this.frame.finder.getLocation(name, null, "something", callback);
    }
    
    doLongClick(e) {
        const matched = this.frame.raycast(e);
        
        for (let i=0; i<matched.length; i += 1) {
            let entry = matched[i];
            let name = entry.meta.name;
            if (entry.meta.name == "Solar Neighborhood") {                
                this.setAnim("Local Galactic Neighborhood");
                return;
            }
        }
        super.doLongClick(e);
    }
    
    
    getPositions(data) {
        const px = [];
        const csys        = Coords.getCoords("eqgal");
        
        for (var i=0; i<data.length; i += 1) {
            let datum = data[i];
            let x,y,z;
            if (datum.l  || datum.b) {
                [x,y,z] = this.getXYZ(datum.l, datum.b, datum.d);                
            } else {
                [x,y,z] = this.getXYZ(datum.ra, datum.dec, datum.rsun, csys);
            }
            px.push(x,y,z);
        }
        return new Float32BufferAttribute(px,3);
    }
    
    getColors(data) {  
        const colors = [];
        let base = [0.6, 1.0, 0.6];
        if (data[0].l || data[0].g) {
            base = [0.3, 0.6, 1.0];
        }
        for (var i=0; i < data.length; i += 1) {
            colors.push(base[0], base[1], base[2]);            
        }
        return new Float32BufferAttribute( colors, 3 );
    }
    
    addHII() {
        const geometry = new BufferGeometry();
        geometry.setAttribute('position', this.getPositions(hii));
        geometry.setAttribute('color', this.getColors(hii));
        const material       = new PointsMaterial( {sizeAttenuation: false, size: 2, vertexColors: true } );
        const points         = new AngPoints(geometry, material );
        points.getIndexedMeta = function(index) {
            const meta = {...hii[index]};
            meta.type = "HII region";
            return meta;
        }
        let elem = {
            component: points,
        };
        this.addElement("hiiregions", elem);
        Util.log("Added "+hii.length+" HII regions");
    }
    addPulsars() {


        const geometry = new BufferGeometry(); 
        // Should the time here be 0?
        geometry.setAttribute( 'position', this.getPositions(pulsars));
        geometry.setAttribute( 'color',    this.getColors(pulsars));
        
        const material       = new PointsMaterial( {sizeAttenuation: false, size: 2, vertexColors: true } );
        const points         = new AngPoints(geometry, material );
        points.getIndexedMeta = function(index) {
            const meta = {...pulsars[index]};
            meta.type = "Pulsar";
            return meta;
        }
    
        let count = 0;
        let nmid = pulsars.length / 2;
        
        let starts = [0, 0, nmid];
        let ns     = [pulsars.length, nmid, pulsars.length-nmid];
        let ilast  = -1; 
        
        let elem = {
            component: points,
            render:
               function(time) {
                   let i = (count/20) % 3;
                   if (i != ilast) {
                       geometry.setDrawRange(starts[i], ns[i]);
                    }
                }
        };
        this.addElement("pulsars", elem);
    };
}

export default Galaxy;