// The constraints that the each particle must satisfy.
// Two types of constraints are supported:
//   A given parameter must be less than another parameter.
//   A given parameter must be in a specified range.
class Constraints {
    constructor() {
        this.smaller = [];
        this.limits  = [];
    }
    
    // Require that parameter i be less than parameter j
    addSmaller(i, j) {
        this.smaller.push([i,j]);
    }
    
    // Require that parameter i be between the values min and max, enclusive.  Min < max.
    addLimits(i, min, max) {
        this.limits.push([i, min, max]);
    }
    
    // Check a particle against the constraints.
    test(part) {
        for (let i=0; i<this.smaller.length; i += 1) {
            let [a,b] = this.smaller[i];
            if (part[a] > part[b]) {
                return false;
            }
        }
        for (let i=0; i<this.limits.length; i += 1) {
            let [a,min,max] = this.limits[i];
            let val = part[a];
            if (val < min || val > max) {
                return false;
            }
        }
        return true;
    }
    
}

export default Constraints;