import Util from "../std/Util.js";
import TimeFormatter from "../elems/TimeFormatter.js";
import Acts from "./actions/Acts.js";

class Command {
    constructor(time, command, forward) {
        // The instant the command should happen/start (going forward)
        this.t = time;
        
        // The keyword defining the command.
        this.command = command.toLowerCase();   
        
        // The arguments to the command when moving forward.
        this.forward    = forward;
        // Was this command generated by another
        this.generated  = false;
        // Was this command last executed going forward (1) or back (-1)
        this.direction  = 0;
    }
    
    setGenerated(parent) {
        // Structure with ptr to sequence
        if (parent.ptr) {
            this.generated = parent.ptr.elem;
        //  ... or pointer
        } else if (parent.elem) {
            this.generated = parent.elem;
        //  ... or the command itself
        } else if (parent.command) {
            this.generated = parent;
        } else {
            Util.log("Call to Command.setGenerated with unrecognized structure");
        }
    }
    
    // ptr  -- Pointer to the current command in the trajectory sequence.
    //         This also has pointers to the previous and subsequent commands.
    // anim -- The current animation.
    // traj -- The trajectory controller.
    static enact(ptr, anim, traj) {
        let cmd = ptr.elem.command;
        let dir = anim.delta > 0;
        let gen = ptr.elem.generated !== false;
        let chra = dir ? ">" : "<";
        let chrb = gen? "+" : ".";
        Util.log("Cmd" + chra + chrb+"-  "+ptr.elem.t+": "+ptr.elem.command+" "+ptr.elem.forward);
        
        try {
            Command.getAction(cmd, ptr, anim, traj).exec();
        } catch (exc) {
            Util.log("Caught exception running command: ",cmd, " -- ", exc);
            console.error("Error log is:", exc.stack)
            anim.setQuickHTML("Unable to execute command: "+cmd);
        }
    }
    
    static getAction(cmd, ptr, anim, traj) {
        let Aclass = Acts[cmd];
        return new Aclass(ptr, anim, traj);
    }
        
    toString(seconds) {
        if (seconds == null) {
            seconds = false;
        }
        let tf = new TimeFormatter();
        
        let time = this.t;
        if (!seconds) {
            time = tf.dateFormat(this.t, 1);
            time = time.replace("T00:00:00","");
        }
        let res = time + " "+this.command;
        if (this.forward) {
            res += " "+this.forward;
        }
        if (this.generated) {
            return "#GEN "+res;
        } else {
            return res;
        }
    }
}

export default Command;