import Rocket     from "../components/Rocket.js";
import Constants  from "../std/Constants.js";
import Command    from "../trajanim/Command.js";

import Integrator from "../math/Integrator.js";
import QOrb       from "../orbits/QOrb.js";
import Rotation   from "../orbits/Rotation.js";
import Epicycle   from "../orbits/Epicycle.js";
import Coast      from "../orbits/Coast.js";
import Accel      from "../orbits/Accel.js";
import UpdatingTraj from "../traj/UpdatingTraj.js";

import MotionAction from "../trajanim/actions/MotionAction.js";
import SolarSystem from "../animations/SolarSystem.js";

import Util from "../std/Util.js";
import {Euler} from "three";

class TravellingRocket {
    
    constructor(args) {       
        if (args.name) {
            this.name = args.name;            
        } else {
            this.name = "MyRocket";
        }
        
        this.anim    = args.anim;
        this.gravity = true;
        this.trajSeq = this.anim.frame.traj;
        this.orbChanging     = false;
        this.orbChange       = false;
        this.firstCall       = true;
        
        // The initial orbit.
        this.traj = new UpdatingTraj();
        if (args.traj) {
            this.traj.updTraj(args.traj, null);
        }
        this.thrusting = false;
        
        // Vector of last thrust
        this.lastThrust = null;
        
        // Total impulse.
        this.totalDV    = 0;
        this.totalTime  = 0;
        this.scale      = this.anim.sceneScale;
        this.accCount   = 0;
        
        this.trialCount = 0;
        this.updFunc   = this.updateDV.bind(this);
        this.minA = 1.e10;
        this.maxA = -1.e10;
    }
    
    
    // Initiate thrust.  We don't
    // worry about adding a new interval here, because
    // that should be handled in the accel and integrator objects
    // when they see the gap from the last thrust time.
    startThrust(t, mag) {
        let forward         = this.anim.delta > 0;
        this.thrusting      = true;
        this.lastThrustMag  = mag;
        this.lastThrustTime = t;
    }
    
    stopThrust(t) {
        
        // See if we need to worry about a last bit of thrust.
        if (!this.thrusting  || t == this.lastThrustTime) {
            this.thrusting = false;
            this.lastThrustTime = null;
            return;
        }
        
        let forward = this.anim.delta > 0;
         if ((forward && t > this.lastThrustTime) ||
                         t < this.lastThrustTime) {
            // We need to account for a little bit of extra time.
            this.updateDV(t, this.lastThrust);
        }
        this.thrusting      = false;
        this.lastThrustMag  = 0;
        this.lastThrustTime = null;
        this.lastThrust     = null;
    }
    
    getImpulse() {
        return this.totalDV;
    }
    
    setAnimation(anim) {
        this.anim = anim;
    }
    
    setRocketControl(rc) {
        this.cont = rc;
    }
        
    // Set the trajectory to be an accelerating trajectory simulataneously
    // subject to gravity from a central body.
    setToIntegrate(time, force) {
        this.orbChanging = true;
        this.lastThrust = null;
        this.gravity = true;
                
        let lastState = this.traj.stateVector(time);
        this.startThrust(time, force.magnitude());
        let dt = Math.abs(this.anim.delta/3);
        this.traj.updLocal(new Integrator(force, lastState[0], lastState[1], time, dt, this.updateDV.bind(this)), time);
    }
    
    // Have the rocket rest on the surface of the primary at the given longitude and latitude.
    setToRest(t, primary, pLon, pLat) {
        let data = SolarSystem.getTrackedObject(primary);
        if (!data || !data.radius || !data.rotation.rotationPeriod) {
           throw new Error("Inadequate data to land on:"+name);
        }
                        
        let rotation = new Rotation(primary, pLon, pLat);
        if (this.traj.traj) {
            let entryState = this.traj.localStateVector(t);
            rotation.setEntry({time:t, state:entryState});
        }
        let orbit = new Epicycle(data.orbit, rotation, primary);
        orbit.primaryName = primary;        
        
        if (this.traj.traj != null) {
            // Compare the position defined by the rest request with the current
            // state
            let oldState = this.traj.stateVector(t);
            let newState = orbit.stateVector(t);
            let dr = Util.mag(Util.diff(oldState[0], newState[0]));
            let dv = Util.mag(Util.diff(oldState[1], newState[1]));
            let drs = (dr/1000).toFixed(2)+ " km";
            let dvs = (dv).toFixed(2) + " m/s";
            if (dr > 100000 || dv > 100) {
                this.anim.setQuickHTML(" Jump at landing: "+drs+ "  "+dvs);
            }
        }
        this.traj.updTraj(orbit, t);
    }
    
    // Set the trajectory to be a free orbit around a central body.
    setToOrbit(time, lastState) {
        this.orbChanging = false;
        this.gravity = true;
        // Create an orbit using the current state vector.
        if (lastState == null) {
            lastState = this.traj.stateVector(time);
        }
        
        // Currently only solar orbits.
        let str = {t: time, r: lastState[0], v: lastState[1], M: Constants.MSun};
        let orb = QOrb.makeOrbit(str);
        orb.scale = 1/this.scale;
        this.traj.updTraj(orb, time);
        this.stopThrust(time);
    }
    
    // Set the trajectory to be a constant velocity trajectory using the current velocity
    // [No gravity]
    setToCoast(time, params) {
        this.gravity = false;
        this.orbChanging = true;
        let v  = params.v;
        let x0 = params.r;
        let t0 = params.t;
        
        this.traj.updTraj(new Coast(x0, v, t0), time);
        this.stopThrust(time);
    }
    
    // Set the trajectory to a constant acceleration (currently Newtonian)
    // No gravity assumed.
    //   time     -- time the transition is happening
    //   refTime  -- time associated with xorig, vorig (sames as time when moving forward)
    //   force    -- acceleration vector
    //   xorig    -- position at reference time
    //   vorig    -- velocity at reference time.
    setToAccel(time, refTime, force, xorig, vorig) {
        this.gravity = false;
        this.orbChanging = true;
        let lastState = this.traj.stateVector(time);
        let baseTraj = this;
        let here = this;
        let mag = Util.mag(force);
        this.lastThrust = force;
        let accel = new Accel(xorig, vorig, force, refTime, this.updFunc);
        this.startThrust(time, mag);
        this.traj.updTraj(accel, time);        
    } 
    
    // Add an instantaneous impulse to the existing orbit.
    // (or conceivably at the end of a thrusting period but
    // this will turn off the thrust).
    addImpulse(dv, time) {
        this.addJumpOrImpulse(dv, time, 1);
    }
    
    // Add an instantaneous jump to an existing orbit or coast.
    addJump(dx, time) {
        this.addJumpOrImpulse(dx, time, 0);
    }
    
    // These basically differ in whether
    // we are incrementing the first or second element of the state vector.
    addJumpOrImpulse(delt, time, index) {
        
        let sign  =  1;
        if (this.anim.delta < 0) {
            sign  = -1;
        }
        // Get the state vector for the current orbit, add the
        // delta, and then calculate the orbit associated with
        // the updated state vectory.
        let lastState = this.traj.localStateVector(time);
        let here = this;
        
        let r = lastState[0];
        let v = lastState[1];
        
        let str  = {t: time, r: r, v: v, M: this.traj.primaryMass()};
        lastState[index] = Util.vadd(lastState[index], delt, sign);
        
        if (index == 0) {
            str.r = lastState[0];
        } else {
            str.v = lastState[1];
        }
        
        
        // Get a new orbit from the updated state vector.
        let orb = QOrb.stateOrbit(str);
        this.traj.updLocal(orb, time);
        this.lastState = [str.r, str.v];
        
        let [tr,tv] = this.traj.localStateVector(time);
        this.orbChange = true;

        // Can't assess cost of jumps since they are unphysical.
        if (index == 1) {
            this.thrusting = false;        
            let mag        = Util.mag(delt);
            this.updateDV(sign*mag);
            this.accCount += 1;
        }
                
       
        // If we are just coasting before the impulse, go back to that.
        // If we are going forward, then the gravity flag is used, but if we are going
        // backwards, then we need to look earlier in the sequence for
        // the next previous orbit/thrust or coast/accel command
        if ( (sign ==  1 && !this.gravity)  ||
             (sign == -1 && !this.hadGravity(time) ))  {
            this.setToCoast(time);
        } else if (sign == -1) {
            let cmd = this.prevCmd.elem.command;
            // If the last motion command was a rest, and there are
            // no impulses before this one, then we should rest on the planet.
            if (cmd == "rest" && this.nimps == 0) {
                Command.getAction(cmd, this.prevCmd, this.anim, this.trajSeq).exec(true, time);
            }
        } 
    }
    
    // Can be called with just a single argument
    //   updateDV(delta) or
    //   updateDV(t, a)
    updateDV(t, a) {
        if (a == null) {
            this.totalDV += t;
        } else {
            let mag             = Util.mag(a);
            if (mag > this.maxA) {
                this.maxA = mag;
                console.log("Maximum thrust:", mag);
            }
            if (mag < this.minA) {
                this.minA = mag;
//                console.log("Minimum thrust:", mag);
            }
            let dt              = t - this.lastThrustTime;
            if (dt) {
                this.totalDV       += mag*dt;
                this.lastThrustTime = t;
                this.lastThrust     = a;
                this.totalTime     += dt;
            }
        }
    }
    
    hadGravity(time) {
        this.nimps   = 0;
        this.prevCmd = null;
        // Working backwards from the current command do 
        // we hit a non-gravity command before a gravity command.
        let seq = this.trajSeq.sequence;
        let curr = seq.first;
        // We assume that there is only a single impulse at the current time,
        // but there might be other commands that execute at the same instant,
        // so this should break at the current impulse.
        while (curr.elem.t < time  || (curr.elem.command != "impulse"  && curr.elem.command != "jump")) {
            curr = curr.next;
        }
        
        let grav = MotionAction.gravityCommands;
        // Don't test the current impulse...
        curr = curr.prev;
        do {
            let cmd = curr.elem.command;
            if (grav.hasOwnProperty(cmd)) {
                this.prevCmd = curr;
                return grav[cmd];
            } else if (cmd == "impulse") {
                this.nimps += 1;
            }
            
            curr = curr.prev;
        } while (curr.prev != null);
        // Should never get here.
        throw new Error("Unable to find motion or rest command previous to Jump/Impulse");
    }
    
    position(t) {
        return this.traj.position(t);
    }
    stateVector(t) {
        return this.traj.stateVector(t);
    }
    
    setRocketController(cont) {
        this.controller = cont;
    }
    
    update(t) {          

        // Note that state should return the position of the rocket in heliocentric
        // ecliptic coordinates regardless of the initial and current animation.
        let state = this.stateVector(t);

        // This should return the offset and motion of the current animation.
        let offset = this.anim.center(t);        

        // Get the position and velocity in the frame of the current animation.
        let x = Util.diff(state[0], offset[0]);            
        let v = Util.diff(state[1], offset[1]);

        // Update the current orbit in case we want to compare to a destination.
        if (this.orbChange || this.orbChanging) {
            // This bit of the program seems to be a bit out of date...
            // we should just be tracking the travelling rocket trajectory regardless.
            // So we'd just need to set this up during the Travelling rocket initialization.
            // The displayed orbit needs to be recalculated if it is changing
            // of course,
            // but maybe we are forgetting something we ran into when we were
            // trying out the OrbCompare code.  May need to revist this later.
            this.trajSeq.setTestOrbit(this.traj);
            // If we are displaying the orbit, we defer to other elements
            // of the program.
            if (!this.anim.sceneElements["TrajOrb"]) {
                this.orbChange = false;
            }
        }

        let att;
        if (this.thrusting && this.lastThrust) {
            att = this.lastThrust;
        } else if (this.rocketControl) {
            // Get correct orientation.
            let v3 = this.rocketControl.vAbs;
            att = [v3.x, v3.y, v3.z];

        } else {
            att = v;
        }
        
        

        // Change from ecliptic coordinates to the current
        // system for the current animation to whatever the local system is.
        let trns = this.anim.orientation();            
        att = trns.vTransform(att);
        let xx = trns.vTransform(x);


        // Point in direction of acceleration or velocity.
        let vnorm = Util.unit(att);
        let b = Math.asin(vnorm[2]);
        let l = Math.atan2(vnorm[1], vnorm[0]);
        this.icon.Mfire.visible = this.thrusting;
        let scale = this.anim.sceneScale;
        let pos = Util.times(1/scale, xx);
        
        this.icon.position.set(pos[0], pos[1], pos[2]);

        // If we are onground and we are in the appropriate animation,
        // then display the rocket on the surface of the object.
        if (this.traj.traj.onGround) {
            if (this.traj.traj.onGround == this.anim.name.toLowerCase()) {                
                let offset = this.traj.traj.sec.position(t);
                let [u,v,w]   = trns.vTransform(offset);
                l = Math.atan2(v,u);
                b = Math.asin(w/Math.sqrt(u*u + v*v));            
                this.icon.position.set(1.1*pos[0], 1.1*pos[1], 1.1*pos[2]);
            }            
        }
        // Remember that the arguments to the Euler constructor
        // are in XYZ order, not the order of rotation.

        this.icon.setRotationFromEuler(new Euler(Math.PI/2-b, 0, Math.PI/2+l, "ZYX"));
    }

    setTraveller() {
        let here = this;
        let myRocket = new Rocket({name: this.name, height: 0.15});
        this.icon = myRocket;
        myRocket.meta.traj = this.traj;

        this.comp =   
           {name:      "MyRocket", 
            component: myRocket, 
            render:    this.update.bind(this)
        };
    }
    
    getTraveller() {
        return this.traveller;
    }
}

export default TravellingRocket;
